#include <iostream>
#include <memory>
#include <string>
#include <utility>

class Monster {
public:
    explicit Monster(std::string name) : name_(std::move(name)) {
        std::cout << name_ << " spawned\n";
    }
    ~Monster() { std::cout << name_ << " destroyed\n"; }

    void SetTarget(std::shared_ptr<Monster> target) { target_ = std::move(target); }

    void Attack() const {
        std::cout << name_ << " attacks " << target_->name_ << "\n";
    }

private:
    std::string name_;
    std::shared_ptr<Monster> target_;
};

void RunBattle() {
    auto orc = std::make_shared<Monster>("Orc");
    auto knight = std::make_shared<Monster>("Knight");

    orc->SetTarget(knight);
    knight->SetTarget(orc);

    orc->Attack();
    knight->Attack();
    std::cout << "battle end\n";
}

int main() {
    RunBattle();
    std::cout << "back to lobby\n";
    return 0;
}

