#include <iostream>
#include <memory>
#include <string>
#include <utility>

class Monster {
public:
    explicit Monster(std::string name) : name_(std::move(name)) {
        std::cout << name_ << " spawned\n";
    }
    ~Monster() { std::cout << name_ << " destroyed\n"; }

    // Observe the target only: no ownership, so no reference cycle.
    void SetTarget(const std::shared_ptr<Monster>& target) { target_ = target; }

    void Attack() const {
        // lock() yields an owning shared_ptr, or an empty one if the target is gone.
        if (std::shared_ptr<Monster> target = target_.lock()) {
            std::cout << name_ << " attacks " << target->name_ << "\n";
        } else {
            std::cout << name_ << " has no valid target\n";
        }
    }

private:
    std::string name_;
    std::weak_ptr<Monster> target_;
};

void RunBattle() {
    auto orc = std::make_shared<Monster>("Orc");
    auto knight = std::make_shared<Monster>("Knight");

    orc->SetTarget(knight);
    knight->SetTarget(orc);

    orc->Attack();
    knight->Attack();

    knight.reset();   // Knight dies mid-battle: destroyed right here
    orc->Attack();    // expired target is handled, no dangling access
    std::cout << "battle end\n";
}   // Orc destroyed here

int main() {
    RunBattle();
    std::cout << "back to lobby\n";
    return 0;
}

