    for (int i = 2; i <= 60; ++i) mgr.Spawn(i, 50, "Grunt");
    if (!turret.Fire(30)) return "증원 후 살아 있는 타겟에 Fire가 false를 반환함";
    int hp = 0;
    if (!HpOf(mgr, 1, hp)) return "타겟(id 1)이 사라짐";
    if (hp != 70) return "증원(Spawn 59회) 후 Fire(30): 타겟 hp 기대 70, 결과 " + Num(hp) + " (재할당 전 주소에 기록했을 가능성)";
    return "";
}

std::string RandomVsReference() {
    EnemyManager mgr;
    Turret turret(mgr);
    std::map<int, int> ref;  // id -> hp
    bool locked = false;
    int lockedId = 0;
    int nextId = 1;
    unsigned seed = 20261122u;
    for (int step = 0; step < 400; ++step) {
        seed = seed * 1664525u + 1013904223u;
        const unsigned r = (seed >> 16) % 100;
        seed = seed * 1664525u + 1013904223u;
        const int pick = static_cast<int>((seed >> 16) % static_cast<unsigned>(nextId + 1));
        if (r < 35) {
            mgr.Spawn(nextId, 100, "Mob");
            ref[nextId] = 100;
            ++nextId;
        } else if (r < 50) {
            const bool expect = ref.erase(pick) > 0;
            if (mgr.Kill(pick) != expect) return "step " + Num(step) + ": Kill(" + Num(pick) + ") 반환값이 기대와 다름";
        } else if (r < 65) {
            const bool expect = ref.count(pick) > 0;
            if (turret.LockOn(pick) != expect) return "step " + Num(step) + ": LockOn(" + Num(pick) + ") 반환값이 기대와 다름";
            locked = expect;
            lockedId = pick;
        } else {
            const bool expect = locked && ref.count(lockedId) > 0;
            if (expect) ref[lockedId] -= 3; else locked = false;
            if (turret.Fire(3) != expect)
                return "step " + Num(step) + ": Fire 반환값 기대 " + (expect ? "true" : "false") + " (타겟 id " + Num(lockedId) + ")";
        }
        if (mgr.Count() != ref.size()) return "step " + Num(step) + ": Count 기대 " + Num((long long)ref.size()) + ", 결과 " + Num((long long)mgr.Count());
    }
    for (std::map<int, int>::const_iterator it = ref.begin(); it != ref.end(); ++it) {
        int hp = 0;
        if (!HpOf(mgr, it->first, hp)) return "id " + Num(it->first) + "가 사라짐";
        if (hp != it->second) return "id " + Num(it->first) + "의 hp 기대 " + Num(it->second) + ", 결과 " + Num(hp);
    }
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    LabelByValue, LockOnMissing, FireHitsTarget, BossWaveNoMinions,
    KillThenFire, BossWaveEnrage, LockSurvivesReinforcements, RandomVsReference,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);
    judge_heap::g_quarantine = true;

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

