#include <utility>

// ---- Fake C-style graphics API (do not modify: the hidden tests read it) ----
namespace gfx {
const int kMaxTextures = 1024;
inline bool g_alive[kMaxTextures] = {};
inline int g_nextId = 1;
inline int g_liveCount = 0;
inline int g_invalidDestroyCount = 0;

// Returns a new texture id (> 0), or 0 when creation fails.
inline int CreateTexture() {
    if (g_nextId >= kMaxTextures) return 0;
    const int id = g_nextId++;
    g_alive[id] = true;
    ++g_liveCount;
    return id;
}

// Must be called exactly once for every id returned by CreateTexture().
// Destroying 0, an unknown id, or the same id twice is counted as an error.
inline void DestroyTexture(int id) {
    if (id <= 0 || id >= kMaxTextures || !g_alive[id]) {
        ++g_invalidDestroyCount;
        return;
    }
    g_alive[id] = false;
    --g_liveCount;
}

inline bool IsAlive(int id) { return id > 0 && id < kMaxTextures && g_alive[id]; }
inline int LiveCount() { return g_liveCount; }
inline int InvalidDestroyCount() { return g_invalidDestroyCount; }
}  // namespace gfx
// ---------------------------------------------------------------------------

// Owns one texture id. 0 means "empty" (owns nothing).
// Invariant: id_ != 0  <=>  this object is the only owner of texture id_.
class TextureHandle {
public:
    TextureHandle() noexcept = default;
    explicit TextureHandle(int id) noexcept : id_(id) {}

    ~TextureHandle() { Reset(); }

    // One owner only: copying would make two destructors release the same id.
    TextureHandle(const TextureHandle&) = delete;
    TextureHandle& operator=(const TextureHandle&) = delete;

    // Steal the id and leave the source empty, so its destructor does nothing.
    TextureHandle(TextureHandle&& other) noexcept : id_(other.Release()) {}

    TextureHandle& operator=(TextureHandle&& other) noexcept {
        // Release() runs first: on self-move it empties *this and hands the same
        // id back to Reset(), which then has nothing to destroy and stores it again.
        Reset(other.Release());
        return *this;
    }

    int Get() const noexcept { return id_; }
    explicit operator bool() const noexcept { return id_ != 0; }

    // Gives up ownership without destroying. The caller is now responsible.
    int Release() noexcept { return std::exchange(id_, 0); }

    // Destroys the owned texture (if any), then owns `id` (0 = become empty).
    void Reset(int id = 0) noexcept {
        const int old = std::exchange(id_, id);
        if (old != 0 && old != id) gfx::DestroyTexture(old);  // Reset(Get()) is a no-op
    }

private:
    int id_ = 0;
};

