std::string Num(long long v) { return std::to_string(v); }

// Snapshot of the fake API counters; every case reports relative to its start.
struct Probe {
    int live0;
    int invalid0;
    Probe() : live0(gfx::LiveCount()), invalid0(gfx::InvalidDestroyCount()) {}
    int Live() const { return gfx::LiveCount() - live0; }
    int Invalid() const { return gfx::InvalidDestroyCount() - invalid0; }
    // Common end-of-case verdict: nothing leaked, nothing destroyed twice.
    std::string End() const {
        if (Invalid() != 0) return "잘못된 DestroyTexture 호출 " + Num(Invalid()) + "회 (같은 id를 두 번 해제했거나 0을 해제함)";
        if (Live() != 0) return "해제되지 않은 텍스처 " + Num(Live()) + "개 (누수)";
        return "";
    }
};

std::string ScopeExit() {
    Probe probe;
    int id = 0;
    {
        TextureHandle h(gfx::CreateTexture());
        id = h.Get();
        if (id <= 0 || !h) return "생성한 id를 Get()/operator bool로 확인할 수 없음";
        if (probe.Live() != 1) return "핸들이 살아 있는 동안 텍스처가 1개여야 함, 결과 " + Num(probe.Live());
    }
    if (gfx::IsAlive(id)) return "핸들이 스코프를 벗어났는데 텍스처가 해제되지 않음 (소멸자에서 DestroyTexture 필요)";
    return probe.End();
}

std::string EmptyHandle() {
    Probe probe;
    {
        TextureHandle a;
        TextureHandle b(0);  // CreateTexture() failure value
        if (a || b || a.Get() != 0 || b.Get() != 0) return "빈 핸들이 비어 있다고 보고하지 않음";
        TextureHandle c(std::move(a));
        b = std::move(c);
        b.Reset();
        if (b.Release() != 0) return "빈 핸들의 Release()는 0을 반환해야 함";
    }
    if (probe.Invalid() != 0) return "빈 핸들(id 0)에 대해 DestroyTexture가 " + Num(probe.Invalid()) + "회 호출됨";
    return probe.End();
}

std::string MoveCtor() {
    Probe probe;
    int id = 0;
    {
        TextureHandle a(gfx::CreateTexture());
        id = a.Get();
        TextureHandle b(std::move(a));
        if (b.Get() != id) return "이동 생성된 핸들이 id를 넘겨받지 못함";
        if (a.Get() != 0 || a) return "이동된 원본이 여전히 id " + Num(a.Get()) + "를 들고 있음 (소유자가 둘)";
        if (!gfx::IsAlive(id) || probe.Live() != 1) return "이동 생성 중에 텍스처가 해제되었거나 개수가 바뀜";
    }
    if (gfx::IsAlive(id)) return "소유권을 넘겨받은 핸들이 파괴되었는데 텍스처가 남아 있음";
    return probe.End();
}

std::string MoveAssign() {
    Probe probe;
    {
        TextureHandle a(gfx::CreateTexture());
        TextureHandle b(gfx::CreateTexture());
        const int idA = a.Get();
        const int idB = b.Get();
        b = std::move(a);
        if (gfx::IsAlive(idB)) return "이동 대입 직후, 대입받는 쪽이 원래 들고 있던 텍스처가 해제되지 않음";
        if (b.Get() != idA) return "이동 대입 후 Get() 기대 " + Num(idA) + ", 결과 " + Num(b.Get());
        if (a.Get() != 0) return "이동 대입 후 원본이 비워지지 않음 (Get()=" + Num(a.Get()) + ")";
        if (!gfx::IsAlive(idA) || probe.Live() != 1) return "넘겨받은 텍스처가 살아 있지 않음";
        TextureHandle empty;
        b = std::move(empty);  // assigning an empty handle releases the resource
        if (gfx::IsAlive(idA) || b) return "빈 핸들을 이동 대입했는데 기존 텍스처가 해제되지 않음";
    }
    return probe.End();
}

std::string SelfMoveAssign() {
    Probe probe;
    int id = 0;
    {
        TextureHandle h(gfx::CreateTexture());
        id = h.Get();
        TextureHandle& alias = h;
        h = std::move(alias);
        if (probe.Invalid() != 0) return "자기 이동 대입 중 잘못된 DestroyTexture 호출";
        if (h.Get() == id && !gfx::IsAlive(id)) return "자기 이동 대입 후 이미 해제된 id " + Num(id) + "를 계속 들고 있음 (댕글링 핸들)";
        if (h.Get() != id && gfx::IsAlive(id)) return "자기 이동 대입 후 핸들은 비었는데 텍스처는 살아 있음 (누수)";
        if (h.Get() != id) return "자기 이동 대입으로 멀쩡한 텍스처가 해제됨 (h = std::move(h) 뒤에도 같은 텍스처를 소유해야 함)";
    }
    if (gfx::IsAlive(id)) return "자기 이동 대입을 거친 핸들이 파괴된 뒤에도 텍스처가 남아 있음";
    return probe.End();
}

std::string ReleaseGivesUp() {
    Probe probe;
    int raw = 0;
    {
        TextureHandle h(gfx::CreateTexture());
        const int id = h.Get();
        raw = h.Release();
        if (raw != id) return "Release()가 소유하던 id를 반환하지 않음";
        if (h.Get() != 0 || h) return "Release() 후에도 핸들이 id를 들고 있음";
    }
    if (!gfx::IsAlive(raw)) return "Release()로 소유권을 포기했는데 핸들이 텍스처를 해제함";
    gfx::DestroyTexture(raw);  // the caller owns it now
    return probe.End();
}

std::string ResetReplaces() {
    Probe probe;
    {
        TextureHandle h(gfx::CreateTexture());
        const int first = h.Get();
        const int second = gfx::CreateTexture();
        h.Reset(second);
        if (gfx::IsAlive(first)) return "Reset(newId)가 기존 텍스처를 해제하지 않음";
        if (h.Get() != second || !gfx::IsAlive(second)) return "Reset(newId) 후 새 id를 소유하지 않음";
        h.Reset();
        if (gfx::IsAlive(second) || h) return "Reset()이 텍스처를 해제하고 핸들을 비우지 않음";
        h.Reset();  // already empty: must be a no-op
        if (probe.Invalid() != 0) return "빈 핸들에 Reset()을 호출했더니 DestroyTexture(0)이 호출됨";
    }
    return probe.End();
}

std::string VectorOfHandles() {
    if (std::is_copy_constructible<TextureHandle>::value || std::is_copy_assignable<TextureHandle>::value)
        return "TextureHandle이 복사 가능함 — 복사 생성/복사 대입을 = delete 해야 함";
    if (!std::is_nothrow_move_constructible<TextureHandle>::value || !std::is_nothrow_move_assignable<TextureHandle>::value)
        return "이동 생성/이동 대입이 noexcept가 아님";
    if (sizeof(TextureHandle) != sizeof(int)) return "sizeof(TextureHandle)이 sizeof(int)와 다름 — 데이터 멤버는 id 하나여야 함";
    Probe probe;
    {
        std::vector<TextureHandle> atlas;
        std::vector<int> ids;
        for (int i = 0; i < 40; ++i) {  // growth relocates handles by move
            ids.push_back(gfx::CreateTexture());
            atlas.emplace_back(ids.back());
        }
        if (probe.Live() != 40) return "vector에 40개를 넣은 뒤 살아 있는 텍스처 기대 40, 결과 " + Num(probe.Live());
        for (int i = 0; i < 40; ++i) {
            if (atlas[i].Get() != ids[i]) return "재할당 후 atlas[" + Num(i) + "]의 id가 바뀜";
        }
        atlas.erase(atlas.begin() + 5);  // shifts later handles down by move-assignment
        if (gfx::IsAlive(ids[5])) return "erase한 핸들의 텍스처가 해제되지 않음";
        if (probe.Live() != 39) return "erase 후 살아 있는 텍스처 기대 39, 결과 " + Num(probe.Live());
        for (int i = 5; i < 39; ++i) {
            if (atlas[i].Get() != ids[i + 1] || !gfx::IsAlive(ids[i + 1])) return "erase 후 atlas[" + Num(i) + "]가 올바른 텍스처를 소유하지 않음";
        }
        TextureHandle taken = std::move(atlas.back());
        atlas.pop_back();
        if (taken.Get() != ids[39] || !gfx::IsAlive(ids[39])) return "vector에서 꺼낸 핸들이 텍스처를 소유하지 않음";
        if (probe.Invalid() != 0) return "vector 조작 중 잘못된 DestroyTexture 호출 " + Num(probe.Invalid()) + "회";
    }
    return probe.End();
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    ScopeExit, EmptyHandle, MoveCtor, MoveAssign,
    SelfMoveAssign, ReleaseGivesUp, ResetReplaces, VectorOfHandles,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

