#include <csignal>
#include <cstring>
#include <exception>
#include <memory>
#include <string>
#include <utility>
#include <vector>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "factory-creates-each-type",
    "add-takes-ownership",
    "add-null-ignored",
    "find-missing-returns-null",
    "extract-returns-ownership",
    "extract-missing-returns-null",
    "many-entities-stable-addresses",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// A crash in learner code must still produce one line per remaining case.
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 메모리 접근 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }

std::string FactoryCreates() {
    const int base = Entity::alive;
    {
        std::unique_ptr<Entity> g = CreateEntity(EntityType::Goblin, 7);
        std::unique_ptr<Entity> a = CreateEntity(EntityType::Archer, 8);
        if (!g || !a) return "CreateEntity가 nullptr을 반환함";
        if (std::string(g->Name()) != "Goblin" || g->Id() != 7 || g->Hp() != 30) return "Goblin(id 7, hp 30) 기대, 결과 " + std::string(g->Name()) + "(id " + Num(g->Id()) + ", hp " + Num(g->Hp()) + ")";
        if (std::string(a->Name()) != "Archer" || a->Id() != 8 || a->Hp() != 20) return "Archer(id 8, hp 20) 기대, 결과 " + std::string(a->Name()) + "(id " + Num(a->Id()) + ", hp " + Num(a->Hp()) + ")";
        if (Entity::alive != base + 2) return "살아 있는 엔티티 기대 +2, 결과 +" + Num(Entity::alive - base);
    }
    if (Entity::alive != base) return "반환된 unique_ptr이 파괴된 뒤에도 엔티티가 " + Num(Entity::alive - base) + "개 남음";
    return "";
}

std::string AddTakesOwnership() {
    const int base = Entity::alive;
    {
        World world;
        std::unique_ptr<Entity> p = CreateEntity(EntityType::Goblin, 1);
        if (!p) return "CreateEntity가 nullptr을 반환함";
        Entity* raw = p.get();
        world.Add(std::move(p));
        if (world.Count() != 1) return "Add 후 Count 기대 1, 결과 " + Num((long long)world.Count());
        if (Entity::alive != base + 1) return "Add 직후 엔티티가 살아 있지 않음 (소유권을 받아 보관해야 함)";
        if (world.Find(1) != raw) return "Find(1)이 Add한 바로 그 객체를 가리키지 않음";
        world.Add(CreateEntity(EntityType::Archer, 2));  // temporary: moved in directly
        if (world.Count() != 2 || world.Find(2) == nullptr) return "임시 unique_ptr을 Add한 뒤 Count/Find가 기대와 다름";
    }
    if (Entity::alive != base) return "World가 파괴된 뒤에도 엔티티가 " + Num(Entity::alive - base) + "개 남음";
    return "";
}

std::string AddNullIgnored() {
    World world;
    world.Add(nullptr);
    world.Add(std::unique_ptr<Entity>());
    if (world.Count() != 0) return "nullptr을 Add했는데 Count가 " + Num((long long)world.Count());
    world.Add(CreateEntity(EntityType::Goblin, 3));
    world.Add(nullptr);
    if (world.Count() != 1) return "nullptr은 무시하고 유효한 엔티티만 세어야 함: 기대 1, 결과 " + Num((long long)world.Count());
    if (world.Find(4) != nullptr) return "null 슬롯이 남아 Find가 잘못 동작함";
    return "";
}

std::string FindMissing() {
    World world;
    if (world.Find(1) != nullptr) return "빈 World의 Find는 nullptr이어야 함";
    world.Add(CreateEntity(EntityType::Goblin, 1));
    if (world.Find(1) == nullptr) return "Add한 id 1을 Find로 찾지 못함";
    if (world.Find(2) != nullptr) return "없는 id 2에 대해 Find가 nullptr이 아님";
    return "";
}

std::string ExtractReturnsOwnership() {
    const int base = Entity::alive;
    {
        World world;
        world.Add(CreateEntity(EntityType::Goblin, 1));
        world.Add(CreateEntity(EntityType::Archer, 2));
        world.Add(CreateEntity(EntityType::Goblin, 3));
        Entity* raw = world.Find(2);
        if (raw == nullptr) return "Add한 id 2를 Find로 찾지 못함";
        std::unique_ptr<Entity> taken = world.Extract(2);
        if (taken.get() != raw) return "Extract(2)가 월드에 있던 바로 그 객체의 소유권을 반환하지 않음";
        if (world.Count() != 2) return "Extract 후 Count 기대 2, 결과 " + Num((long long)world.Count()) + " (비워진 슬롯을 지워야 함)";
        if (world.Find(2) != nullptr) return "Extract한 id 2가 여전히 Find됨";
        if (world.Find(1) == nullptr || world.Find(3) == nullptr) return "Extract가 다른 엔티티까지 제거함";
        if (Entity::alive != base + 3) return "Extract는 파괴가 아니라 소유권 이전이어야 함 (살아 있는 엔티티 기대 +3, 결과 +" + Num(Entity::alive - base) + ")";
        taken.reset();
        if (Entity::alive != base + 2) return "반환된 unique_ptr을 reset했는데 엔티티가 파괴되지 않음";
        if (world.Find(1) == nullptr || world.Find(3) == nullptr || world.Count() != 2) return "꺼낸 엔티티를 파괴한 뒤 월드 상태가 바뀜";
    }
    if (Entity::alive != base) return "스코프 종료 후 엔티티가 " + Num(Entity::alive - base) + "개 남음";
    return "";
}

std::string ExtractMissing() {
    World world;
    if (world.Extract(5)) return "빈 World의 Extract는 nullptr이어야 함";
    world.Add(CreateEntity(EntityType::Goblin, 1));
    if (world.Extract(5)) return "없는 id 5의 Extract는 nullptr이어야 함";
    if (world.Count() != 1 || world.Find(1) == nullptr) return "실패한 Extract가 월드를 변경함";
    std::unique_ptr<Entity> first = world.Extract(1);
    if (!first) return "Extract(1)이 nullptr을 반환함";
    if (world.Extract(1)) return "같은 id를 두 번 Extract했는데 두 번째가 nullptr이 아님";
    return "";
}

std::string ManyEntities() {
    const int base = Entity::alive;
    {
        World world;
        std::vector<Entity*> raws;
        for (int id = 1; id <= 200; ++id) {
            std::unique_ptr<Entity> p = CreateEntity(id % 2 == 0 ? EntityType::Archer : EntityType::Goblin, id);
            if (!p) return "CreateEntity가 nullptr을 반환함";
            raws.push_back(p.get());
            world.Add(std::move(p));
        }
        if (world.Count() != 200 || Entity::alive != base + 200) return "200개 Add 후 Count/생존 수가 200이 아님";
        for (int id = 1; id <= 200; ++id) {  // vector growth moved the unique_ptrs, not the entities
            if (world.Find(id) != raws[id - 1]) return "vector가 커진 뒤 id " + Num(id) + "의 객체 주소가 바뀜";
        }
        std::vector<std::unique_ptr<Entity>> party;
        for (int id = 2; id <= 200; id += 2) {
            party.push_back(world.Extract(id));
            if (party.back().get() != raws[id - 1]) return "Extract(" + Num(id) + ")가 올바른 객체를 반환하지 않음";
        }
        if (world.Count() != 100 || Entity::alive != base + 200) return "절반을 Extract한 뒤 Count 기대 100 / 생존 기대 +200, 결과 " + Num((long long)world.Count()) + " / +" + Num(Entity::alive - base);
        for (int id = 1; id <= 200; ++id) {
            Entity* found = world.Find(id);
            if (id % 2 == 1 && found != raws[id - 1]) return "남아 있어야 할 id " + Num(id) + "를 찾지 못함";
            if (id % 2 == 0 && found != nullptr) return "꺼낸 id " + Num(id) + "가 여전히 Find됨";
        }
        party.clear();
        if (Entity::alive != base + 100) return "꺼낸 엔티티 100개를 파괴한 뒤 생존 기대 +100, 결과 +" + Num(Entity::alive - base);
    }
    if (Entity::alive != base) return "스코프 종료 후 엔티티가 " + Num(Entity::alive - base) + "개 남음";
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    FactoryCreates, AddTakesOwnership, AddNullIgnored, FindMissing,
    ExtractReturnsOwnership, ExtractMissing, ManyEntities,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

