#include <cstddef>
#include <string>
#include <unordered_map>
#include <vector>

struct Enemy {
    int id = 0;
    int hp = 0;
    int splits = 0;  // how many more times this slime splits when it dies
    std::string name;
};

// A dead enemy that can still split spawns two smaller slimes at the end of the
// turn order. Each child gets the next free id, 15 hp per split the parent had
// left, and one split fewer than its parent.
void SplitDeadSlimes(std::vector<Enemy>& enemies, int& nextId) {
    for (const Enemy& e : enemies) {
        if (e.hp <= 0 && e.splits > 0) {
            enemies.push_back(Enemy{nextId++, 15 * e.splits, e.splits - 1, "Slimeling"});
            enemies.push_back(Enemy{nextId++, 15 * e.splits, e.splits - 1, "Slimeling"});
        }
    }
}

// Removes every enemy with hp <= 0 and keeps the turn order of the survivors.
// Returns how many enemies were removed.
int RemoveDead(std::vector<Enemy>& enemies) {
    int removed = 0;
    for (auto it = enemies.begin(); it != enemies.end(); ++it) {
        if (it->hp <= 0) {
            enemies.erase(it);
            ++removed;
        }
    }
    return removed;
}

// Summoned minions are stored by id. Removes the dead ones and returns how many.
int RemoveDeadMinions(std::unordered_map<int, Enemy>& minions) {
    int removed = 0;
    for (const auto& entry : minions) {
        if (entry.second.hp <= 0) {
            minions.erase(entry.first);
            ++removed;
        }
    }
    return removed;
}

