#include <array>
#include <iostream>
#include <string>
#include <utility>

// Balance constants: fixed at compile time, usable as array sizes and in static_assert.
constexpr int kMaxLevel = 60;
constexpr int kHpPerLevel = 20;

// constexpr function: evaluated by the compiler when a constant expression is
// required and the arguments are constants; an ordinary call otherwise.
constexpr int HpAtLevel(int baseHp, int level) { return baseHp + kHpPerLevel * (level - 1); }

class CharacterStats {
public:
    CharacterStats(std::string name, int level, int baseHp)
        : name_(std::move(name)), level_(level), baseHp_(baseHp) {}

    // Queries do not modify the object -> const member functions.
    // Name() returns a reference to const so that a const object cannot be
    // modified through the getter.
    const std::string& Name() const { return name_; }
    int Level() const { return level_; }
    int MaxHp() const { return HpAtLevel(baseHp_, level_); }
    bool IsMaxLevel() const { return level_ == kMaxLevel; }

    // Changes the object -> stays non-const on purpose.
    void LevelUp() {
        if (level_ < kMaxLevel) ++level_;
    }

private:
    std::string name_;
    int level_;
    int baseHp_;
};

// Read-only parameter -> reference to const. Accepts const objects and temporaries.
std::string Describe(const CharacterStats& stats) {
    return stats.Name() + " Lv." + std::to_string(stats.Level()) + " HP " + std::to_string(stats.MaxHp());
}

int main() {
    CharacterStats knight("Knight", 9, 100);
    knight.LevelUp();
    std::cout << Describe(knight) << " (expected Knight Lv.10 HP 280)\n";

    // (A) A boss template that must never change after it is created.
    const CharacterStats boss("Lich King", 60, 5000);
    std::cout << Describe(boss) << " (expected Lich King Lv.60 HP 6180)\n";
    std::cout << "boss at max level: " << boss.IsMaxLevel() << " (expected 1)\n";

    // (B) Checked by the compiler; costs nothing at run time.
    static_assert(HpAtLevel(100, 10) == 280, "level curve changed");
    std::array<int, kMaxLevel> xpTable{};
    std::cout << "xp table size: " << xpTable.size() << " (expected 60)\n";

    // The same function with a run-time argument is an ordinary call.
    const int levelFromSave = knight.Level();
    const int hpNow = HpAtLevel(100, levelFromSave);
    std::cout << "hp from run-time level: " << hpNow << " (expected 280)\n";

    // (C) Still a compile error, and that is the point: LevelUp() modifies the
    // object, boss is const, and the compiler refuses the call.
    // boss.LevelUp();
    return 0;
}

