#include <cassert>
#include <cstddef>
#include <cstdint>
#include <new>
#include <utility>

// Fixed-capacity object pool. The storage for all N objects lives inside the pool
// object itself; the pool never allocates from the heap.
template <typename T, std::size_t N>
class ObjectPool {
    static_assert(N > 0, "ObjectPool needs at least one slot");

public:
    ObjectPool() noexcept : firstFree_(0), size_(0) {
        // Free list threaded through the unused slots: slot i -> slot i + 1.
        // The value N means "end of list".
        for (std::size_t i = 0; i < N; ++i) {
            slots_[i].nextFree = i + 1;
            live_[i] = false;
        }
    }

    ~ObjectPool() {
        // The free list only knows the free slots, so the live flags tell us which
        // slots hold an object whose destructor still has to run.
        for (std::size_t i = 0; i < N; ++i) {
            if (live_[i]) ObjectAt(i)->~T();
        }
    }

    ObjectPool(const ObjectPool&) = delete;
    ObjectPool& operator=(const ObjectPool&) = delete;

    // Constructs a T in a free slot from the given arguments and returns it.
    // Returns nullptr (and constructs nothing) when all N slots are in use.
    // If T's constructor throws, the exception propagates and the slot stays free.
    template <typename... Args>
    T* Create(Args&&... args) {
        if (firstFree_ == N) return nullptr;
        const std::size_t index = firstFree_;
        // Read the link first: constructing T reuses the very bytes that hold it.
        const std::size_t next = slots_[index].nextFree;
        T* object = nullptr;
        try {
            // Placement new: no allocation, just the constructor call at this address.
            object = ::new (static_cast<void*>(slots_[index].storage)) T(std::forward<Args>(args)...);
        } catch (...) {
            // A half-run constructor may have scribbled over the link. Put it back;
            // firstFree_ was not changed, so the slot is simply still free.
            slots_[index].nextFree = next;
            throw;
        }
        firstFree_ = next;
        live_[index] = true;
        ++size_;
        return object;
    }

    // Destroys an object returned by Create and makes its slot reusable.
    // Destroy(nullptr) does nothing.
    // Contract: any other pointer must come from Create() of this pool and must not
    // have been destroyed already. Violations are caught in debug builds only.
    void Destroy(T* object) noexcept {
        if (object == nullptr) return;
        const std::size_t index = IndexOf(object);
        assert(index < N && live_[index] && "not created by this pool, or destroyed twice");
        object->~T();  // explicit destructor call: the storage itself is not released
        slots_[index].nextFree = firstFree_;  // push the slot on the free list
        firstFree_ = index;
        live_[index] = false;
        --size_;
    }

    // Number of objects currently alive.
    std::size_t Size() const noexcept { return size_; }

    static constexpr std::size_t Capacity() noexcept { return N; }

private:
    // A slot is either the storage of a live T or, while free, the index of the
    // next free slot. The free list therefore costs no memory per object.
    union Slot {
        std::size_t nextFree;
        alignas(T) unsigned char storage[sizeof(T)];
    };

    std::size_t IndexOf(const T* object) const noexcept {
        const std::uintptr_t address = reinterpret_cast<std::uintptr_t>(object);
        const std::uintptr_t base = reinterpret_cast<std::uintptr_t>(&slots_[0]);
        return static_cast<std::size_t>((address - base) / sizeof(Slot));
    }

    T* ObjectAt(std::size_t index) noexcept {
        return std::launder(reinterpret_cast<T*>(slots_[index].storage));
    }

    Slot slots_[N];
    bool live_[N];
    std::size_t firstFree_;
    std::size_t size_;
};

