#include <cerrno>
#include <csignal>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <new>
#include <string>
#include <utility>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

// Counting heap: every allocation and release through operator new/delete is counted
// in static storage, so "the pool never touches the heap" is measured, not assumed.
namespace judge_heap {
long g_allocs = 0;
long g_frees = 0;
}
void* operator new(std::size_t n) {
    ++judge_heap::g_allocs;
    void* p = std::malloc(n ? n : 1);
    if (p == nullptr) throw std::bad_alloc();
    return p;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept {
    if (p == nullptr) return;
    ++judge_heap::g_frees;
    std::free(p);
}
void operator delete[](void* p) noexcept { operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { operator delete(p); }

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "create-constructs-inside-pool",
    "full-pool-returns-null-then-reuses",
    "destroy-runs-destructor-once",
    "no-heap-allocation",
    "pool-destructor-destroys-leftovers",
    "constructor-throw-keeps-slot-free",
    "overaligned-and-nontrivial-types",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 메모리 접근 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }

// Instrumented element type. Constructor/destructor calls are counted and every
// live address is registered in static storage, so a destructor that runs twice,
// or on a slot that never held an object, is counted instead of guessed at.
struct Boom {};
struct Tracked;
const int kMaxLive = 128;
const Tracked* g_liveAddr[kMaxLive];
int g_liveCount = 0;
long g_ctor = 0;
long g_dtor = 0;
long g_badDtor = 0;

struct Tracked {
    int value;
    int mirror;
    explicit Tracked(int v) : value(v), mirror(~v) { Register(); }
    Tracked(int v, bool boom) : value(v), mirror(~v) {
        if (boom) throw Boom();
        Register();
    }
    Tracked(const Tracked&) = delete;
    Tracked& operator=(const Tracked&) = delete;
    ~Tracked() {
        ++g_dtor;
        bool found = false;
        for (int i = 0; i < g_liveCount; ++i) {
            if (g_liveAddr[i] == this) {
                g_liveAddr[i] = g_liveAddr[--g_liveCount];
                found = true;
                break;
            }
        }
        if (!found) ++g_badDtor;
    }
    bool Intact(int expected) const { return value == expected && mirror == ~expected; }

private:
    void Register() {
        ++g_ctor;
        if (g_liveCount < kMaxLive) g_liveAddr[g_liveCount++] = this;
    }
};

void ResetTracked() {
    g_liveCount = 0;
    g_ctor = 0;
    g_dtor = 0;
    g_badDtor = 0;
}

std::string TrackedVerdict(long expectCtor) {
    if (g_badDtor != 0) return "객체가 없는 슬롯이나 이미 파괴된 객체에 소멸자가 " + Num(g_badDtor) + "회 호출됨";
    if (g_ctor != expectCtor) return "생성자 호출 기대 " + Num(expectCtor) + "회, 결과 " + Num(g_ctor) + "회";
    if (g_dtor != g_ctor) return "생성된 객체 " + Num(g_ctor) + "개 중 소멸자가 호출된 것은 " + Num(g_dtor) + "개 (풀이 파괴될 때 남은 객체를 정리해야 함)";
    return "";
}

// The pool sits between two fences on the judge's stack. A write outside the pool
// object shows up as a broken fence; an object outside the pool's own footprint
// means the storage is not inside the pool.
template <typename P>
struct Fenced {
    unsigned char pre[128];
    P pool;
    unsigned char post[128];
    Fenced() {
        std::memset(pre, 0xA5, sizeof(pre));
        std::memset(post, 0xA5, sizeof(post));
    }
    bool Broken() const {
        for (std::size_t i = 0; i < sizeof(pre); ++i) {
            if (pre[i] != 0xA5 || post[i] != 0xA5) return true;
        }
        return false;
    }
    bool Contains(const void* p, std::size_t size) const {
        const std::uintptr_t a = reinterpret_cast<std::uintptr_t>(p);
        const std::uintptr_t lo = reinterpret_cast<std::uintptr_t>(&pool);
        return a >= lo && a + size <= lo + sizeof(P);
    }
};

template <typename T>
bool Aligned(const T* p) {
    return reinterpret_cast<std::uintptr_t>(p) % alignof(T) == 0;
}

std::string CreateInsidePool() {
    ResetTracked();
    {
        Fenced<ObjectPool<Tracked, 4> > f;
        if (f.pool.Size() != 0) return "새 풀의 Size 기대 0, 결과 " + Num((long long)f.pool.Size());
        if (ObjectPool<Tracked, 4>::Capacity() != 4) return "Capacity 기대 4";
        Tracked* made[4];
        for (int i = 0; i < 4; ++i) {
            made[i] = f.pool.Create(10 * (i + 1));
            if (made[i] == nullptr) return "빈 슬롯이 있는데 " + Num(i + 1) + "번째 Create가 nullptr을 반환함";
            if (!f.Contains(made[i], sizeof(Tracked))) return "Create가 반환한 객체가 풀 객체의 메모리 범위 밖에 있음 (저장소는 풀 안에 있어야 함)";
            if (!Aligned(made[i])) return "Create가 반환한 주소가 alignof(T)에 맞지 않음";
            for (int k = 0; k < i; ++k) {
                if (made[k] == made[i]) return "살아 있는 두 객체가 같은 슬롯을 받음";
            }
            if (f.pool.Size() != static_cast<std::size_t>(i + 1)) return "Create " + Num(i + 1) + "회 뒤 Size 기대 " + Num(i + 1) + ", 결과 " + Num((long long)f.pool.Size());
        }
        for (int i = 0; i < 4; ++i) {
            if (!made[i]->Intact(10 * (i + 1))) return Num(i + 1) + "번째 객체의 값이 깨짐 (기대 " + Num(10 * (i + 1)) + ", 결과 " + Num(made[i]->value) + ")";
        }
        if (g_ctor != 4) return "생성자 호출 기대 4회, 결과 " + Num(g_ctor) + "회";
        for (int i = 0; i < 4; ++i) f.pool.Destroy(made[i]);
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    return TrackedVerdict(4);
}

std::string FullThenReuse() {
    ResetTracked();
    {
        Fenced<ObjectPool<Tracked, 3> > f;
        Tracked* a = f.pool.Create(1);
        Tracked* b = f.pool.Create(2);
        Tracked* c = f.pool.Create(3);
        if (a == nullptr || b == nullptr || c == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        Tracked* overflow = f.pool.Create(4);
        if (overflow != nullptr) return "슬롯 3개가 모두 사용 중인데 Create가 nullptr을 반환하지 않음";
        if (g_ctor != 3) return "풀이 가득 찼는데 생성자가 호출됨 (생성자 호출 " + Num(g_ctor) + "회)";
        if (f.pool.Size() != 3) return "가득 찬 풀의 Size 기대 3, 결과 " + Num((long long)f.pool.Size());
        f.pool.Destroy(b);
        if (f.pool.Size() != 2) return "Destroy 뒤 Size 기대 2, 결과 " + Num((long long)f.pool.Size());
        Tracked* again = f.pool.Create(5);
        if (again == nullptr) return "슬롯을 반납했는데 Create가 nullptr을 반환함";
        if (again != b) return "유일하게 비어 있던 슬롯이 재사용되지 않음";
        if (!a->Intact(1) || !c->Intact(3) || !again->Intact(5)) return "슬롯 재사용 뒤 객체의 값이 깨짐";
        if (f.pool.Create(6) != nullptr) return "다시 가득 찼는데 Create가 nullptr을 반환하지 않음";
        f.pool.Destroy(a);
        f.pool.Destroy(c);
        f.pool.Destroy(again);
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    return TrackedVerdict(4);
}

std::string DestroyRunsDestructorOnce() {
    ResetTracked();
    {
        Fenced<ObjectPool<Tracked, 5> > f;
        f.pool.Destroy(nullptr);
        if (g_dtor != 0 || f.pool.Size() != 0) return "Destroy(nullptr)가 무언가를 파괴하거나 Size를 바꿈";
        Tracked* p[5];
        for (int i = 0; i < 5; ++i) {
            p[i] = f.pool.Create(i);
            if (p[i] == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        }
        f.pool.Destroy(p[3]);
        if (g_dtor != 1) return "Destroy 1회에 소멸자 호출 기대 1회, 결과 " + Num(g_dtor) + "회";
        f.pool.Destroy(p[0]);
        f.pool.Destroy(p[4]);
        if (g_dtor != 3 || g_badDtor != 0) return "Destroy 3회에 소멸자 호출 기대 3회, 결과 " + Num(g_dtor) + "회";
        if (!p[1]->Intact(1) || !p[2]->Intact(2)) return "다른 객체를 Destroy하자 살아 있는 객체의 값이 깨짐 (free list 링크가 살아 있는 슬롯을 덮어씀)";
        f.pool.Destroy(p[1]);
        f.pool.Destroy(p[2]);
        if (f.pool.Size() != 0) return "모두 Destroy한 뒤 Size 기대 0, 결과 " + Num((long long)f.pool.Size());
        // Every slot must be back on the free list.
        for (int i = 0; i < 5; ++i) {
            p[i] = f.pool.Create(100 + i);
            if (p[i] == nullptr) return "모두 반납한 뒤 " + Num(i + 1) + "번째 Create가 nullptr을 반환함 (반납한 슬롯을 잃어버림)";
            for (int k = 0; k < i; ++k) {
                if (p[k] == p[i]) return "살아 있는 두 객체가 같은 슬롯을 받음";
            }
        }
        for (int i = 0; i < 5; ++i) {
            if (!p[i]->Intact(100 + i)) return "다시 채운 객체의 값이 깨짐";
            f.pool.Destroy(p[i]);
        }
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    return TrackedVerdict(10);
}

struct Bullet {
    float x, y, vx, vy;
    int owner;
    Bullet(float px, float py, int who) : x(px), y(py), vx(1.0f), vy(0.0f), owner(who) {}
};

std::string NoHeapAllocation() {
    const long allocs0 = judge_heap::g_allocs;
    bool wrong = false;
    {
        Fenced<ObjectPool<Bullet, 64> > f;
        Bullet* live[64];
        int count = 0;
        unsigned seed = 7u;
        for (int step = 0; step < 4000; ++step) {
            seed = seed * 1664525u + 1013904223u;
            if (count < 64 && ((seed >> 16) % 3 != 0)) {
                Bullet* b = f.pool.Create(static_cast<float>(step), 2.0f, step);
                if (b == nullptr || b->owner != step) {
                    wrong = true;
                    break;
                }
                live[count++] = b;
            } else if (count > 0) {
                const int k = static_cast<int>((seed >> 8) % static_cast<unsigned>(count));
                f.pool.Destroy(live[k]);
                live[k] = live[--count];
            }
        }
        if (!wrong && f.Broken()) wrong = true;
    }
    const long allocs = judge_heap::g_allocs - allocs0;
    if (wrong) return "Create/Destroy 4000회 반복 중 Create가 실패하거나 값이 깨짐";
    if (allocs != 0) return "풀 생성부터 파괴까지 힙 할당이 " + Num(allocs) + "회 일어남 (기대 0회)";
    return "";
}

struct Named {
    std::string name;
    int level;
    Named(const char* n, int lv) : name(n), level(lv) {}
};

std::string PoolDestructorDestroysLeftovers() {
    ResetTracked();
    {
        Fenced<ObjectPool<Tracked, 6> > f;
        Tracked* p[5];
        for (int i = 0; i < 5; ++i) p[i] = f.pool.Create(i);
        for (int i = 0; i < 5; ++i) {
            if (p[i] == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        }
        f.pool.Destroy(p[1]);
        f.pool.Destroy(p[4]);
        // p[0], p[2], p[3] are still alive when the pool goes out of scope.
    }
    std::string d = TrackedVerdict(5);
    if (!d.empty()) return d;
    if (g_liveCount != 0) return "풀이 파괴된 뒤에도 소멸자가 호출되지 않은 객체가 " + Num(g_liveCount) + "개 남음";
    ResetTracked();
    {
        ObjectPool<Tracked, 3> untouched;  // never used: no destructor may run
    }
    if (g_dtor != 0) return "아무것도 만들지 않은 풀이 파괴되면서 소멸자가 " + Num(g_dtor) + "회 호출됨";
    const long balance0 = judge_heap::g_allocs - judge_heap::g_frees;
    {
        ObjectPool<Named, 4> names;
        Named* a = names.Create("a long enough name to live on the heap #1", 1);
        Named* b = names.Create("a long enough name to live on the heap #2", 2);
        Named* c = names.Create("a long enough name to live on the heap #3", 3);
        if (a == nullptr || b == nullptr || c == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        names.Destroy(b);
    }
    const long leaked = (judge_heap::g_allocs - judge_heap::g_frees) - balance0;
    if (leaked != 0) return "std::string을 가진 객체가 남은 채 풀이 파괴된 뒤 해제되지 않은 힙 블록 " + Num(leaked) + "개 (남은 객체의 소멸자가 호출되지 않음)";
    return "";
}

std::string ConstructorThrowKeepsSlot() {
    ResetTracked();
    {
        Fenced<ObjectPool<Tracked, 4> > f;
        Tracked* a = f.pool.Create(1);
        if (a == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        for (int attempt = 0; attempt < 3; ++attempt) {
            bool threw = false;
            try {
                f.pool.Create(99, true);
            } catch (const Boom&) {
                threw = true;
            }
            if (!threw) return "T의 생성자가 던진 예외가 Create 밖으로 전파되지 않음";
            if (f.pool.Size() != 1) return "생성자가 예외로 실패한 뒤 Size 기대 1, 결과 " + Num((long long)f.pool.Size());
        }
        if (g_dtor != 0) return "생성에 실패한 객체에 소멸자가 호출됨";
        Tracked* rest[3];
        for (int i = 0; i < 3; ++i) {
            rest[i] = f.pool.Create(20 + i);
            if (rest[i] == nullptr) return "생성자가 예외로 실패한 슬롯을 잃어버림: 빈 슬롯 3개 중 " + Num(i + 1) + "번째 Create가 nullptr";
            if (rest[i] == a) return "살아 있는 객체의 슬롯을 다시 내줌";
            for (int k = 0; k < i; ++k) {
                if (rest[k] == rest[i]) return "살아 있는 두 객체가 같은 슬롯을 받음 (예외 뒤 free list가 깨짐)";
            }
        }
        if (f.pool.Create(5) != nullptr) return "가득 찼는데 Create가 nullptr을 반환하지 않음";
        if (!a->Intact(1) || !rest[0]->Intact(20) || !rest[1]->Intact(21) || !rest[2]->Intact(22)) return "예외 뒤 만든 객체의 값이 깨짐";
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    return TrackedVerdict(4);
}

struct alignas(32) Wide {
    double v[4];
    int tag;
    explicit Wide(int t) : tag(t) {
        for (int i = 0; i < 4; ++i) v[i] = t + 0.25 * i;
    }
    bool Intact(int t) const {
        if (tag != t) return false;
        for (int i = 0; i < 4; ++i) {
            if (v[i] != t + 0.25 * i) return false;
        }
        return true;
    }
};

// Only a byte-sized member: constructing one at a misaligned address cannot fault,
// so the judge can simply look at the address it gets back.
struct alignas(64) AlignProbe {
    unsigned char tag;
    explicit AlignProbe(unsigned char t) : tag(t) {}
};

// Whether a stack variable happens to start on a 32- or 64-byte boundary is luck.
// Here the pool is built at every position inside a 64-byte-aligned arena that the
// pool type's own alignment permits, so storage that is not aligned for T is caught
// on every run instead of only when the stack layout is unlucky.
std::string AlignmentAtEveryPlacement() {
    typedef ObjectPool<AlignProbe, 3> Pool;
    if (alignof(Pool) > 64) return "";
    alignas(64) static unsigned char arena[sizeof(Pool) + 64];
    for (std::size_t offset = 0; offset < 64; offset += alignof(Pool)) {
        Pool* pool = ::new (static_cast<void*>(arena + offset)) Pool();
        std::string bad;
        AlignProbe* made[3] = {nullptr, nullptr, nullptr};
        for (int i = 0; i < 3 && bad.empty(); ++i) {
            made[i] = pool->Create(static_cast<unsigned char>(i + 1));
            if (made[i] == nullptr) {
                bad = "alignas(64) 타입: 빈 슬롯이 있는데 Create가 nullptr을 반환함";
            } else if (!Aligned(made[i])) {
                bad = "alignas(64) 타입의 객체 주소가 64의 배수가 아님 (저장소 정렬 누락: 풀 타입의 정렬이 " + Num((long long)alignof(Pool)) +
                      "이어서 풀이 놓인 위치에 따라 객체 주소가 어긋남)";
            }
        }
        for (int i = 0; i < 3; ++i) {
            if (made[i] != nullptr) pool->Destroy(made[i]);
        }
        pool->~Pool();
        if (!bad.empty()) return bad;
    }
    return "";
}

std::string OveralignedAndNontrivial() {
    {
        std::string d = AlignmentAtEveryPlacement();
        if (!d.empty()) return d;
    }
    {
        Fenced<ObjectPool<Wide, 5> > f;
        Wide* w[5];
        for (int i = 0; i < 5; ++i) {
            w[i] = f.pool.Create(i + 1);
            if (w[i] == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
            if (!Aligned(w[i])) return "alignas(32) 타입의 객체 주소가 32의 배수가 아님 (저장소 정렬 누락)";
            if (!f.Contains(w[i], sizeof(Wide))) return "객체가 풀 객체의 메모리 범위 밖에 있음";
        }
        f.pool.Destroy(w[2]);
        f.pool.Destroy(w[0]);
        w[0] = f.pool.Create(70);
        w[2] = f.pool.Create(80);
        if (w[0] == nullptr || w[2] == nullptr) return "반납한 슬롯을 다시 받지 못함";
        if (!Aligned(w[0]) || !Aligned(w[2])) return "재사용한 슬롯의 주소가 32의 배수가 아님";
        if (!w[0]->Intact(70) || !w[1]->Intact(2) || !w[2]->Intact(80) || !w[3]->Intact(4) || !w[4]->Intact(5)) return "alignas(32) 객체의 값이 깨짐 (슬롯 크기/간격 계산 오류)";
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    {
        ObjectPool<Named, 3> names;
        Named* a = names.Create("Captain of the Northern Watch", 12);
        Named* b = names.Create("Wandering Alchemist of the Marsh", 7);
        Named* c = names.Create("Keeper of the Sunken Library", 30);
        if (a == nullptr || b == nullptr || c == nullptr) return "빈 슬롯이 있는데 Create가 nullptr을 반환함";
        names.Destroy(b);
        b = names.Create("Apprentice Blacksmith of the Lower Town", 3);
        if (b == nullptr) return "반납한 슬롯을 다시 받지 못함";
        if (a->name != "Captain of the Northern Watch" || a->level != 12 || c->name != "Keeper of the Sunken Library" || c->level != 30 ||
            b->name != "Apprentice Blacksmith of the Lower Town" || b->level != 3)
            return "std::string 멤버를 가진 객체의 값이 깨짐";
        names.Destroy(a);
        names.Destroy(b);
        names.Destroy(c);
    }
    {
        // An element smaller than a free-list link.
        Fenced<ObjectPool<char, 3> > f;
        char* x = f.pool.Create('x');
        char* y = f.pool.Create('y');
        char* z = f.pool.Create('z');
        if (x == nullptr || y == nullptr || z == nullptr) return "char 풀: 빈 슬롯이 있는데 Create가 nullptr을 반환함";
        if (x == y || y == z || x == z) return "char 풀: 살아 있는 두 객체가 같은 슬롯을 받음";
        f.pool.Destroy(y);
        y = f.pool.Create('w');
        if (y == nullptr || *x != 'x' || *y != 'w' || *z != 'z') return "char 풀: 슬롯 재사용 뒤 값이 깨짐 (슬롯이 링크보다 작은 타입을 고려하지 않음)";
        if (f.pool.Create('q') != nullptr) return "char 풀: 가득 찼는데 Create가 nullptr을 반환하지 않음";
        if (f.Broken()) return "char 풀: 풀 객체 바깥의 메모리에 기록함";
    }
    return "";
}

// Model for the random case, kept in static storage.
Tracked* g_modelPtr[16];
int g_modelValue[16];

std::string RandomVsReference() {
    ResetTracked();
    long created = 0;
    {
        Fenced<ObjectPool<Tracked, 16> > f;
        int count = 0;
        unsigned seed = 20261122u;
        for (int step = 0; step < 3000; ++step) {
            seed = seed * 1664525u + 1013904223u;
            const unsigned roll = (seed >> 16) % 100;
            seed = seed * 1664525u + 1013904223u;
            const unsigned pick = seed >> 16;
            // Phases: mostly create, then mostly destroy, so the pool repeatedly fills up and drains.
            const unsigned createBias = ((step / 150) % 2 == 0) ? 70u : 30u;
            if (roll < createBias) {
                Tracked* made = f.pool.Create(step);
                if (count == 16) {
                    if (made != nullptr) return "step " + Num(step) + ": 가득 찼는데 Create가 nullptr을 반환하지 않음";
                } else {
                    if (made == nullptr) return "step " + Num(step) + ": 빈 슬롯이 " + Num(16 - count) + "개 있는데 Create가 nullptr을 반환함";
                    for (int k = 0; k < count; ++k) {
                        if (g_modelPtr[k] == made) return "step " + Num(step) + ": 살아 있는 객체의 슬롯을 다시 내줌";
                    }
                    g_modelPtr[count] = made;
                    g_modelValue[count] = step;
                    ++count;
                    ++created;
                }
            } else if (count > 0) {
                const int k = static_cast<int>(pick % static_cast<unsigned>(count));
                f.pool.Destroy(g_modelPtr[k]);
                --count;
                g_modelPtr[k] = g_modelPtr[count];
                g_modelValue[k] = g_modelValue[count];
            }
            if (f.pool.Size() != static_cast<std::size_t>(count)) return "step " + Num(step) + ": Size 기대 " + Num(count) + ", 결과 " + Num((long long)f.pool.Size());
            for (int k = 0; k < count; ++k) {
                if (!g_modelPtr[k]->Intact(g_modelValue[k])) return "step " + Num(step) + ": 살아 있는 객체의 값이 깨짐 (기대 " + Num(g_modelValue[k]) + ", 결과 " + Num(g_modelPtr[k]->value) + ")";
            }
            if (g_badDtor != 0) return "step " + Num(step) + ": 잘못된 주소에 소멸자가 호출됨";
            if (g_liveCount != count) return "step " + Num(step) + ": 살아 있어야 할 객체 수 " + Num(count) + ", 실제로 소멸자가 불리지 않은 객체 수 " + Num(g_liveCount);
        }
        if (f.Broken()) return "풀 객체 바깥의 메모리에 기록함";
    }
    return TrackedVerdict(created);
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    CreateInsidePool,                FullThenReuse,             DestroyRunsDestructorOnce, NoHeapAllocation,
    PoolDestructorDestroysLeftovers, ConstructorThrowKeepsSlot, OveralignedAndNontrivial,  RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                      : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 1;  // a correct case finishes in milliseconds
const int kMaxTimeouts = 3;       // after this many, the remaining cases are not started

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): assert 실패 또는 std::terminate 호출";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (free list가 순환하는 등 끝나지 않는 루프 가능성)";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (객체가 없는 슬롯의 소멸자 호출이나 깨진 free list 링크 가능성)";
        if (sig == SIGKILL) return "실행 환경이 프로세스를 강제 종료함 (메모리 한도 초과 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Every case runs in its own child process. An abort, a crash or an endless loop
    // therefore costs only that case: the other cases still run and report their own
    // results.
    int timeouts = 0;
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        if (timeouts >= kMaxTimeouts) {
            const std::string skipped = std::string("[FAIL] ") + kCases[i] + " :: 앞선 케이스 " + Num(timeouts) +
                                        "개가 시간 초과되어 이 케이스는 실행하지 않음 (끝나지 않는 루프를 먼저 고치세요)\n";
            Emit(skipped.c_str());
            continue;
        }
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            // No process isolation available: run in this process. A crash then ends the
            // run, and OnCrash still writes one line for every remaining case.
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        if (waited == pid && WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) ++timeouts;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written
}

