problems.solutionCode:
#include <cstddef>
#include <memory>
#include <utility>
#include <vector>

// HUD marker drawn over a locked-on target for as long as a missile refers to it.
struct LockOnMarker {
    int targetId = 0;
};

class Projectile {
public:
    Projectile(float x, float speed) : x_(x), speed_(speed) {}

    // Fix 2: derived objects are destroyed through Projectile pointers
    // (std::unique_ptr<Projectile>), so the destructor must be virtual. Without it
    // that delete is undefined behaviour, and ~HomingMissile is not guaranteed to
    // run and release the marker.
    virtual ~Projectile() = default;

    // Prevention: a polymorphic base that cannot be copied cannot be sliced.
    // With these two lines the old by-value parameter no longer compiles.
    Projectile(const Projectile&) = delete;
    Projectile& operator=(const Projectile&) = delete;

    virtual void Update(float dt) { x_ += speed_ * dt; }
    virtual int Damage() const { return 10; }

    float X() const { return x_; }

protected:
    float x_;
    float speed_;
};

// Accelerates on every update and keeps the lock-on marker of its target alive.
class HomingMissile : public Projectile {
public:
    HomingMissile(float x, float speed, std::shared_ptr<LockOnMarker> marker)
        : Projectile(x, speed), marker_(std::move(marker)) {}

    void Update(float dt) override {
        speed_ += 20.0f * dt;
        x_ += speed_ * dt;
    }
    int Damage() const override { return 40; }

private:
    std::shared_ptr<LockOnMarker> marker_;
};

// Damage that gets through the armor of the target (never negative).
// Fix 1: take the projectile by reference to const. A by-value Projectile parameter
// copies only the base part of the argument (slicing), so Damage() was always 10.
int DamageAfterArmor(const Projectile& projectile, int armor) {
    const int damage = projectile.Damage() - armor;
    return damage > 0 ? damage : 0;
}

class ProjectileSystem {
public:
    void Add(std::unique_ptr<Projectile> projectile) { projectiles_.push_back(std::move(projectile)); }

    void UpdateAll(float dt) {
        for (auto& p : projectiles_) p->Update(dt);
    }

    // Total damage if every projectile hit a target with the given armor.
    int TotalDamage(int armor) const {
        int total = 0;
        for (const auto& p : projectiles_) total += DamageAfterArmor(*p, armor);
        return total;
    }

    std::size_t Count() const { return projectiles_.size(); }
    void Clear() { projectiles_.clear(); }

private:
    std::vector<std::unique_ptr<Projectile>> projectiles_;
};

tests.template:
#include <csignal>
#include <cstdio>
#include <cstring>
#include <exception>
#include <memory>
#include <string>
#include <type_traits>
#include <utility>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "base-projectile-behaves",
    "damage-after-armor-uses-derived",
    "system-total-damage-mixed",
    "update-all-dispatches-virtually",
    "base-has-virtual-destructor",
    "destroying-projectiles-releases-markers",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// A crash in learner code must still produce one line per remaining case.
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (유효하지 않은 메모리 접근 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }
std::string Flt(float v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%g", static_cast<double>(v));
    return buf;
}
bool Near(float a, float b) { return a - b < 0.001f && b - a < 0.001f; }

// Known at compile time. Deleting a derived object through a Projectile pointer is
// undefined behaviour while this is false, so the judge never does it in that case:
// it deliberately leaves the system alive instead (see SystemHolder).
const bool kVirtualDtor = std::has_virtual_destructor<Projectile>::value;

struct SystemHolder {
    ProjectileSystem* system;
    SystemHolder() : system(new ProjectileSystem) {}
    ~SystemHolder() {
        if (kVirtualDtor) delete system;
    }
    SystemHolder(const SystemHolder&) = delete;
    SystemHolder& operator=(const SystemHolder&) = delete;
};

// A projectile type the learner code has never seen.
int g_rocketsAlive = 0;
class JudgeRocket : public Projectile {
public:
    JudgeRocket(float x, float speed) : Projectile(x, speed) { ++g_rocketsAlive; }
    ~JudgeRocket() { --g_rocketsAlive; }
    int Damage() const override { return 77; }
};

std::string BaseProjectileBehaves() {
    Projectile bullet(0.0f, 10.0f);
    bullet.Update(0.5f);
    if (!Near(bullet.X(), 5.0f)) return "Projectile(0, 10).Update(0.5) 뒤 X 기대 5, 결과 " + Flt(bullet.X());
    if (bullet.Damage() != 10) return "Projectile::Damage 기대 10, 결과 " + Num(bullet.Damage());
    int got = DamageAfterArmor(bullet, 3);
    if (got != 7) return "DamageAfterArmor(기본 탄환, 방어 3) 기대 7, 결과 " + Num(got);
    got = DamageAfterArmor(bullet, 50);
    if (got != 0) return "DamageAfterArmor(기본 탄환, 방어 50) 기대 0, 결과 " + Num(got);
    return "";
}

std::string DamageUsesDerived() {
    HomingMissile missile(0.0f, 8.0f, std::make_shared<LockOnMarker>());
    int got = DamageAfterArmor(missile, 15);
    if (got != 25) return "DamageAfterArmor(HomingMissile, 방어 15) 기대 25, 결과 " + Num(got) + " (값으로 받으면 기반 부분만 복사되어 Projectile::Damage가 호출됨)";
    got = DamageAfterArmor(missile, 100);
    if (got != 0) return "DamageAfterArmor(HomingMissile, 방어 100) 기대 0, 결과 " + Num(got);
    JudgeRocket rocket(0.0f, 1.0f);
    got = DamageAfterArmor(rocket, 7);
    if (got != 70) return "DamageAfterArmor(Damage가 77인 새 파생 클래스, 방어 7) 기대 70, 결과 " + Num(got) + " (슬라이싱)";
    return "";
}

std::string SystemTotalDamageMixed() {
    SystemHolder h;
    std::shared_ptr<LockOnMarker> marker = std::make_shared<LockOnMarker>();
    if (h.system->TotalDamage(5) != 0) return "빈 시스템의 TotalDamage가 0이 아님";
    h.system->Add(std::make_unique<Projectile>(0.0f, 10.0f));
    h.system->Add(std::make_unique<HomingMissile>(0.0f, 8.0f, marker));
    h.system->Add(std::make_unique<Projectile>(1.0f, 10.0f));
    h.system->Add(std::make_unique<HomingMissile>(2.0f, 8.0f, marker));
    h.system->Add(std::make_unique<JudgeRocket>(3.0f, 1.0f));
    if (h.system->Count() != 5) return "Count 기대 5, 결과 " + Num((long long)h.system->Count());
    const int got = h.system->TotalDamage(5);  // 5 + 35 + 5 + 35 + 72
    if (got != 152) return "탄환 2 + 미사일 2 + 로켓 1, 방어 5의 TotalDamage 기대 152, 결과 " + Num(got);
    const int blocked = h.system->TotalDamage(40);  // 0 + 0 + 0 + 0 + 37
    if (blocked != 37) return "방어 40의 TotalDamage 기대 37, 결과 " + Num(blocked);
    return "";
}

std::string UpdateAllDispatches() {
    SystemHolder h;
    std::unique_ptr<Projectile> bullet = std::make_unique<Projectile>(0.0f, 10.0f);
    std::unique_ptr<Projectile> missile = std::make_unique<HomingMissile>(0.0f, 8.0f, std::make_shared<LockOnMarker>());
    const Projectile* const rawBullet = bullet.get();
    const Projectile* const rawMissile = missile.get();
    h.system->Add(std::move(bullet));
    h.system->Add(std::move(missile));
    h.system->UpdateAll(0.5f);
    if (!Near(rawBullet->X(), 5.0f)) return "UpdateAll(0.5) 뒤 탄환 X 기대 5, 결과 " + Flt(rawBullet->X());
    if (!Near(rawMissile->X(), 9.0f)) return "UpdateAll(0.5) 뒤 미사일 X 기대 9, 결과 " + Flt(rawMissile->X());
    h.system->UpdateAll(0.5f);
    if (!Near(rawBullet->X(), 10.0f)) return "UpdateAll 2회 뒤 탄환 X 기대 10, 결과 " + Flt(rawBullet->X());
    if (!Near(rawMissile->X(), 23.0f)) return "UpdateAll 2회 뒤 미사일 X 기대 23, 결과 " + Flt(rawMissile->X());
    return "";
}

std::string BaseHasVirtualDestructor() {
    if (!kVirtualDtor) return "Projectile의 소멸자가 virtual이 아님 (unique_ptr<Projectile>로 파생 객체를 파괴하는 것은 미정의 동작)";
    if (!std::has_virtual_destructor<HomingMissile>::value) return "HomingMissile의 소멸자가 virtual이 아님";
    return "";
}

std::string DestroyReleasesMarkers() {
    if (!kVirtualDtor)
        return "Projectile의 소멸자가 virtual이 아니어서 ~HomingMissile(마커 해제)이 호출된다는 보장이 없음 (미정의 동작이므로 이 케이스는 실행하지 않음)";
    std::shared_ptr<LockOnMarker> marker = std::make_shared<LockOnMarker>();
    g_rocketsAlive = 0;
    {
        ProjectileSystem system;
        system.Add(std::make_unique<HomingMissile>(0.0f, 8.0f, marker));
        system.Add(std::make_unique<HomingMissile>(1.0f, 8.0f, marker));
        system.Add(std::make_unique<Projectile>(2.0f, 10.0f));
        if (marker.use_count() != 3) return "미사일 2발이 마커를 잡고 있을 때 use_count 기대 3, 결과 " + Num(marker.use_count());
        system.Clear();
        if (system.Count() != 0) return "Clear 뒤 Count 기대 0, 결과 " + Num((long long)system.Count());
        if (marker.use_count() != 1) return "Clear 뒤에도 락온 마커 참조가 남음: use_count 기대 1, 결과 " + Num(marker.use_count()) + " (~HomingMissile이 호출되지 않음)";
        system.Add(std::make_unique<HomingMissile>(3.0f, 8.0f, marker));
        system.Add(std::make_unique<JudgeRocket>(4.0f, 1.0f));
        if (g_rocketsAlive != 1) return "JudgeRocket 생성 수가 맞지 않음";
    }
    if (marker.use_count() != 1) return "시스템이 파괴된 뒤에도 락온 마커 참조가 남음: use_count 기대 1, 결과 " + Num(marker.use_count());
    if (g_rocketsAlive != 0) return "시스템이 파괴됐는데 파생 클래스(JudgeRocket)의 소멸자가 호출되지 않음";
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    BaseProjectileBehaves, DamageUsesDerived,        SystemTotalDamageMixed,
    UpdateAllDispatches,   BaseHasVirtualDestructor, DestroyReleasesMarkers,
};

}  // namespace judge

int main() {
    using namespace judge;
    const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
    for (int s : signals) std::signal(s, OnCrash);

    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        std::string reason;
        try {
            reason = kFns[i]();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                          : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
        line += "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written; skip static destructors
}

followUps.keyAnswer:
- **왜 타입이 없는가**: `EnemyBase<SlimeC>`와 `EnemyBase<ArcherC>`는 같은 템플릿에서 나온 **서로 다른 타입**이고 공통 기반이 없습니다. CRTP는 호출하는 코드가 구체 타입을 컴파일 시점에 알 때만 동작하는 정적 다형성이라, "실행 중에 타입이 섞인 목록"은 그 자체로 표현하지 못합니다.
- **구성 예 (타입별 묶음 + 묶음 단위 가상 호출)**:
  ```cpp
  struct IEnemyGroup {
      virtual ~IEnemyGroup() = default;
      virtual float TickAll(float dt) = 0;
  };
  template <class T>
  struct EnemyGroup final : IEnemyGroup {
      std::vector<T> items;  // T = SlimeC, ArcherC, ... (값으로 연속 저장)
      float TickAll(float dt) override {
          float sum = 0.0f;
          for (T& e : items) sum += e.Tick(dt);  // 정적 호출: 인라인 가능
          return sum;
      }
  };
  std::vector<std::unique_ptr<IEnemyGroup>> groups;  // 적 종류 수만큼
  ```
  가상 호출은 프레임당 **묶음 수(12번)**만 일어나고, 3만 번의 원소 호출은 모두 정적 호출입니다. CRTP 기반 `EnemyBase<T>`는 각 적 타입이 이동·피격 같은 공통 구현을 재사용하는 데 씁니다.
- **다른 구성**: 적 종류가 닫혀 있다면 `std::variant<SlimeC, ArcherC, ...>`의 vector와 `std::visit`도 됩니다. 이 경우 원소마다 인덱스에 따른 분기가 남습니다.
- **대가**: 타입 사이의 업데이트 순서가 사라지고(종류별로 몰아서 실행), 다른 시스템이 특정 적을 가리키려면 (종류, 인덱스) 같은 핸들이 필요하며, 종류마다 템플릿 인스턴스 코드가 생깁니다. 바꾼 뒤 같은 장면에서 다시 측정합니다.

