#include <cstdio>
#include <memory>
#include <type_traits>
#include <variant>
#include <vector>

// (1) Dynamic polymorphism: open set of types, one indirect call per object.
struct Enemy {
    virtual ~Enemy() = default;
    virtual float Tick(float dt) = 0;  // damage dealt during this tick
};
struct SlimeV final : Enemy {
    float dps = 2.0f;
    float Tick(float dt) override { return dps * dt; }
};
struct ArcherV final : Enemy {
    float dps = 5.0f;
    float Tick(float dt) override { return dps * dt; }
};

// (2) CRTP: shared code reaches the derived implementation through static_cast,
// so the call is resolved at compile time. There is no common runtime base.
template <class Derived>
struct EnemyBase {
    float DamageOver(float seconds, float dt) {
        Derived& self = static_cast<Derived&>(*this);
        float total = 0.0f;
        for (float t = 0.0f; t < seconds; t += dt) total += self.Tick(dt);
        return total;
    }

protected:
    EnemyBase() = default;  // only usable as a base of Derived
};
struct SlimeC : EnemyBase<SlimeC> {
    float dps = 2.0f;
    float Tick(float dt) { return dps * dt; }
};
struct ArcherC : EnemyBase<ArcherC> {
    float dps = 5.0f;
    float Tick(float dt) { return dps * dt; }
};
static_assert(!std::is_base_of<EnemyBase<SlimeC>, ArcherC>::value,
              "EnemyBase<SlimeC> and EnemyBase<ArcherC> are unrelated types");

// (3) Closed set of types with std::variant: the value lives inside the variant,
// std::visit dispatches on the stored alternative.
struct Slime {
    float dps = 2.0f;
    float Tick(float dt) const { return dps * dt; }
};
struct Archer {
    float dps = 5.0f;
    float Tick(float dt) const { return dps * dt; }
};
using AnyEnemy = std::variant<Slime, Archer>;

// (4) Grouping by type: one homogeneous array per type, plain calls inside each loop.
struct EnemyWorld {
    std::vector<Slime> slimes;
    std::vector<Archer> archers;
};

int main() {
    const float dt = 0.5f;

    std::vector<std::unique_ptr<Enemy>> byPointer;
    for (int i = 0; i < 3; ++i) byPointer.push_back(std::make_unique<SlimeV>());
    for (int i = 0; i < 2; ++i) byPointer.push_back(std::make_unique<ArcherV>());
    float a = 0.0f;
    for (const auto& e : byPointer) a += e->Tick(dt);  // indirect call through the vtable

    SlimeC slimeC;
    ArcherC archerC;
    const float b = 3 * slimeC.DamageOver(dt, dt) + 2 * archerC.DamageOver(dt, dt);

    std::vector<AnyEnemy> byValue{Slime{}, Slime{}, Slime{}, Archer{}, Archer{}};
    float c = 0.0f;
    for (const AnyEnemy& e : byValue) c += std::visit([dt](const auto& x) { return x.Tick(dt); }, e);

    EnemyWorld world;
    world.slimes.resize(3);
    world.archers.resize(2);
    float d = 0.0f;
    for (const Slime& s : world.slimes) d += s.Tick(dt);    // Slime::Tick, statically bound
    for (const Archer& r : world.archers) d += r.Tick(dt);  // Archer::Tick, statically bound

    std::printf("damage: virtual %.1f, crtp %.1f, variant %.1f, grouped %.1f\n", a, b, c, d);
    std::printf("sizeof: SlimeV %zu, SlimeC %zu, Slime %zu, AnyEnemy %zu, unique_ptr<Enemy> %zu\n",
                sizeof(SlimeV), sizeof(SlimeC), sizeof(Slime), sizeof(AnyEnemy), sizeof(std::unique_ptr<Enemy>));
    return 0;
}

