    if (!d.empty()) return d + " (빈 핸들의 Reset이 다른 핸들의 구독을 끝냄)";
    Subscription c = bus.Subscribe<DamageEvent>(Probe(2));
    c = std::move(b);
    if (b.Active() || !c.Active()) return "이동 대입 뒤 원본은 비고 대상 핸들이 활성이어야 함";
    bus.Publish(DamageEvent{0, 4});
    d = ExpectCalls({{1, 4}}, "활성 핸들에 이동 대입한 뒤 발행");
    if (!d.empty()) return d + " (대입받은 핸들이 원래 갖고 있던 구독은 끝나야 함)";
    if (g_alive != alive0 + 1) return "이동 대입으로 끝난 구독의 핸들러 객체가 파괴되지 않음";
    { Subscription moved(std::move(c)); }
    bus.Publish(DamageEvent{0, 5});
    d = ExpectCalls({}, "구독을 넘겨받은 핸들이 파괴된 뒤 발행");
    if (!d.empty()) return d;
    std::vector<Subscription> handles;
    for (int i = 0; i < 9; ++i) handles.push_back(bus.Subscribe<DamageEvent>(Probe(10 + i)));
    bus.Publish(DamageEvent{0, 6});
    d = ExpectCalls({{10, 6}, {11, 6}, {12, 6}, {13, 6}, {14, 6}, {15, 6}, {16, 6}, {17, 6}, {18, 6}}, "핸들을 vector에 9개 담은 뒤(재할당으로 이동됨) 발행");
    if (!d.empty()) return d;
    handles.erase(handles.begin() + 3);
    bus.Publish(DamageEvent{0, 7});
    d = ExpectCalls({{10, 7}, {11, 7}, {12, 7}, {14, 7}, {15, 7}, {16, 7}, {17, 7}, {18, 7}}, "vector에서 핸들 하나를 erase 한 뒤 발행");
    if (!d.empty()) return d;
    handles.clear();
    if (bus.HandlerCount<DamageEvent>() != 0 || g_alive != alive0) return "핸들을 모두 파괴했는데 핸들러가 남음";
    return "";
}

std::string BusDestroyedFirst() {
    const int alive0 = g_alive;
    // static: if a wrong solution still reports these handles active after the bus is
    // gone, the case returns its verdict before anything touches the destroyed bus (the
    // case process ends with _exit, so these handles are never destroyed implicitly).
    static Subscription a, b, c;
    {
        EventBus* bus = new EventBus;
        a = bus->Subscribe<DamageEvent>(Probe(1));
        b = bus->Subscribe<HealEvent>(Probe(2));
        c = bus->Subscribe<DamageEvent>(Probe(3));
        c.Reset();
        if (!a.Active() || !b.Active()) return "Subscribe가 반환한 핸들의 Active()가 false";
        delete bus;
    }
    if (g_alive != alive0) return "버스가 파괴됐는데 핸들러 객체 " + Num(g_alive - alive0) + "개가 파괴되지 않음";
    if (a.Active() || b.Active()) return "버스가 파괴된 뒤에도 핸들의 Active()가 true";
    a.Reset();
    a.Reset();
    Subscription moved(std::move(b));
    if (moved.Active() || b.Active()) return "버스가 파괴된 뒤 이동한 핸들의 Active()가 true";
    { Subscription last(std::move(moved)); }
    EventBus fresh;
    Subscription e = fresh.Subscribe<DamageEvent>(Probe(4));
    c.Reset();
    fresh.Publish(DamageEvent{0, 8});
    std::string d = ExpectCalls({{4, 8}}, "먼저 파괴된 버스의 핸들을 정리한 뒤 새 버스에서 발행");
    if (!d.empty()) return d;
    return "";
}

std::string UnsubscribeDuringPublish() {
    EventBus bus;
    g_bus = &bus;
    const int alive0 = g_alive;
    g_subs[0] = bus.Subscribe<DamageEvent>(Probe(1, ActResetThird));          // ends a later handler
    g_subs[1] = bus.Subscribe<DamageEvent>(Probe(2, ActResetSecond));         // ends itself
    g_subs[2] = bus.Subscribe<DamageEvent>(Probe(3));
    g_subs[3] = bus.Subscribe<DamageEvent>(Probe(4, ActDropFourthByAssign));  // ends itself by assignment
    g_subs[4] = bus.Subscribe<DamageEvent>(Probe(5, ActResetFirst));          // ends an earlier handler
    bus.Publish(DamageEvent{0, 8});
    std::string d = ExpectCalls({{1, 8}, {2, 8}, {4, 8}, {5, 8}}, "발행 중 구독 해지");
    if (!d.empty()) return d + " (발행 도중 끝난 구독의 핸들러는 그 뒤로 호출되지 않아야 하고, 나머지는 건너뛰면 안 됨)";
    if (g_destroyedWhileRunning != 0) return "자기 구독을 끝낸 핸들러 객체가 실행 도중에 파괴됨 (" + Num(g_destroyedWhileRunning) + "회)";
    if (bus.HandlerCount<DamageEvent>() != 1) return "발행 뒤 활성 핸들러 수 기대 1, 결과 " + Num((long long)bus.HandlerCount<DamageEvent>());
    if (g_alive != alive0 + 1) return "Publish가 반환했는데 구독이 끝난 핸들러 객체가 파괴되지 않음 (살아 있는 수 기대 1, 결과 " + Num(g_alive - alive0) + ")";
    bus.Publish(DamageEvent{0, 9});
    d = ExpectCalls({{5, 9}}, "두 번째 발행");
    if (!d.empty()) return d;
    for (Subscription& s : g_subs) s.Reset();
    g_bus = nullptr;
    return "";
}

// A handler that subscribes during the publish that is calling it, then keeps using
// its own capture. With N handlers already registered, a container that doubles its
// capacity grows exactly during that Subscribe.
struct LateState {
    EventBus* bus;
    Subscription late;
    Subscription lateQuest;
    int calls;
};

std::string SubscribeDuringPublishWith(int n) {
    EventBus bus;
    LateState st{&bus, Subscription(), Subscription(), 0};
    std::vector<Subscription> subs;
    for (int i = 1; i < n; ++i) subs.push_back(bus.Subscribe<DamageEvent>(Probe(i)));
    subs.push_back(bus.Subscribe<DamageEvent>([state = &st](const DamageEvent& e) {
        if (!state->late.Active()) {
            state->late = state->bus->Subscribe<DamageEvent>(Probe(100));
            state->lateQuest = state->bus->Subscribe<QuestEvent>(Probe(200));
        }
        ++state->calls;  // reads the handler's own capture after Subscribe returned
        g_log.push_back(Call{99, e.amount});
    }));
    Subscription& late = st.late;
    const int& calls = st.calls;
    std::vector<Call> want;
    for (int i = 1; i < n; ++i) want.push_back(Call{i, 5});
    want.push_back(Call{99, 5});
    bus.Publish(DamageEvent{0, 5});
    const std::string who = "핸들러 " + Num(n) + "개 중 마지막 핸들러가 발행 중에 Subscribe";
    std::string d = ExpectCalls(want, who + ", 첫 발행");
    if (!d.empty()) return d + " (발행 중에 추가된 핸들러는 그 발행에서 호출되지 않아야 함)";
    if (calls != 1) return who + ": 핸들러의 캡처로 센 호출 수 기대 1, 결과 " + Num(calls);
    if (!late.Active()) return who + ": 발행 중에 받은 핸들의 Active()가 false";
    if (bus.HandlerCount<DamageEvent>() != static_cast<std::size_t>(n + 1)) return who + ": 발행 뒤 핸들러 수 기대 " + Num(n + 1) + ", 결과 " + Num((long long)bus.HandlerCount<DamageEvent>());
    want.clear();
    for (int i = 1; i < n; ++i) want.push_back(Call{i, 6});
    want.push_back(Call{99, 6});
    want.push_back(Call{100, 6});
    bus.Publish(DamageEvent{0, 6});
    d = ExpectCalls(want, who + ", 두 번째 발행");
    if (!d.empty()) return d + " (발행 중에 추가된 핸들러는 다음 발행부터, 구독 순서대로 호출되어야 함)";
    bus.Publish(QuestEvent{3});
    d = ExpectCalls({{200, 3}}, who + ", 발행 중에 구독한 다른 타입(QuestEvent) 발행");
    if (!d.empty()) return d;
    if (g_destroyedWhileRunning != 0) return who + ": 실행 중인 핸들러 객체가 파괴됨";
    return "";
}

std::string SubscribeDuringPublish() {
    const int sizes[] = {4, 8, 16, 32};
    for (int n : sizes) {
        std::string d = SubscribeDuringPublishWith(n);
        if (!d.empty()) return d;
    }
    return "";
}

std::string NestedPublish() {
    EventBus bus;
    g_bus = &bus;
    const int alive0 = g_alive;
    g_subs[0] = bus.Subscribe<DeathEvent>(Probe(1, ActPublishLootThenResetSecond));
    g_subs[1] = bus.Subscribe<DeathEvent>(Probe(2));
    g_subs[2] = bus.Subscribe<DeathEvent>(Probe(3));
    g_subs[3] = bus.Subscribe<LootEvent>(Probe(11));
    g_subs[4] = bus.Subscribe<LootEvent>(Probe(12, ActResetThird));  // runs inside the nested publish
    bus.Publish(DeathEvent{5});
    std::string d = ExpectCalls({{1, 5}, {11, 77}, {12, 77}}, "DeathEvent 핸들러 안에서 LootEvent를 발행");
    if (!d.empty()) return d + " (안쪽 발행이 끝난 뒤에도 바깥 발행은 이어져야 하고, 그동안 끝난 구독은 호출되지 않아야 함)";
    if (g_destroyedWhileRunning != 0) return "중첩 발행 중 실행 중인 핸들러 객체가 파괴됨";
    if (bus.HandlerCount<DeathEvent>() != 1 || bus.HandlerCount<LootEvent>() != 2)
        return "중첩 발행 뒤 핸들러 수 기대 Death 1·Loot 2, 결과 Death " + Num((long long)bus.HandlerCount<DeathEvent>()) + "·Loot " + Num((long long)bus.HandlerCount<LootEvent>());
    if (g_alive != alive0 + 3) return "가장 바깥 Publish가 반환했는데 구독이 끝난 핸들러 객체가 파괴되지 않음";
    bus.Publish(DeathEvent{6});
    d = ExpectCalls({{1, 6}, {11, 77}, {12, 77}}, "두 번째 DeathEvent 발행");
    if (!d.empty()) return d;
    Subscription self = bus.Subscribe<DamageEvent>(Probe(21, ActPublishDamageOnce));
    Subscription after = bus.Subscribe<DamageEvent>(Probe(22));
    g_nestedDone = false;
    bus.Publish(DamageEvent{0, 50});
    d = ExpectCalls({{21, 50}, {21, 1}, {22, 1}, {22, 50}}, "DamageEvent 핸들러 안에서 같은 타입을 한 번 더 발행");
    if (!d.empty()) return d;
    for (Subscription& s : g_subs) s.Reset();
