// Reference model: every subscription ever made, in subscription order.
struct ModelEntry { int tag; int type; bool active; };

std::string RandomVsReference() {
    EventBus bus;
    std::vector<ModelEntry> model;
    Subscription handles[12];
    int owner[12];
    for (int& o : owner) o = -1;
    unsigned seed = 20261122u;
    auto next = [&seed]() { seed = seed * 1664525u + 1013904223u; return seed >> 16; };
    int nextTag = 1;
    for (int step = 0; step < 400; ++step) {
        const unsigned op = next() % 10;
        const int k = static_cast<int>(next() % 12);
        const std::string at = "step " + Num(step) + ": ";
        if (op < 4) {
            const int type = static_cast<int>(next() % 3);
            if (owner[k] >= 0) model[owner[k]].active = false;
            const int tag = nextTag++;
            if (type == 0) handles[k] = bus.Subscribe<DamageEvent>(Probe(tag));
            else if (type == 1) handles[k] = bus.Subscribe<HealEvent>(Probe(tag));
            else handles[k] = bus.Subscribe<LootEvent>(Probe(tag));
            model.push_back(ModelEntry{tag, type, true});
            owner[k] = static_cast<int>(model.size()) - 1;
        } else if (op < 6) {
            handles[k].Reset();
            if (owner[k] >= 0) model[owner[k]].active = false;
            owner[k] = -1;
        } else if (op < 7) {
            const int j = static_cast<int>(next() % 12);
            if (j == k) continue;
            handles[j] = std::move(handles[k]);
            if (owner[j] >= 0) model[owner[j]].active = false;
            owner[j] = owner[k];
            owner[k] = -1;
        } else {
            const int type = static_cast<int>(next() % 3);
            const int value = static_cast<int>(next() % 1000);
            std::vector<Call> want;
            for (const ModelEntry& m : model) {
                if (m.active && m.type == type) want.push_back(Call{m.tag, value});
            }
            if (type == 0) bus.Publish(DamageEvent{0, value});
            else if (type == 1) bus.Publish(HealEvent{0, value});
            else bus.Publish(LootEvent{value});
            std::string d = ExpectCalls(want, at + "발행");
            if (!d.empty()) return d;
        }
        std::size_t counts[3] = {0, 0, 0};
        for (const ModelEntry& m : model) {
            if (m.active) ++counts[m.type];
        }
        if (bus.HandlerCount<DamageEvent>() != counts[0] || bus.HandlerCount<HealEvent>() != counts[1] || bus.HandlerCount<LootEvent>() != counts[2])
            return at + "HandlerCount가 기준 구현과 다름";
        for (int s = 0; s < 12; ++s) {
            if (handles[s].Active() != (owner[s] >= 0)) return at + "핸들 " + Num(s) + "의 Active()가 기준 구현과 다름";
        }
    }
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    PublishMatchesTypeAndOrder, ResetAndDestructor,     MoveTransfers, BusDestroyedFirst,
    UnsubscribeDuringPublish,   SubscribeDuringPublish, NestedPublish, RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i]
                                      : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

// ---- process isolation: every case runs in its own child process ----

volatile std::sig_atomic_t g_current = 0;

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료 (파괴된 버스나 옮겨진 핸들러를 사용했을 가능성)\n"
                            : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 1;  // a correct case finishes in milliseconds
const int kMaxTimeouts = 3;       // after this many, the remaining cases are not started

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): 표준 라이브러리 검사 모드가 무효화된 반복자나 범위 밖 인덱스 사용을 감지했을 가능성 (발행 중에 핸들러 목록을 지우거나 늘렸는지 확인)";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (끝나지 않는 루프 가능성)";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (파괴된 버스에 접근했거나, 실행 중인 핸들러의 저장소가 옮겨지거나 해제되었을 가능성)";
        if (sig == SIGKILL) return "실행 환경이 프로세스를 강제 종료함 (메모리 한도 초과 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Checked-library reports are word-wrapped at about 78 columns by default. In
    // libstdc++ 13 a single word of exactly 77 columns (a long type name, for example)
    // makes that wrapping print blank lines until the process is killed (reproduced on
    // this judge). A large GLIBCXX_DEBUG_MESSAGE_LENGTH, a variable the libstdc++ manual
    // documents, turns the wrapping off in practice.
    setenv("GLIBCXX_DEBUG_MESSAGE_LENGTH", "100000", 1);
    int timeouts = 0;
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        if (timeouts >= kMaxTimeouts) {
            const std::string skipped = std::string("[FAIL] ") + kCases[i] + " :: 앞선 케이스 " + Num(timeouts) +
                                        "개가 시간 초과되어 이 케이스는 실행하지 않음 (끝나지 않는 루프를 먼저 고치세요)\n";
            Emit(skipped.c_str());
            continue;
        }
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            struct rlimit memory;
            memory.rlim_cur = memory.rlim_max = static_cast<rlim_t>(256) * 1024 * 1024;
            setrlimit(RLIMIT_AS, &memory);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            // No process isolation available: run in this process. A crash then ends the
            // run, and OnCrash still writes one line for every remaining case.
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        if (waited == pid && WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) ++timeouts;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);  // every verdict line is already written
}

