#include <cstddef>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>

// Loot bag of one party member, shown in the inventory UI. T is an item type with an
// int member `weight`. Copying an item can throw (items own strings and affix lists,
// and the console build's allocator throws std::bad_alloc when the budget runs out).
// The encumbrance bar reads TotalWeight() every frame, so the sum is cached.
template <class T>
class LootBag {
    static_assert(std::is_nothrow_move_constructible<T>::value && std::is_nothrow_move_assignable<T>::value,
                  "items must move without throwing");

public:
    std::size_t Size() const noexcept { return items_.size(); }
    int TotalWeight() const noexcept { return totalWeight_; }
    const T& At(std::size_t index) const { return items_.at(index); }

    // Puts a copy of item at the end of the bag.
    void Add(const T& item) {
        totalWeight_ += item.weight;
        items_.push_back(item);
    }

    // Opening a chest: every item of the drop goes into the bag, in drop order.
    void AddAll(const std::vector<T>& drop) {
        for (const T& item : drop) {
            Add(item);
        }
    }

    // Hands the item at index over to another party member's bag (dest is never *this).
    // The items left behind keep their order. Throws std::out_of_range for a bad index.
    void TransferTo(LootBag& dest, std::size_t index) {
        T item = std::move(items_.at(index));
        items_.erase(items_.begin() + static_cast<std::ptrdiff_t>(index));
        totalWeight_ -= item.weight;
        dest.Add(item);
    }

private:
    std::vector<T> items_;
    int totalWeight_ = 0;
};

problems.solutionCode:
#include <cstddef>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>

// Loot bag of one party member, shown in the inventory UI. T is an item type with an
// int member `weight`. Copying an item can throw (items own strings and affix lists,
// and the console build's allocator throws std::bad_alloc when the budget runs out).
// The encumbrance bar reads TotalWeight() every frame, so the sum is cached.
//
// Invariant: totalWeight_ == sum of items_[i].weight.
// Add, AddAll and TransferTo give the strong guarantee: if they throw, every bag they
// touched has the same items, order and TotalWeight() as before the call.
template <class T>
class LootBag {
    static_assert(std::is_nothrow_move_constructible<T>::value && std::is_nothrow_move_assignable<T>::value,
                  "items must move without throwing");

public:
    std::size_t Size() const noexcept { return items_.size(); }
    int TotalWeight() const noexcept { return totalWeight_; }
    const T& At(std::size_t index) const { return items_.at(index); }

    // Puts a copy of item at the end of the bag.
    void Add(const T& item) {
        // Fix 1: do the step that can throw first. push_back at the end has the strong
        // guarantee, and the cache is updated only after it succeeded (int += cannot throw).
        items_.push_back(item);
        totalWeight_ += item.weight;
    }

    // Opening a chest: every item of the drop goes into the bag, in drop order.
    void AddAll(const std::vector<T>& drop) {
        // Fix 2: all or nothing. Each push_back either adds one item or changes nothing;
        // if a later copy throws, the items added by this call are popped again
        // (pop_back cannot throw) and the exception goes on to the caller.
        // No reserve(oldSize + drop.size()) here: called on every chest it would grow
        // the capacity linearly instead of geometrically.
        const std::size_t oldSize = items_.size();
        int addedWeight = 0;
        try {
            for (const T& item : drop) {
                items_.push_back(item);
                addedWeight += item.weight;
            }
        } catch (...) {
            while (items_.size() > oldSize) {
                items_.pop_back();
            }
            throw;
        }
        totalWeight_ += addedWeight;  // commit: cannot throw
    }

    // Hands the item at index over to another party member's bag (dest is never *this).
    // The items left behind keep their order. Throws std::out_of_range for a bad index.
    void TransferTo(LootBag& dest, std::size_t index) {
        // Fix 3: copy into dest BEFORE removing from this bag. Until dest.Add returns,
        // nothing has changed anywhere (Add is strong). After that only non-throwing
        // steps remain: erase moves the later items with T's noexcept move assignment.
        const T& item = items_.at(index);  // may throw out_of_range: nothing changed yet
        const int weight = item.weight;
        dest.Add(item);
        items_.erase(items_.begin() + static_cast<std::ptrdiff_t>(index));
        totalWeight_ -= weight;
    }

private:
    std::vector<T> items_;
    int totalWeight_ = 0;
};

tests.template:
#include <cstdio>
#include <exception>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

// Failure injection: the n-th item copy from now on throws CopyFailed (0 = never).
// Copy construction and copy assignment both count; moves never throw.
struct CopyFailed : std::runtime_error {
    CopyFailed() : std::runtime_error("item copy failed (injected)") {}
};
int g_failAt = 0;
long g_copies = 0;     // copy constructions + copy assignments
long g_moveCtors = 0;  // move constructions (vector reallocation moves items)
long g_live = 0;       // items constructed minus items destroyed

void CountCopy() {
    ++g_copies;
    if (g_failAt > 0 && --g_failAt == 0) throw CopyFailed();
}

struct Item {
    int id = 0;
    int weight = 0;
    Item(int i, int w) : id(i), weight(w) { ++g_live; }
    Item(const Item& o) : id(o.id), weight(o.weight) {
        CountCopy();
        ++g_live;
    }
    Item(Item&& o) noexcept : id(o.id), weight(o.weight) {
        ++g_moveCtors;
        ++g_live;
    }
    Item& operator=(const Item& o) {
        CountCopy();
        id = o.id;
        weight = o.weight;
        return *this;
    }
    Item& operator=(Item&& o) noexcept {
        id = o.id;
        weight = o.weight;
        return *this;
    }
    ~Item() { --g_live; }
};

using Bag = LootBag<Item>;
using Model = std::vector<std::pair<int, int>>;  // (id, weight) in bag order

std::string Num(long long v) { return std::to_string(v); }

std::string Show(const Model& m) {
    std::string s = "[";
    for (std::size_t i = 0; i < m.size(); ++i) s += (i ? " " : "") + Num(m[i].first);
    return s + "]";
}

Model Read(const Bag& bag) {
    Model m;
    for (std::size_t i = 0; i < bag.Size(); ++i) m.push_back({bag.At(i).id, bag.At(i).weight});
    return m;
}

int WeightOf(const Model& m) {
    int w = 0;
    for (const auto& e : m) w += e.second;
    return w;
}

// Compares a bag with the expected items (ids in order) and checks TotalWeight().
std::string Check(const Bag& bag, const Model& want, const std::string& who) {
    const Model got = Read(bag);
    if (got != want) return who + " 아이템 id 기대 " + Show(want) + ", 결과 " + Show(got);
    if (bag.TotalWeight() != WeightOf(want))
        return who + " TotalWeight 기대 " + Num(WeightOf(want)) + ", 결과 " + Num(bag.TotalWeight()) + " (캐시가 내용과 어긋남)";
    return "";
}

Bag Make(const Model& m) {
    Bag bag;
    for (const auto& e : m) bag.Add(Item(e.first, e.second));
    return bag;
}

std::vector<Item> Drop(const Model& m) {
    std::vector<Item> v;
    v.reserve(m.size());
    for (const auto& e : m) v.emplace_back(e.first, e.second);
    return v;
}

Model Concat(Model x, const Model& y) {
    x.insert(x.end(), y.begin(), y.end());
    return x;
}

const Model kA = {{1, 5}, {2, 7}};
const Model kDrop = {{10, 3}, {11, 4}, {12, 6}, {13, 2}};

std::string AddOk() {
    Bag bag;
    bag.Add(Item(1, 5));
    bag.Add(Item(2, 7));
    bag.Add(Item(3, 4));
    return Check(bag, {{1, 5}, {2, 7}, {3, 4}}, "Add 3번:");
}

std::string AddFailure() {
    Bag bag = Make(kA);
    const Item item(3, 4);
    g_failAt = 1;
    bool threw = false;
    try {
        bag.Add(item);
    } catch (const CopyFailed&) {
        threw = true;
    }
    g_failAt = 0;
    if (!threw) return "첫 복사에서 던진 CopyFailed가 Add 밖으로 전파되지 않음";
    std::string d = Check(bag, kA, "복사가 실패한 Add 뒤:");
    if (!d.empty()) return d;
    bag.Add(item);
    return Check(bag, {{1, 5}, {2, 7}, {3, 4}}, "실패 뒤 다시 Add:");
}

std::string AddAllOk() {
    Bag bag = Make(kA);
    const std::vector<Item> drop = Drop(kDrop);
    g_copies = 0;
    bag.AddAll(drop);
    const long copies = g_copies;
    const Model want = Concat(kA, kDrop);
    std::string d = Check(bag, want, "AddAll 성공:");
    if (!d.empty()) return d;
    bag.AddAll({});
    d = Check(bag, want, "빈 drop AddAll:");
    if (!d.empty()) return d;
    if (copies > 4) return "아이템 4개 AddAll에 복사 " + Num(copies) + "번 (드롭 크기만큼만 복사해야 함)";
    return "";
}

struct Two {
    Bag a, b;
    std::vector<Item> drop;
};

// Runs op with the n-th copy failing, for n = 1, 2, ... until op succeeds. Every failed
// attempt must leave the bags exactly as they were; the successful one must finish.
template <class Setup, class Op, class Unchanged, class Done>
std::string EveryFailurePoint(Setup setup, Op op, Unchanged unchanged, Done done, const char* what) {
    for (int n = 1; n <= 12; ++n) {
        Two state = setup();
        g_failAt = n;
        bool threw = false;
        try {
            op(state);
        } catch (const CopyFailed&) {
            threw = true;
        }
        g_failAt = 0;
        const std::string d = threw ? unchanged(state) : done(state);
        if (!d.empty())
            return std::string(what) + " " + Num(n) + "번째 복사에 실패 주입" + (threw ? "(예외 발생) 뒤 " : "(예외 없이 끝남) 뒤 ") + d;
        if (!threw) return "";
    }
    return std::string(what) + ": 복사가 12번 넘게 일어남";
}

std::string AddAllFailure() {
    auto setup = [] { return Two{Make(kA), Bag(), Drop(kDrop)}; };
    auto op = [](Two& s) { s.a.AddAll(s.drop); };
    auto unchanged = [](Two& s) { return Check(s.a, kA, "가방:"); };
    auto done = [](Two& s) { return Check(s.a, Concat(kA, kDrop), "가방:"); };
    return EveryFailurePoint(setup, op, unchanged, done, "AddAll(아이템 4개)의");
}

std::string AddAllCopyBudget() {
    Model big;
    for (int i = 0; i < 300; ++i) big.push_back({100 + i, 1 + i % 5});
    Bag bag = Make(big);
    const Model small = {{7, 2}, {8, 3}, {9, 4}};
    const std::vector<Item> drop = Drop(small);
    g_copies = 0;
    bag.AddAll(drop);
    const long copies = g_copies;
    std::string d = Check(bag, Concat(big, small), "아이템 300개 가방에 AddAll:");
    if (!d.empty()) return d;
    if (copies > 3) return "아이템 300개 가방에 3개를 AddAll 하는 데 복사 " + Num(copies) + "번 (기대 3번 이하: 가방 전체를 복사하지 않음)";
    // 300 chests of one item each: with geometric growth the reallocations move each
    // item only a few times in total; growing the capacity by exactly k per call moves
    // the whole bag on almost every call once the spare capacity is used up.
    long moves = 0;
    Model all = Concat(big, small);
    for (int i = 0; i < 300; ++i) {
        const std::vector<Item> one = Drop({{1000 + i, 1}});
        all.push_back({1000 + i, 1});
        g_moveCtors = 0;
        bag.AddAll(one);
        moves += g_moveCtors;
    }
    d = Check(bag, all, "아이템 1개짜리 AddAll 300번 뒤:");
    if (!d.empty()) return d;
    if (moves > 5000)
        return "아이템 1개짜리 AddAll 300번에 아이템 이동 " + Num(moves) + "번 (기대 5000번 이하: 용량이 기하급수가 아니라 선형으로 늘어남, 예: 매번 reserve(size + k))";
    return "";
}

std::string TransferOk() {
    Bag a = Make({{1, 5}, {2, 7}, {3, 4}});
    Bag b = Make({{9, 1}});
    g_copies = 0;
    a.TransferTo(b, 1);
    const long copies = g_copies;
    std::string d = Check(a, {{1, 5}, {3, 4}}, "넘겨준 가방:");
    if (!d.empty()) return d;
    d = Check(b, {{9, 1}, {2, 7}}, "받은 가방:");
    if (!d.empty()) return d;
    if (copies > 1) return "아이템 1개를 넘기는 데 복사 " + Num(copies) + "번 (기대 1번 이하)";
    bool threw = false;
    try {
        a.TransferTo(b, 2);
    } catch (const std::out_of_range&) {
        threw = true;
    }
    if (!threw) return "범위 밖 index(2, 가방 크기 2)에서 std::out_of_range가 나오지 않음";
    d = Check(a, {{1, 5}, {3, 4}}, "범위 밖 index 뒤 넘겨준 가방:");
    if (!d.empty()) return d;
    return Check(b, {{9, 1}, {2, 7}}, "범위 밖 index 뒤 받은 가방:");
}

std::string TransferFailure() {
    const Model a0 = {{1, 5}, {2, 7}, {3, 4}};
    const Model b0 = {{9, 1}};
    auto setup = [&] { return Two{Make(a0), Make(b0), {}}; };
    auto op = [](Two& s) { s.a.TransferTo(s.b, 1); };
    auto unchanged = [&](Two& s) {
        std::string d = Check(s.a, a0, "넘겨준 가방:");
        return d.empty() ? Check(s.b, b0, "받은 가방:") : d;
    };
    auto done = [](Two& s) {
        std::string d = Check(s.a, {{1, 5}, {3, 4}}, "넘겨준 가방:");
        return d.empty() ? Check(s.b, {{9, 1}, {2, 7}}, "받은 가방:") : d;
    };
    return EveryFailurePoint(setup, op, unchanged, done, "TransferTo(1번 칸)의");
}

// 400 random operations on three bags with random copy failures, compared with a model
// that applies an operation only when it did not throw.
std::string RandomVsReference() {
    unsigned seed = 20261122u;
    auto next = [&](unsigned mod) {
        seed = seed * 1664525u + 1013904223u;
        return static_cast<int>((seed >> 16) % mod);
    };
    Bag bags[3];
    Model models[3];
    int nextId = 1;
    for (int step = 0; step < 400; ++step) {
        const int kind = next(3), who = next(3), fail = next(4) == 0 ? 1 + next(3) : 0;
        bool threw = false;
        Model after = models[who];
        int other = -1;
        Model otherAfter;
        try {
            if (kind == 0) {
                const Item item(nextId++, 1 + next(9));
                after.push_back({item.id, item.weight});
                g_failAt = fail;
                bags[who].Add(item);
            } else if (kind == 1) {
                Model d;
                const int k = next(4);
                for (int i = 0; i < k; ++i) d.push_back({nextId++, 1 + next(9)});
                const std::vector<Item> drop = Drop(d);
                after = Concat(after, d);
                g_failAt = fail;
                bags[who].AddAll(drop);
            } else {
                other = (who + 1 + next(2)) % 3;
                const std::size_t index = static_cast<std::size_t>(next(static_cast<unsigned>(models[who].size()) + 1));
                otherAfter = models[other];
                const bool valid = index < after.size();
                if (valid) {
                    otherAfter.push_back(after[index]);
                    after.erase(after.begin() + static_cast<std::ptrdiff_t>(index));
                }
                g_failAt = fail;
                try {
                    bags[who].TransferTo(bags[other], index);
                    if (!valid) return "step " + Num(step) + ": 범위 밖 index에서 std::out_of_range가 나오지 않음";
                } catch (const std::out_of_range&) {
                    if (valid) throw;
                    threw = true;
                }
            }
        } catch (const CopyFailed&) {
            threw = true;
        }
        g_failAt = 0;
        if (!threw) {
            models[who] = after;
            if (other >= 0) models[other] = otherAfter;
        }
        for (int i = 0; i < 3; ++i) {
            const std::string d = Check(bags[i], models[i], "step " + Num(step) + (threw ? "(작업 실패 뒤) " : "(작업 성공 뒤) ") + "가방 " + Num(i) + ":");
            if (!d.empty()) return d;
        }
    }
    return "";
}

typedef std::string (*CaseFn)();
struct Case {
    const char* name;
    CaseFn fn;
};
const Case kCases[] = {
    {"add-keeps-order-and-weight", AddOk},
    {"add-failed-copy-changes-nothing", AddFailure},
    {"addall-success", AddAllOk},
    {"addall-all-or-nothing", AddAllFailure},
    {"addall-cost-follows-drop-size", AddAllCopyBudget},
    {"transfer-success-and-bad-index", TransferOk},
    {"transfer-failure-keeps-both-bags", TransferFailure},
    {"random-ops-with-failures", RandomVsReference},
};

}  // namespace judge

int main() {
    using namespace judge;
    for (const Case& c : kCases) {
        std::string reason;
        const long liveBefore = g_live;
        try {
            reason = c.fn();
        } catch (const std::exception& e) {
            reason = std::string("예상하지 못한 예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        g_failAt = 0;
        if (reason.empty() && g_live != liveBefore)
            reason = "케이스가 끝난 뒤 살아 있는 아이템 수가 " + Num(g_live - liveBefore) + "개 어긋남 (누수 또는 이중 파괴)";
        if (reason.empty()) {
            std::printf("[PASS] %s\n", c.name);
        } else {
            std::printf("[FAIL] %s :: %s\n", c.name, reason.c_str());
        }
        g_live = liveBefore;
    }
    return 0;
}

