#include <cstddef>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

// Read and written by the movement loop for every unit, every frame.
struct UnitHot {
    float x = 0, y = 0;    // position
    float vx = 0, vy = 0;  // velocity, units per second
};

// Read by the UI, AI decisions and the death handler; rarely touched.
struct UnitCold {
    std::string name;
    int prefabId = 0;
    int lootTableId = 0;
    double spawnTime = 0;
};

// Stable handle that gameplay code keeps instead of an index or a pointer.
// 0 never names a unit. Ids are handed out as 1, 2, 3, ... and never reused.
using UnitId = std::uint32_t;

// Hot and cold halves live in two parallel dense arrays (same index = same unit).
// Two small tables connect them to the stable ids:
//   indexOf_[id]  -> dense index of that unit, or kDead
//   idOf_[index]  -> id of the unit at that dense index (needed by swap-and-pop)
// Invariant: for every dense index i, indexOf_[idOf_[i]] == i.
class UnitStore {
public:
    // Adds a unit at the end of the dense arrays and returns its id.
    UnitId Spawn(const UnitHot& hot, UnitCold cold) {
        const UnitId id = static_cast<UnitId>(indexOf_.size());  // indexOf_[0] is a dummy
        const std::uint32_t index = static_cast<std::uint32_t>(hot_.size());
        hot_.push_back(hot);
        cold_.push_back(std::move(cold));
        idOf_.push_back(id);
        indexOf_.push_back(index);
        return id;
    }

    // Removes the unit: the last unit moves into its place (swap-and-pop).
    // Returns false, and changes nothing, if id does not name a live unit.
    bool Despawn(UnitId id) {
        if (!Alive(id)) return false;
        const std::uint32_t hole = indexOf_[id];
        const std::uint32_t last = static_cast<std::uint32_t>(hot_.size() - 1);
        if (hole != last) {
            // Move the last unit into the hole, in all three dense arrays, and tell the
            // id table where that unit lives now.
            hot_[hole] = hot_[last];
            cold_[hole] = std::move(cold_[last]);
            idOf_[hole] = idOf_[last];
            indexOf_[idOf_[hole]] = hole;
        }
        hot_.pop_back();
        cold_.pop_back();
        idOf_.pop_back();
        indexOf_[id] = kDead;  // last: when hole == last, the moved unit would be id itself
        return true;
    }

    // nullptr if id does not name a live unit. Valid until the next Spawn or Despawn.
    UnitHot* Hot(UnitId id) { return Alive(id) ? &hot_[indexOf_[id]] : nullptr; }
    const UnitCold* Cold(UnitId id) const { return Alive(id) ? &cold_[indexOf_[id]] : nullptr; }

    std::size_t Count() const { return hot_.size(); }

    // Moves every live unit by velocity * dt. Touches only the hot array.
    void Integrate(float dt) {
        for (UnitHot& u : hot_) {
            u.x += u.vx * dt;
            u.y += u.vy * dt;
        }
    }

    // Dense views for systems. Element i of HotUnits() and of ColdUnits() belong to the
    // same unit, whose id is IdAt(i). Exactly Count() elements, no holes.
    const std::vector<UnitHot>& HotUnits() const { return hot_; }
    const std::vector<UnitCold>& ColdUnits() const { return cold_; }
    UnitId IdAt(std::size_t denseIndex) const { return idOf_[denseIndex]; }

private:
    static constexpr std::uint32_t kDead = 0xFFFFFFFFu;

    bool Alive(UnitId id) const { return id != 0 && id < indexOf_.size() && indexOf_[id] != kDead; }

    std::vector<UnitHot> hot_;
    std::vector<UnitCold> cold_;
    std::vector<UnitId> idOf_;                  // dense index -> id
    std::vector<std::uint32_t> indexOf_{kDead};  // id -> dense index; slot 0 is never a unit
};

