#include <cstdio>
#include <exception>
#include <string>
#include <utility>
#include <vector>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

std::string Num(long long v) { return std::to_string(v); }

struct Ref {
    UnitId id;
    UnitHot hot;
    UnitCold cold;
};

// Reference store: one dense vector, removal by swapping with the last element.
struct Model {
    std::vector<Ref> units;
    UnitId nextId = 1;
    UnitId Spawn(const UnitHot& h, const UnitCold& c) {
        units.push_back(Ref{nextId, h, c});
        return nextId++;
    }
    bool Despawn(UnitId id) {
        for (std::size_t i = 0; i < units.size(); ++i) {
            if (units[i].id != id) continue;
            units[i] = units.back();
            units.pop_back();
            return true;
        }
        return false;
    }
    const Ref* Find(UnitId id) const {
        for (const Ref& r : units)
            if (r.id == id) return &r;
        return nullptr;
    }
};

UnitHot H(float x, float y, float vx = 0, float vy = 0) {
    UnitHot h;
    h.x = x;
    h.y = y;
    h.vx = vx;
    h.vy = vy;
    return h;
}

UnitCold C(const std::string& name, int prefab) {
    UnitCold c;
    c.name = name;
    c.prefabId = prefab;
    c.lootTableId = prefab * 10;
    c.spawnTime = prefab * 0.5;
    return c;
}

bool SameHot(const UnitHot& a, const UnitHot& b) { return a.x == b.x && a.y == b.y && a.vx == b.vx && a.vy == b.vy; }
bool SameCold(const UnitCold& a, const UnitCold& b) {
    return a.name == b.name && a.prefabId == b.prefabId && a.lootTableId == b.lootTableId && a.spawnTime == b.spawnTime;
}

// Dense order around position `at`, at most 8 ids, so failure lines stay short.
std::string Window(const std::vector<UnitId>& ids, std::size_t at) {
    const std::size_t from = at > 3 ? at - 3 : 0, to = from + 8 < ids.size() ? from + 8 : ids.size();
    std::string s = from ? "[... " : "[";
    for (std::size_t i = from; i < to; ++i) s += (i > from ? " " : "") + Num(ids[i]);
    return s + (to < ids.size() ? " ...]" : "]");
}

std::string OrderDiff(const UnitStore& s, const Model& m, std::size_t at) {
    std::vector<UnitId> want, got;
    for (const Ref& r : m.units) want.push_back(r.id);
    for (std::size_t i = 0; i < s.Count(); ++i) got.push_back(s.IdAt(i));
    return "위치 " + Num((long long)at) + " 부근 id 순서 기대 " + Window(want, at) + ", 결과 " + Window(got, at);
}

// Full comparison: dense order, both arrays aligned, every id lookup.
std::string Compare(UnitStore& s, const Model& m, const std::string& who) {
    if (s.Count() != m.units.size()) return who + " Count 기대 " + Num((long long)m.units.size()) + ", 결과 " + Num((long long)s.Count());
    if (s.HotUnits().size() != s.Count() || s.ColdUnits().size() != s.Count())
        return who + " HotUnits/ColdUnits 크기가 Count와 다름 (빈칸 없이 촘촘해야 함)";
    for (std::size_t i = 0; i < m.units.size(); ++i) {
        const Ref& r = m.units[i];
        if (s.IdAt(i) != r.id) return who + " 촘촘한 배열의 " + OrderDiff(s, m, i) + " (지운 자리에는 마지막 유닛이 와야 함)";
        if (!SameHot(s.HotUnits()[i], r.hot)) return who + " HotUnits()[" + Num((long long)i) + "]가 id " + Num(r.id) + "의 hot 데이터가 아님";
        if (!SameCold(s.ColdUnits()[i], r.cold)) return who + " ColdUnits()[" + Num((long long)i) + "]가 id " + Num(r.id) + "의 cold 데이터가 아님 (" + s.ColdUnits()[i].name + ")";
        const UnitHot* h = s.Hot(r.id);
        const UnitCold* c = static_cast<const UnitStore&>(s).Cold(r.id);
        if (h == nullptr || c == nullptr) return who + " 살아 있는 id " + Num(r.id) + "의 Hot/Cold가 nullptr";
        if (h != &s.HotUnits()[i]) return who + " Hot(" + Num(r.id) + ")가 HotUnits()의 해당 원소를 가리키지 않음";
        if (c != &s.ColdUnits()[i]) return who + " Cold(" + Num(r.id) + ")가 ColdUnits()의 해당 원소를 가리키지 않음";
    }
    return "";
}

std::string DeadEverywhere(UnitStore& s, UnitId id, const std::string& who) {
    if (s.Hot(id) != nullptr || static_cast<const UnitStore&>(s).Cold(id) != nullptr)
        return who + " 살아 있지 않은 id " + Num(id) + "의 Hot/Cold가 nullptr가 아님";
    return "";
}

std::string SpawnAndLookup() {
    if (sizeof(UnitHot) != 4 * sizeof(float)) return "UnitHot에 멤버가 추가됨: hot 구조체는 이동 루프가 쓰는 네 값만 가져야 함";
    UnitStore s;
    Model m;
    const char* names[] = {"Grunt", "Archer", "Wyvern"};
    for (int i = 0; i < 3; ++i) {
        const UnitId want = m.Spawn(H(i * 1.f, i * 2.f, 1.f, -1.f), C(names[i], 100 + i));
        const UnitId got = s.Spawn(H(i * 1.f, i * 2.f, 1.f, -1.f), C(names[i], 100 + i));
        if (got != want) return "Spawn 반환 id 기대 " + Num(want) + ", 결과 " + Num(got);
    }
    std::string d = Compare(s, m, "Spawn 3번:");
    if (!d.empty()) return d;
    s.Hot(2)->x = 42.f;
    m.units[1].hot.x = 42.f;
    d = Compare(s, m, "Hot(2)->x = 42 뒤:");
    if (!d.empty()) return d;
    return DeadEverywhere(s, 0, "id 0:");
}

std::string DespawnMiddle() {
    UnitStore s;
    Model m;
    for (int i = 1; i <= 5; ++i) {
        m.Spawn(H(i * 10.f, 0), C("U" + Num(i), i));
        s.Spawn(H(i * 10.f, 0), C("U" + Num(i), i));
    }
    if (!s.Despawn(2)) return "살아 있는 id 2의 Despawn이 false";
    m.Despawn(2);
    std::string d = Compare(s, m, "5마리 중 id 2 Despawn 뒤:");
    if (!d.empty()) return d;
    d = DeadEverywhere(s, 2, "Despawn한 id 2:");
    if (!d.empty()) return d;
    s.Despawn(1);
    m.Despawn(1);
    return Compare(s, m, "이어서 id 1 Despawn 뒤:");
}

std::string DespawnLastAndOnly() {
    UnitStore s;
    Model m;
    for (int i = 1; i <= 3; ++i) {
        m.Spawn(H(i * 1.f, 0), C("U" + Num(i), i));
        s.Spawn(H(i * 1.f, 0), C("U" + Num(i), i));
    }
    if (!s.Despawn(3)) return "마지막 유닛 id 3의 Despawn이 false";
    m.Despawn(3);
    std::string d = Compare(s, m, "마지막 유닛(id 3) Despawn 뒤:");
    if (!d.empty()) return d;
    d = DeadEverywhere(s, 3, "Despawn한 id 3:");
    if (!d.empty()) return d;
    s.Despawn(1);
    m.Despawn(1);
    s.Despawn(2);
    m.Despawn(2);
    d = Compare(s, m, "전부 Despawn 뒤:");
    if (!d.empty()) return d;
    const UnitId again = s.Spawn(H(7, 7), C("Late", 9));
    m.Spawn(H(7, 7), C("Late", 9));
    if (again != 4) return "모두 지운 뒤 Spawn한 id 기대 4(재사용 없음), 결과 " + Num(again);
    return Compare(s, m, "다시 Spawn 뒤:");
}

std::string InvalidIds() {
    UnitStore s;
    if (s.Despawn(0) || s.Despawn(1)) return "빈 저장소에서 Despawn이 true";
    s.Spawn(H(1, 1), C("A", 1));
    s.Spawn(H(2, 2), C("B", 2));
    if (s.Despawn(0)) return "Despawn(0)이 true (0은 유닛이 아님)";
    if (s.Despawn(999)) return "발급한 적 없는 id 999의 Despawn이 true";
    if (!s.Despawn(1)) return "살아 있는 id 1의 Despawn이 false";
    if (s.Despawn(1)) return "이미 Despawn한 id 1을 다시 Despawn하자 true";
    if (s.Count() != 1) return "잘못된 Despawn 뒤 Count 기대 1, 결과 " + Num((long long)s.Count());
    std::string d = DeadEverywhere(s, 999, "id 999:");
    if (!d.empty()) return d;
    d = DeadEverywhere(s, 1, "Despawn한 id 1:");
    if (!d.empty()) return d;
    const UnitCold* c = static_cast<const UnitStore&>(s).Cold(2);
    if (c == nullptr || c->name != "B") return "남은 id 2의 Cold가 잘못됨";
    return "";
}

std::string IntegrateMovesLive() {
    UnitStore s;
    Model m;
    for (int i = 1; i <= 6; ++i) {
        m.Spawn(H(i * 1.f, 0, 2.f * i, -4.f), C("U" + Num(i), i));
        s.Spawn(H(i * 1.f, 0, 2.f * i, -4.f), C("U" + Num(i), i));
    }
    s.Despawn(2);
    m.Despawn(2);
    s.Despawn(5);
    m.Despawn(5);
    s.Integrate(0.5f);
    s.Integrate(0.25f);
    for (Ref& r : m.units) {
        r.hot.x += r.hot.vx * 0.5f;
        r.hot.y += r.hot.vy * 0.5f;
        r.hot.x += r.hot.vx * 0.25f;
        r.hot.y += r.hot.vy * 0.25f;
    }
    return Compare(s, m, "Integrate(0.5), Integrate(0.25) 뒤:");
}

std::string IdsNeverReused() {
    UnitStore s;
    std::vector<UnitId> dead;
    for (int round = 0; round < 50; ++round) {
        const UnitId a = s.Spawn(H(0, 0), C("A", round));
        const UnitId b = s.Spawn(H(1, 1), C("B", round));
        if (a != static_cast<UnitId>(2 * round + 1) || b != static_cast<UnitId>(2 * round + 2))
            return "round " + Num(round) + ": Spawn id 기대 " + Num(2 * round + 1) + "/" + Num(2 * round + 2) + ", 결과 " + Num(a) + "/" + Num(b);
        s.Despawn(a);
        dead.push_back(a);
    }
    for (UnitId id : dead) {
        std::string d = DeadEverywhere(s, id, "Despawn한 id:");
        if (!d.empty()) return d;
    }
    if (s.Count() != 50) return "Count 기대 50, 결과 " + Num((long long)s.Count());
    return "";
}

std::string RandomVsReference() {
    unsigned seed = 77031u;
    auto next = [&](unsigned mod) {
        seed = seed * 1664525u + 1013904223u;
        return (seed >> 8) % mod;
    };
    UnitStore s;
    Model m;
    for (int step = 0; step < 20000; ++step) {
        const unsigned op = next(10);
        if (op < 5 || m.units.empty()) {
            const UnitHot h = H(static_cast<float>(next(1000)), static_cast<float>(next(1000)), 1.f, 2.f);
            const UnitCold c = C("Unit" + Num(step), static_cast<int>(next(50)));
            const UnitId want = m.Spawn(h, c);
            const UnitId got = s.Spawn(h, c);
            if (got != want) return "step " + Num(step) + ": Spawn id 기대 " + Num(want) + ", 결과 " + Num(got);
        } else if (op < 9) {
            const UnitId id = m.units[next(static_cast<unsigned>(m.units.size()))].id;
            if (!s.Despawn(id)) return "step " + Num(step) + ": 살아 있는 id " + Num(id) + "의 Despawn이 false";
            m.Despawn(id);
        } else {
            const UnitId id = static_cast<UnitId>(next(m.nextId + 5));
            const bool want = m.Find(id) != nullptr;
            if (s.Despawn(id) != want) return "step " + Num(step) + ": id " + Num(id) + "의 Despawn 반환 기대 " + (want ? "true" : "false");
            if (want) m.Despawn(id);
        }
        if (step % 997 == 0 || step > 19900) {
            std::string d = Compare(s, m, "step " + Num(step) + ":");
            if (!d.empty()) return d;
        }
    }
    for (UnitId id = 0; id < m.nextId + 3; ++id) {
        const Ref* r = m.Find(id);
        const UnitHot* h = s.Hot(id);
        if ((r == nullptr) != (h == nullptr)) return "끝 상태: id " + Num(id) + "의 Hot " + (r ? "nullptr이면 안 됨" : "nullptr이어야 함");
        if (r && !SameHot(*h, r->hot)) return "끝 상태: id " + Num(id) + "의 Hot 데이터가 다름";
    }
    return Compare(s, m, "끝 상태:");
}

typedef std::string (*CaseFn)();
struct Case {
    const char* name;
    CaseFn fn;
};
const Case kCases[] = {
    {"spawn-ids-and-lookup", SpawnAndLookup},
    {"despawn-middle-moves-last", DespawnMiddle},
    {"despawn-last-and-only", DespawnLastAndOnly},
    {"invalid-and-dead-ids", InvalidIds},
    {"integrate-hot-only", IntegrateMovesLive},
    {"ids-never-reused", IdsNeverReused},
    {"random-vs-reference", RandomVsReference},
};

}  // namespace judge

int main() {
    using namespace judge;
    for (const Case& c : kCases) {
        std::string reason;
        try {
            reason = c.fn();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        if (reason.empty()) {
            std::printf("[PASS] %s\n", c.name);
        } else {
            std::printf("[FAIL] %s :: %s\n", c.name, reason.c_str());
        }
    }
    return 0;
}

