게임 클라이언트 프로그래머 면접입니다. 면접관이 지원자의 포트폴리오에서 세 조각을 보여 줍니다.

```cpp
// (1) 데미지 계산 — 초당 수천 번 호출된다
float ComputeDamage(const float& base, const float& multiplier);

// (2) 머리 위 이름표
class Nameplate {
public:
    void SetText(std::string&& text) { text_ = text; }
private:
    std::string text_;
};

// (3) 오브젝트 풀에 적을 생성한다
template <class T, class... Args>
T& Spawn(std::vector<T>& pool, Args&&... args) {
    return pool.emplace_back(std::move(args)...);
}

std::string bossName = "Lich King";
Spawn(enemies, bossName, 900);
ShowBossIntro(bossName);   // 보스 등장 연출에 이름을 띄운다
```

QA는 보스 등장 연출에 이름이 비어 나온다고 보고했습니다.

**질문: "lvalue와 rvalue는 무엇이고, `std::move`와 `std::forward`는 각각 무엇을 하나요? `Args&&`가 어떻게 lvalue와 rvalue를 모두 받는지 템플릿 인자 추론과 참조 축약으로 설명한 뒤, 세 조각의 문제를 짚고, 매개변수를 값·`const&`·`&&`·전달 참조 중 무엇으로 받을지 정하는 기준을 말해 주세요."**

problems.solutionCode:
#include <cstdio>
#include <string>
#include <utility>
#include <vector>

// (1) Cheap "in" parameter: pass by value (Core Guidelines F.16).
float ComputeDamage(float base, float multiplier) { return base * multiplier; }

// (2) A value the object keeps: const& for lvalues plus && for rvalues
// (F.16 "advanced uses", F.18). Inside the && overload `text` has a name, so it is an
// lvalue expression; std::move is what lets the assignment move from it.
class Nameplate {
public:
    void SetText(const std::string& text) { text_ = text; }
    void SetText(std::string&& text) { text_ = std::move(text); }
    const std::string& Text() const { return text_; }

private:
    std::string text_;
};

// (3) "Forward" parameters: TP&& and std::forward exactly once on each path (F.19).
// For an lvalue argument Args is deduced as X& and forward returns an lvalue (copy);
// for an rvalue argument Args is X and forward returns an xvalue (move).
template <class T, class... Args>
T& Spawn(std::vector<T>& pool, Args&&... args) {
    return pool.emplace_back(std::forward<Args>(args)...);
}

struct Enemy {
    std::string name;
    int hp;
    Enemy(std::string n, int h) : name(std::move(n)), hp(h) {}
};

// Counts how a stored value gets into an object under each parameter style.
struct Counted {
    static int copies, moves;
    Counted() = default;
    Counted(const Counted&) { ++copies; }
    Counted(Counted&&) noexcept { ++moves; }
    Counted& operator=(const Counted&) {
        ++copies;
        return *this;
    }
    Counted& operator=(Counted&&) noexcept {
        ++moves;
        return *this;
    }
};
int Counted::copies = 0;
int Counted::moves = 0;

struct Holder {
    Counted kept;
    void ByValue(Counted c) { kept = std::move(c); }
    void ByConstRef(const Counted& c) { kept = c; }
    void Overloaded(const Counted& c) { kept = c; }
    void Overloaded(Counted&& c) { kept = std::move(c); }
    template <class C>
    void Forwarding(C&& c) { kept = std::forward<C>(c); }
};

template <class F>
void Measure(const char* what, F call) {
    Counted::copies = Counted::moves = 0;
    call();
    std::printf("%-32s copies %d, moves %d\n", what, Counted::copies, Counted::moves);
}

int main() {
    std::printf("damage %.1f\n", ComputeDamage(40.0f, 1.5f));

    Nameplate plate;
    std::string title = "Dragon Slayer";
    plate.SetText(title);                   // lvalue: copied, title keeps its text
    plate.SetText(std::string("Boss"));     // rvalue: moved
    std::printf("plate \"%s\", title \"%s\"\n", plate.Text().c_str(), title.c_str());

    std::vector<Enemy> enemies;
    std::string bossName = "Lich King";
    Spawn(enemies, bossName, 900);           // copies bossName
    Spawn(enemies, std::string("Ghoul"), 40);  // moves the temporary
    std::printf("spawned \"%s\" and \"%s\", bossName still \"%s\"\n", enemies[0].name.c_str(),
                enemies[1].name.c_str(), bossName.c_str());

    Holder h;
    Counted lv;
    Measure("by value, lvalue", [&] { h.ByValue(lv); });
    Measure("by value, rvalue", [&] { h.ByValue(Counted()); });
    Measure("const&, lvalue", [&] { h.ByConstRef(lv); });
    Measure("const&, rvalue", [&] { h.ByConstRef(Counted()); });
    Measure("const& + && overloads, lvalue", [&] { h.Overloaded(lv); });
    Measure("const& + && overloads, rvalue", [&] { h.Overloaded(Counted()); });
    Measure("T&& + std::forward, lvalue", [&] { h.Forwarding(lv); });
    Measure("T&& + std::forward, rvalue", [&] { h.Forwarding(Counted()); });
    return 0;
}

