// Objects live in slots. A removed object's slot is reused by a later Insert, and every
// handle that pointed at the removed object must stop working at that moment.
template <class T>
class SlotMap {
public:
    // Stores value and returns a handle to it. Reuses a free slot before adding a new one.
    Handle Insert(T value) {
        (void)value;
        return Handle{};
    }

    // Destroys the object now and frees its slot. Returns false, and changes nothing,
    // if h does not refer to a live object.
    bool Remove(Handle h) {
        (void)h;
        return false;
    }

    // nullptr if h does not refer to a live object. The pointer stays valid only until
    // the next Insert or Remove.
    T* Get(Handle h) {
        (void)h;
        return nullptr;
    }
    const T* Get(Handle h) const {
        (void)h;
        return nullptr;
    }

    std::size_t Size() const noexcept { return size_; }            // live objects
    std::size_t SlotCount() const noexcept { return slots_.size(); }  // slots ever created

private:
    struct Slot {
        std::optional<T> value;  // empty while the slot is free
        std::uint32_t generation = 0;
    };
    std::vector<Slot> slots_;
    std::vector<std::uint32_t> freeSlots_;  // indices of empty slots
    std::size_t size_ = 0;
};

problems.solutionCode:
#include <cstddef>
#include <cstdint>
#include <optional>
#include <utility>
#include <vector>

// What gameplay code keeps instead of Enemy*: turret targets, threat lists, UI markers.
struct Handle {
    std::uint32_t index = 0;
    std::uint32_t generation = 0;
};

// Objects live in slots. A removed object's slot is reused by a later Insert, and every
// handle that pointed at the removed object must stop working at that moment.
//
// Each slot counts how many times it has been freed (its generation). A handle copies
// the generation at Insert time, so it matches only while that same object is alive.
template <class T>
class SlotMap {
public:
    // Stores value and returns a handle to it. Reuses a free slot before adding a new one.
    Handle Insert(T value) {
        if (freeSlots_.empty()) {
            slots_.emplace_back();  // a new, empty slot
            freeSlots_.push_back(static_cast<std::uint32_t>(slots_.size() - 1));
        }
        const std::uint32_t index = freeSlots_.back();
        Slot& slot = slots_[index];
        slot.value.emplace(std::move(value));  // if this throws, the slot simply stays free
        freeSlots_.pop_back();
        ++size_;
        return Handle{index, slot.generation};
    }

    // Destroys the object now and frees its slot. Returns false, and changes nothing,
    // if h does not refer to a live object.
    bool Remove(Handle h) {
        Slot* slot = Find(h);
        if (slot == nullptr) return false;
        slot->value.reset();  // runs ~T() now, not when the slot is reused
        ++slot->generation;   // every handle to the old object is stale from here on
        freeSlots_.push_back(h.index);
        --size_;
        return true;
    }

    // nullptr if h does not refer to a live object. The pointer stays valid only until
    // the next Insert or Remove.
    T* Get(Handle h) {
        Slot* slot = Find(h);
        return slot ? &*slot->value : nullptr;
    }
    const T* Get(Handle h) const {
        const Slot* slot = Find(h);
        return slot ? &*slot->value : nullptr;
    }

    std::size_t Size() const noexcept { return size_; }            // live objects
    std::size_t SlotCount() const noexcept { return slots_.size(); }  // slots ever created

private:
    struct Slot {
        std::optional<T> value;  // empty while the slot is free
        // Starts at 1 so that a default Handle{} (generation 0) never matches a slot.
        // Wrap-around after 2^32 - 1 reuses of one slot is not handled here.
        std::uint32_t generation = 1;
    };

    // Range check, then generation check. A free slot never matches: Remove bumped its
    // generation past every handle that was given out for it.
    const Slot* Find(Handle h) const {
        if (h.index >= slots_.size()) return nullptr;
        const Slot& slot = slots_[h.index];
        if (slot.generation != h.generation || !slot.value.has_value()) return nullptr;
        return &slot;
    }
    Slot* Find(Handle h) { return const_cast<Slot*>(static_cast<const SlotMap&>(*this).Find(h)); }

    std::vector<Slot> slots_;
    std::vector<std::uint32_t> freeSlots_;  // indices of empty slots
    std::size_t size_ = 0;
};

