#include <cstdio>
#include <exception>
#include <string>
#include <utility>
#include <vector>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

long g_live = 0;  // Enemy objects constructed minus destroyed

struct Enemy {
    int id = 0;
    int hp = 0;
    Enemy(int i, int h) : id(i), hp(h) { ++g_live; }
    Enemy(const Enemy& o) : id(o.id), hp(o.hp) { ++g_live; }
    Enemy(Enemy&& o) noexcept : id(o.id), hp(o.hp) { ++g_live; }
    Enemy& operator=(const Enemy&) = default;
    Enemy& operator=(Enemy&&) noexcept = default;
    ~Enemy() { --g_live; }
};

using Map = SlotMap<Enemy>;

std::string Num(long long v) { return std::to_string(v); }
std::string H(Handle h) { return "{" + Num(h.index) + ", " + Num(h.generation) + "}"; }

// Get must return the object inserted for this handle, through both overloads.
std::string Expect(Map& m, Handle h, int id, int hp, const std::string& who) {
    Enemy* e = m.Get(h);
    const Enemy* ce = static_cast<const Map&>(m).Get(h);
    if (e == nullptr) return who + " 살아 있는 핸들 " + H(h) + "의 Get이 nullptr";
    if (ce != e) return who + " const Get과 비 const Get의 결과가 다름";
    if (e->id != id || e->hp != hp) return who + " 핸들 " + H(h) + "이(가) 다른 적(id " + Num(e->id) + ")을 가리킴, 기대 id " + Num(id);
    return "";
}

std::string ExpectStale(Map& m, Handle h, const std::string& who) {
    const Enemy* e = m.Get(h);
    const Enemy* ce = static_cast<const Map&>(m).Get(h);
    if (e != nullptr || ce != nullptr)
        return who + " 무효인 핸들 " + H(h) + "의 Get이 nullptr가 아님 (id " + Num((e ? e : ce)->id) + "인 적을 가리킴)";
    return "";
}

std::string InsertAndGet() {
    Map m;
    const Handle a = m.Insert(Enemy(1, 100));
    const Handle b = m.Insert(Enemy(2, 80));
    const Handle c = m.Insert(Enemy(3, 60));
    if (m.Size() != 3) return "Insert 3번 뒤 Size 기대 3, 결과 " + Num((long long)m.Size());
    std::string d = Expect(m, a, 1, 100, "a:");
    if (d.empty()) d = Expect(m, b, 2, 80, "b:");
    if (d.empty()) d = Expect(m, c, 3, 60, "c:");
    if (!d.empty()) return d;
    m.Get(b)->hp = 5;
    return Expect(m, b, 2, 5, "Get(b)->hp = 5 뒤:");
}

std::string DefaultHandleNeverValid() {
    Map m;
    std::string d = ExpectStale(m, Handle{}, "빈 SlotMap에서 Handle{}:");
    if (!d.empty()) return d;
    const Handle a = m.Insert(Enemy(1, 100));
    m.Insert(Enemy(2, 80));
    d = ExpectStale(m, Handle{}, "적 2명이 있을 때 Handle{}:");
    if (!d.empty()) return d;
    if (m.Remove(Handle{})) return "Remove(Handle{})가 true (기본 핸들은 어떤 적도 가리키지 않음)";
    if (m.Size() != 2) return "Remove(Handle{}) 뒤 Size 기대 2, 결과 " + Num((long long)m.Size());
    m.Remove(a);
    m.Insert(Enemy(3, 60));
    return ExpectStale(m, Handle{}, "슬롯을 재사용한 뒤 Handle{}:");
}

std::string RemovedHandleGoesStale() {
    Map m;
    const Handle a = m.Insert(Enemy(1, 100));
    const Handle b = m.Insert(Enemy(2, 80));
    if (!m.Remove(a)) return "살아 있는 핸들의 Remove가 false";
    std::string d = ExpectStale(m, a, "Remove한 a:");
    if (!d.empty()) return d;
    if (m.Remove(a)) return "이미 Remove한 핸들을 다시 Remove하자 true";
    if (m.Size() != 1) return "Remove 뒤 Size 기대 1, 결과 " + Num((long long)m.Size());
    return Expect(m, b, 2, 80, "남은 b:");
}

std::string ReusedSlotRejectsOldHandle() {
    Map m;
    const Handle oldOrc = m.Insert(Enemy(1, 100));
    m.Remove(oldOrc);
    const Handle newImp = m.Insert(Enemy(2, 30));
    if (m.SlotCount() != 1) return "빈 슬롯이 있는데 새 슬롯을 만듦: SlotCount 기대 1, 결과 " + Num((long long)m.SlotCount());
    std::string d = ExpectStale(m, oldOrc, "같은 슬롯에 새 적이 들어온 뒤 옛 핸들:");
    if (!d.empty()) return d;
    d = Expect(m, newImp, 2, 30, "새 핸들:");
    if (!d.empty()) return d;
    if (m.Remove(oldOrc)) return "옛 핸들로 Remove하자 true: 같은 슬롯의 새 적이 지워짐";
    if (m.Size() != 1) return "옛 핸들로 Remove한 뒤 Size 기대 1, 결과 " + Num((long long)m.Size());
    return Expect(m, newImp, 2, 30, "옛 핸들로 Remove를 시도한 뒤 새 핸들:");
}

std::string RemoveDestroysNow() {
    const long before = g_live;
    {
        Map m;
        const Handle a = m.Insert(Enemy(1, 100));
        m.Insert(Enemy(2, 80));
        if (g_live - before != 2) return "Insert 2번 뒤 살아 있는 Enemy 기대 2, 결과 " + Num(g_live - before);
        m.Remove(a);
        if (g_live - before != 1) return "Remove 직후 살아 있는 Enemy 기대 1, 결과 " + Num(g_live - before) + " (Remove가 객체를 바로 파괴해야 함)";
    }
    if (g_live != before) return "SlotMap이 파괴된 뒤 살아 있는 Enemy가 " + Num(g_live - before) + "개 (누수 또는 이중 파괴)";
    return "";
}

std::string BadHandles() {
    Map m;
    const Handle a = m.Insert(Enemy(1, 100));
    std::string d = ExpectStale(m, Handle{50, a.generation}, "범위 밖 index:");
    if (!d.empty()) return d;
    d = ExpectStale(m, Handle{a.index, a.generation + 7}, "세대가 다른 핸들:");
    if (!d.empty()) return d;
    if (m.Remove(Handle{50, a.generation}) || m.Remove(Handle{a.index, a.generation + 7})) return "잘못된 핸들의 Remove가 true";
    return Expect(m, a, 1, 100, "a:");
}

std::string FreeSlotsReused() {
    Map m;
    std::vector<Handle> hs;
    for (int i = 0; i < 10; ++i) hs.push_back(m.Insert(Enemy(i, i)));
    for (int i = 0; i < 10; i += 2) m.Remove(hs[i]);
    m.Remove(hs[9]);
    for (int i = 0; i < 6; ++i) m.Insert(Enemy(100 + i, 1));
    if (m.SlotCount() != 10) return "빈 슬롯 6개를 다시 채운 뒤 SlotCount 기대 10, 결과 " + Num((long long)m.SlotCount());
    if (m.Size() != 10) return "Size 기대 10, 결과 " + Num((long long)m.Size());
    for (int i = 1; i < 9; i += 2) {
        std::string d = Expect(m, hs[i], i, i, "지우지 않은 핸들:");
        if (!d.empty()) return d;
    }
    return "";
}

std::string RandomVsReference() {
    unsigned seed = 4242u;
    auto next = [&](unsigned mod) {
        seed = seed * 1664525u + 1013904223u;
        return (seed >> 8) % mod;
    };
    struct Issued {
        Handle h;
        int id;
        bool alive;
    };
    Map m;
    std::vector<Issued> issued;
    std::size_t live = 0, peak = 0;
    for (int step = 0; step < 4000; ++step) {
        const unsigned op = next(10);
        if (op < 5 || live == 0) {
            const Handle h = m.Insert(Enemy(step, static_cast<int>(next(500))));
            issued.push_back({h, step, true});
            ++live;
            if (live > peak) peak = live;
        } else if (op < 9) {
            Issued& victim = issued[next(static_cast<unsigned>(issued.size()))];
            if (m.Remove(victim.h) != victim.alive)
                return "step " + Num(step) + ": " + (victim.alive ? "살아 있는" : "이미 지운") + " 핸들 " + H(victim.h) + "의 Remove 반환값이 틀림";
            if (victim.alive) --live;
            victim.alive = false;
        } else {
            const Issued& probe = issued[next(static_cast<unsigned>(issued.size()))];
            const Enemy* e = m.Get(probe.h);
            if (probe.alive && (e == nullptr || e->id != probe.id))
                return "step " + Num(step) + ": 살아 있는 핸들 " + H(probe.h) + "의 Get이 다른 결과를 냄";
            if (!probe.alive && e != nullptr)
                return "step " + Num(step) + ": 지운 적의 핸들 " + H(probe.h) + "이(가) id " + Num(e->id) + "인 적을 가리킴 (세대 검사 누락)";
        }
    }
    if (m.Size() != live) return "끝 상태 Size 기대 " + Num((long long)live) + ", 결과 " + Num((long long)m.Size());
    if (m.SlotCount() > peak) return "SlotCount " + Num((long long)m.SlotCount()) + "가 동시에 살아 있던 최대 수 " + Num((long long)peak) + "보다 큼 (빈 슬롯을 재사용하지 않음)";
    for (const Issued& is : issued) {
        const Enemy* e = m.Get(is.h);
        if (is.alive && (e == nullptr || e->id != is.id)) return "끝 상태: 살아 있는 핸들 " + H(is.h) + "의 Get이 틀림";
        if (!is.alive && e != nullptr) return "끝 상태: 지운 적의 핸들 " + H(is.h) + "이(가) id " + Num(e->id) + "인 적을 가리킴";
    }
    return "";
}

typedef std::string (*CaseFn)();
struct Case {
    const char* name;
    CaseFn fn;
};
const Case kCases[] = {
    {"insert-and-get", InsertAndGet},
    {"default-handle-never-valid", DefaultHandleNeverValid},
    {"removed-handle-goes-stale", RemovedHandleGoesStale},
    {"reused-slot-rejects-old-handle", ReusedSlotRejectsOldHandle},
    {"remove-destroys-object-now", RemoveDestroysNow},
    {"out-of-range-and-wrong-generation", BadHandles},
    {"free-slots-reused-before-growing", FreeSlotsReused},
    {"random-vs-reference", RandomVsReference},
};

}  // namespace judge

int main() {
    using namespace judge;
    for (const Case& c : kCases) {
        std::string reason;
        try {
            reason = c.fn();
        } catch (const std::exception& e) {
            reason = std::string("예외가 밖으로 전파됨: ") + e.what();
        } catch (...) {
            reason = "알 수 없는 예외가 밖으로 전파됨";
        }
        if (reason.empty()) {
            std::printf("[PASS] %s\n", c.name);
        } else {
            std::printf("[FAIL] %s :: %s\n", c.name, reason.c_str());
        }
    }
    return 0;
}

