// Runs callbacks a number of ticks after they were scheduled (one Tick per frame).
class TimerQueue {
public:
    void After(int ticks, std::function<void()> callback) {
        pending_.push_back(Pending{now_ + ticks, std::move(callback)});
    }

    // Advances one tick and runs every callback that is due, in scheduling order.
    void Tick() {
        ++now_;
        std::vector<Pending> due, later;
        for (Pending& p : pending_) (p.at <= now_ ? due : later).push_back(std::move(p));
        pending_ = std::move(later);
        for (Pending& p : due) p.callback();
    }

private:
    struct Pending {
        int at;
        std::function<void()> callback;
    };
    int now_ = 0;
    std::vector<Pending> pending_;
};

// The HUD's popup text log. It lives as long as the HUD, longer than any timer.
struct PopupLog {
    std::vector<std::string> lines;
    void Show(const std::string& text) { lines.push_back(text); }
};

// The combat system fills one reusable HitInfo per hit and overwrites it on the next hit.
struct HitInfo {
    std::string targetName;
    int damage = 0;
};

// Exercise 1: the damage number pops up delayTicks after the hit and must show the hit
// as it was when it happened, e.g. "Orc -12".
void ScheduleDamagePopup(TimerQueue& timers, PopupLog& popups, const HitInfo& hit, int delayTicks) {
    // The hit data is copied into the closure now (init-capture builds the text once).
    // popups stays a reference on purpose: the HUD log outlives every timer, and the
    // popup must land in that log, not in a private copy.
    timers.After(delayTicks, [&popups, text = hit.targetName + " -" + std::to_string(hit.damage)]() {
        popups.Show(text);
    });
}

// Exercise 2: every hit shows "Combo xN!" 30 ticks later, where N is the combo count at
// the moment of that hit.
class ComboCounter {
public:
    void OnHit(TimerQueue& timers, PopupLog& popups) {
        ++combo_;
        // [=] would not copy combo_: it captures `this`, and combo_ is read through it
        // when the timer fires. Copy the value into the closure explicitly.
        timers.After(30, [&popups, count = combo_]() {
            popups.Show("Combo x" + std::to_string(count) + "!");
        });
    }
    void Break() { combo_ = 0; }  // the player took damage: the combo ends
    int Combo() const { return combo_; }

private:
    int combo_ = 0;
};

