// Every object the callbacks could refer to (the HitInfo buffer, the PopupLog, the
// ComboCounter) stays alive until the timers have fired, so the program has defined
// behaviour whichever way the lambdas capture. A by-reference capture is detected by
// overwriting or changing the caller's object before the timer fires: it then shows
// the new value instead of the value at the time of the hit.
namespace judge {

std::string Num(long long v) { return std::to_string(v); }

std::string Lines(const std::vector<std::string>& v) {
    std::string s = "[";
    for (std::size_t i = 0; i < v.size(); ++i) s += (i ? ", \"" : "\"") + v[i] + "\"";
    return s + "]";
}

std::string Expect(const PopupLog& log, const std::vector<std::string>& want, const std::string& who) {
    if (log.lines != want) return who + " 팝업 기대 " + Lines(want) + ", 결과 " + Lines(log.lines);
    return "";
}

void Fill(HitInfo& buffer, const char* name, int damage) {
    buffer.targetName = name;
    buffer.damage = damage;
}

std::string PopupKeepsHit() {
    TimerQueue timers;
    PopupLog log;
    HitInfo buffer;
    Fill(buffer, "Orc", 12);
    ScheduleDamagePopup(timers, log, buffer, 2);
    Fill(buffer, "Goblin Shaman of the Deep Caves", 99);  // the next hit reuses the buffer
    timers.Tick();
    std::string d = Expect(log, {}, "1틱 뒤(지연 2틱):");
    if (!d.empty()) return d;
    timers.Tick();
    return Expect(log, {"Orc -12"}, "2틱 뒤, 버퍼를 다음 타격으로 덮어쓴 상태에서:");
}

