    const int delays[] = {2, 1, 2, 3};
    for (int i = 0; i < 4; ++i) {
        Fill(buffer, names[i], damages[i]);
        ScheduleDamagePopup(timers, log, buffer, delays[i]);
    }
    Fill(buffer, "<overwritten>", -1);
    for (int t = 0; t < 3; ++t) timers.Tick();
    return Expect(log, {"Bat -8", "Slime -3", "Wolf -15", "Troll -40"}, "버퍼 하나로 4번 타격한 뒤 3틱:");
}

std::string PopupsReachSharedLog() {
    TimerQueue timers;
    PopupLog hud, killFeed;
    HitInfo buffer;
    Fill(buffer, "Archer", 21);
    ScheduleDamagePopup(timers, hud, buffer, 1);
    Fill(buffer, "Knight", 5);
    ScheduleDamagePopup(timers, killFeed, buffer, 1);
    ScheduleDamagePopup(timers, hud, buffer, 1);
    timers.Tick();
    std::string d = Expect(hud, {"Archer -21", "Knight -5"}, "HUD 로그:");
    if (!d.empty()) return d + (hud.lines.empty() ? " (넘겨받은 PopupLog가 아니라 람다 안의 복사본에 썼을 가능성)" : "");
    return Expect(killFeed, {"Knight -5"}, "킬 피드 로그:");
}

