#include <algorithm>
#include <cstddef>
#include <stdexcept>
#include <string>
#include <vector>

struct ItemStack {
    int itemId = 0;  // 0 means the slot is empty
    int count = 0;
};

// A survival game's backpack with a fixed number of slots. Not copyable.
class Inventory {
public:
    explicit Inventory(int slotCount) : slots_(new ItemStack[slotCount]), slotCount_(slotCount) {}

    ~Inventory() { delete slots_; }

    Inventory(const Inventory&) = delete;
    Inventory& operator=(const Inventory&) = delete;

    int SlotCount() const { return slotCount_; }
    ItemStack Slot(int index) const { return slots_[index]; }

    // Stacks onto the slot that already holds itemId, otherwise uses the first
    // empty slot. Returns false (and changes nothing) when neither exists.
    bool Add(int itemId, int count) {
        for (int i = 0; i < slotCount_; ++i) {
            if (slots_[i].itemId == itemId) {
                slots_[i].count += count;
                return true;
            }
        }
        for (int i = 0; i < slotCount_; ++i) {
            if (slots_[i].itemId == 0) {
                slots_[i] = ItemStack{itemId, count};
                return true;
            }
        }
        return false;
    }

    // Consumes `need` items of ingredientId and adds one resultId. Returns false
    // and leaves the inventory unchanged when there are not enough ingredients
    // or no slot for the result.
    bool Craft(int ingredientId, int need, int resultId) {
        ItemStack* backup = new ItemStack[slotCount_];
        std::copy(slots_, slots_ + slotCount_, backup);

        int remaining = need;
        for (int i = 0; i < slotCount_ && remaining > 0; ++i) {
            if (slots_[i].itemId != ingredientId) continue;
            const int take = std::min(remaining, slots_[i].count);
            slots_[i].count -= take;
            remaining -= take;
            if (slots_[i].count == 0) slots_[i] = ItemStack{};
        }
        if (remaining > 0) {
            std::copy(backup, backup + slotCount_, slots_);
            delete[] backup;
            return false;
        }
        if (!Add(resultId, 1)) {
            std::copy(backup, backup + slotCount_, slots_);
            return false;
        }
        delete[] backup;
        return true;
    }

    // Loads the slots from save lines "<itemId> <count>", one line per slot
    // (missing lines mean empty slots). std::stoi throws on a corrupted line;
    // the exception reaches the caller and the inventory keeps its old contents.
    void Load(const std::vector<std::string>& lines) {
        ItemStack* loaded = new ItemStack[slotCount_];
        for (int i = 0; i < slotCount_ && i < static_cast<int>(lines.size()); ++i) {
            std::size_t used = 0;
            loaded[i].itemId = std::stoi(lines[i], &used);
            loaded[i].count = std::stoi(lines[i].substr(used));
        }
        delete[] slots_;
        slots_ = loaded;
    }

private:
    ItemStack* slots_;
    int slotCount_;
};

