#include <algorithm>
#include <cstddef>
#include <stdexcept>
#include <string>
#include <vector>

struct ItemStack {
    int itemId = 0;  // 0 means the slot is empty
    int count = 0;
};

// A survival game's backpack with a fixed number of slots. Not copyable.
// Every buffer is owned by a std::vector, so each path out of a function
// (return, early return, exception) releases it, with the matching form.
class Inventory {
public:
    explicit Inventory(int slotCount) : slots_(static_cast<std::size_t>(slotCount)) {}

    // No user-written destructor: ~vector releases the slots.

    Inventory(const Inventory&) = delete;
    Inventory& operator=(const Inventory&) = delete;

    int SlotCount() const { return static_cast<int>(slots_.size()); }
    ItemStack Slot(int index) const { return slots_[static_cast<std::size_t>(index)]; }

    // Stacks onto the slot that already holds itemId, otherwise uses the first
    // empty slot. Returns false (and changes nothing) when neither exists.
    bool Add(int itemId, int count) {
        for (ItemStack& s : slots_) {
            if (s.itemId == itemId) {
                s.count += count;
                return true;
            }
        }
        for (ItemStack& s : slots_) {
            if (s.itemId == 0) {
                s = ItemStack{itemId, count};
                return true;
            }
        }
        return false;
    }

    // Consumes `need` items of ingredientId and adds one resultId. Returns false
    // and leaves the inventory unchanged when there are not enough ingredients
    // or no slot for the result.
    bool Craft(int ingredientId, int need, int resultId) {
        std::vector<ItemStack> backup = slots_;  // freed on every return path

        int remaining = need;
        for (ItemStack& s : slots_) {
            if (remaining == 0) break;
            if (s.itemId != ingredientId) continue;
            const int take = std::min(remaining, s.count);
            s.count -= take;
            remaining -= take;
            if (s.count == 0) s = ItemStack{};
        }
        if (remaining > 0 || !Add(resultId, 1)) {
            slots_.swap(backup);  // roll back; the consumed copy dies with `backup`
            return false;
        }
        return true;
    }

    // Loads the slots from save lines "<itemId> <count>", one line per slot
    // (missing lines mean empty slots). std::stoi throws on a corrupted line;
    // the exception reaches the caller and the inventory keeps its old contents.
    void Load(const std::vector<std::string>& lines) {
        std::vector<ItemStack> loaded(slots_.size());  // freed if stoi throws
        for (std::size_t i = 0; i < loaded.size() && i < lines.size(); ++i) {
            std::size_t used = 0;
            loaded[i].itemId = std::stoi(lines[i], &used);
            loaded[i].count = std::stoi(lines[i].substr(used));
        }
        slots_.swap(loaded);  // commit only after every line parsed
    }

private:
    std::vector<ItemStack> slots_;
};

