#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

// Instrumented heap. Every block records in a 16-byte header whether it came from
// the single-object form (operator new) or the array form (operator new[]), and the
// deallocation function that releases it is checked against that record. Live
// blocks are counted, so a leak is a number, not a guess.
namespace judge_heap {
const std::size_t kHeader = 16;
const unsigned kSingle = 0x5106u;
const unsigned kArray = 0xA77Au;
long g_live = 0;      // blocks handed out and not yet released
long g_mismatch = 0;  // blocks released by the deallocation function of the other form
void* Allocate(std::size_t n, unsigned form) {
    unsigned char* raw = static_cast<unsigned char*>(std::malloc(n + kHeader));
    if (raw == nullptr) throw std::bad_alloc();
    std::memcpy(raw, &form, sizeof(form));
    ++g_live;
    return raw + kHeader;
}
void Release(void* p, unsigned form) noexcept {
    if (p == nullptr) return;
    unsigned char* raw = static_cast<unsigned char*>(p) - kHeader;
    unsigned recorded = 0;
    std::memcpy(&recorded, raw, sizeof(recorded));
    if (recorded != form) ++g_mismatch;
    --g_live;
    std::free(raw);
}
}  // namespace judge_heap
void* operator new(std::size_t n) { return judge_heap::Allocate(n, judge_heap::kSingle); }
void* operator new[](std::size_t n) { return judge_heap::Allocate(n, judge_heap::kArray); }
void operator delete(void* p) noexcept { judge_heap::Release(p, judge_heap::kSingle); }
void operator delete[](void* p) noexcept { judge_heap::Release(p, judge_heap::kArray); }
void operator delete(void* p, std::size_t) noexcept { judge_heap::Release(p, judge_heap::kSingle); }
void operator delete[](void* p, std::size_t) noexcept { judge_heap::Release(p, judge_heap::kArray); }

