std::string Num(long long v) { return std::to_string(v); }

// Failure text goes into a fixed buffer while the inventory is alive, so the
// judge's own messages never show up as live heap blocks.
char g_why[512];
bool Fail(const char* fmt, int a = 0, int b = 0, int c = 0, int d = 0) {
    std::snprintf(g_why, sizeof(g_why), fmt, a, b, c, d);
    return false;
}

// Compares every slot with the expected (itemId, count) pairs; slots past n must be empty.
bool Same(const Inventory& inv, const int (*want)[2], int n, const char* who) {
    for (int i = 0; i < inv.SlotCount(); ++i) {
        const int id = i < n ? want[i][0] : 0;
        const int count = i < n ? want[i][1] : 0;
        const ItemStack s = inv.Slot(i);
        if (s.itemId != id || s.count != count) {
            std::snprintf(g_why, sizeof(g_why), "%s 슬롯 %d 기대 (id %d, %d개), 결과 (id %d, %d개)", who, i, id, count,
                          s.itemId, s.count);
            return false;
        }
    }
    return true;
}

std::string Verdict(bool ok, long leaked, long mismatched, const char* what) {
    if (!ok) return g_why;
    if (leaked != 0) return std::string(what) + " 뒤 해제되지 않은 힙 블록 " + Num(leaked) + "개 (누수)";
    if (mismatched != 0)
        return std::string(what) + ": new[]로 받은 블록을 delete로(또는 new로 받은 블록을 delete[]로) 해제한 횟수 " + Num(mismatched);
    return "";
}

std::string AddStacksThenFillsEmpty() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        Inventory inv(3);
        if (inv.SlotCount() != 3) ok = Fail("SlotCount 기대 3, 결과 %d", inv.SlotCount());
        const int empty[1][2] = {{0, 0}};
        if (ok) ok = Same(inv, empty, 0, "새 가방:");
        if (ok && !inv.Add(7, 2)) ok = Fail("빈 슬롯이 있는데 Add(7, 2)가 false");
        if (ok && !inv.Add(9, 1)) ok = Fail("빈 슬롯이 있는데 Add(9, 1)가 false");
        if (ok && !inv.Add(7, 5)) ok = Fail("같은 아이템이 있는데 Add(7, 5)가 false");
        const int after[2][2] = {{7, 7}, {9, 1}};
        if (ok) ok = Same(inv, after, 2, "Add 3회 뒤:");
        if (ok && !inv.Add(4, 3)) ok = Fail("빈 슬롯이 하나 남았는데 Add(4, 3)가 false");
        if (ok && inv.Add(5, 1)) ok = Fail("가방이 가득 찼는데 Add(5, 1)가 true");
        const int full[3][2] = {{7, 7}, {9, 1}, {4, 3}};
        if (ok) ok = Same(inv, full, 3, "가득 찬 가방:");
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "가방 생성·파괴");
}

std::string CraftSuccess() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        Inventory inv(4);
        inv.Add(1, 3);  // wood x3
        inv.Add(2, 6);  // stone x6
        if (!inv.Craft(1, 3, 5)) ok = Fail("나무 3개로 판자를 만들 수 있는데 Craft(1, 3, 5)가 false");
        // The craft empties the wood slot, so the plank goes into that slot.
        const int want[2][2] = {{5, 1}, {2, 6}};
        if (ok) ok = Same(inv, want, 2, "제작 성공 뒤:");
        if (ok && !inv.Craft(2, 4, 5)) ok = Fail("돌 6개 중 4개로 제작할 수 있는데 Craft(2, 4, 5)가 false");
        const int want2[2][2] = {{5, 2}, {2, 2}};
        if (ok) ok = Same(inv, want2, 2, "두 번째 제작 뒤:");
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "제작 성공 2회");
}

std::string CraftNotEnough() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        Inventory inv(3);
        inv.Add(1, 2);
        inv.Add(3, 4);
        const int want[2][2] = {{1, 2}, {3, 4}};
        for (int k = 0; k < 3 && ok; ++k) {
            if (inv.Craft(1, 5, 6)) ok = Fail("나무가 2개뿐인데 Craft(1, 5, 6)가 true");
            if (ok) ok = Same(inv, want, 2, "재료 부족으로 실패한 뒤:");
        }
        if (ok && inv.Craft(8, 1, 6)) ok = Fail("없는 재료인데 Craft(8, 1, 6)가 true");
        if (ok) ok = Same(inv, want, 2, "없는 재료로 실패한 뒤:");
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "재료 부족으로 Craft 실패 4회");
}

std::string CraftNoFreeSlotNoLeak() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        // Full bag: wood x5, stone x3. Using 2 wood leaves 3, so no slot frees up for the plank.
        Inventory inv(2);
        inv.Add(1, 5);
        inv.Add(2, 3);
        const int want[2][2] = {{1, 5}, {2, 3}};
        for (int k = 0; k < 3 && ok; ++k) {
            if (inv.Craft(1, 2, 4)) ok = Fail("결과물을 둘 슬롯이 없는데 Craft(1, 2, 4)가 true");
            if (ok) ok = Same(inv, want, 2, "슬롯 부족으로 실패한 뒤:");
        }
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "결과물 슬롯이 없어 Craft가 false를 반환한 3회(조기 반환 경로)");
}

std::string LoadValidLines() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        Inventory inv(4);
        inv.Add(9, 9);
        const std::vector<std::string> save = {"3 10", "  7   2", "12 1"};
        inv.Load(save);
        const int want[3][2] = {{3, 10}, {7, 2}, {12, 1}};
        ok = Same(inv, want, 3, "세이브 3줄 로드 뒤:");
        if (ok) {
            // The 5th line is past the last slot and is never parsed.
            const std::vector<std::string> longer = {"1 1", "2 2", "3 3", "4 4", "x 5"};
            inv.Load(longer);
            const int want2[4][2] = {{1, 1}, {2, 2}, {3, 3}, {4, 4}};
            ok = Same(inv, want2, 4, "슬롯보다 많은 줄 로드 뒤:");
        }
        if (ok) {
            inv.Load(std::vector<std::string>());
            const int none[1][2] = {{0, 0}};
            ok = Same(inv, none, 0, "빈 세이브 로드 뒤:");
        }
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "정상 세이브 로드 3회");
}

std::string LoadCorruptLineNoLeak() {
    const long live0 = judge_heap::g_live;
    bool ok = true;
    {
        Inventory inv(4);
        inv.Add(5, 1);
        inv.Add(6, 2);
        const int want[2][2] = {{5, 1}, {6, 2}};
        const char* const bad[] = {"x 5", "12", "7 abc", "99999999999 1"};
        for (int k = 0; k < 4 && ok; ++k) {
            const std::vector<std::string> save = {"3 10", "7 2", bad[k]};
            bool threw = false;
            try {
                inv.Load(save);
            } catch (const std::invalid_argument&) {
                threw = true;
            } catch (const std::out_of_range&) {
                threw = true;
            }
            if (!threw) ok = Fail("손상된 줄(%d번째 형식)이 있는데 Load가 std::stoi의 예외를 전달하지 않음", k + 1);
            if (ok) ok = Same(inv, want, 2, "손상된 세이브 로드가 실패한 뒤:");
        }
    }
    return Verdict(ok, judge_heap::g_live - live0, 0, "손상된 세이브 로드가 예외로 끝난 4회(예외 경로)");
}

std::string DeleteFormMatchesNew() {
    const long live0 = judge_heap::g_live;
    const long mismatch0 = judge_heap::g_mismatch;
    bool ok = true;
    for (int n = 1; n <= 6 && ok; ++n) {
        Inventory inv(n);
        if (!inv.Add(n, n)) ok = Fail("빈 가방(슬롯 %d개)에 Add가 false", n);
    }
    return Verdict(ok, judge_heap::g_live - live0, judge_heap::g_mismatch - mismatch0, "가방 6개 생성·파괴");
}

// Reference model: plain arrays, same rules as the specification.
struct Ref {
    int n = 0;
    int id[8] = {};
    int count[8] = {};
    bool Add(int item, int c) {
        for (int i = 0; i < n; ++i) {
            if (id[i] == item) {
                count[i] += c;
                return true;
            }
        }
        for (int i = 0; i < n; ++i) {
            if (id[i] == 0) {
                id[i] = item;
                count[i] = c;
                return true;
            }
        }
        return false;
    }
    bool Craft(int item, int need, int result) {
        const Ref saved = *this;
        int remaining = need;
        for (int i = 0; i < n && remaining > 0; ++i) {
            if (id[i] != item) continue;
            const int take = remaining < count[i] ? remaining : count[i];
            count[i] -= take;
            remaining -= take;
            if (count[i] == 0) id[i] = 0;
        }
        if (remaining > 0 || !Add(result, 1)) {
            *this = saved;
            return false;
        }
        return true;
    }
};

unsigned g_seed = 20261122u;
int Next(unsigned mod) {
    g_seed = g_seed * 1664525u + 1013904223u;
    return static_cast<int>((g_seed >> 16) % mod);
}

std::string RandomVsReference() {
    const long live0 = judge_heap::g_live;
    const long mismatch0 = judge_heap::g_mismatch;
    bool ok = true;
    const char* const bad[] = {"x 5", "12", "", "7 abc", "99999999999 1"};
    for (int round = 0; round < 40 && ok; ++round) {
        Ref ref;
        ref.n = 1 + Next(8);
        Inventory inv(ref.n);
        for (int step = 0; step < 60 && ok; ++step) {
            const int op = Next(10);
            if (op < 4) {
                const int item = 1 + Next(5), c = 1 + Next(9);
                if (inv.Add(item, c) != ref.Add(item, c)) ok = Fail("round %d step %d: Add(%d, %d)의 반환값이 기준과 다름", round, step, item, c);
            } else if (op < 8) {
                const int item = 1 + Next(5), need = 1 + Next(12), result = 1 + Next(6);
                const bool want = ref.Craft(item, need, result);
                if (inv.Craft(item, need, result) != want)
                    ok = Fail("round %d step %d: Craft의 반환값이 기준과 다름 (기대 %d)", round, step, want ? 1 : 0);
            } else {
                std::vector<std::string> save;
                const int lines = Next(static_cast<unsigned>(ref.n + 2));
                const int corruptAt = Next(3) == 0 ? Next(static_cast<unsigned>(lines + 1)) : -1;
                Ref loaded;
                loaded.n = ref.n;
                for (int i = 0; i < lines; ++i) {
                    if (i == corruptAt) {
                        save.push_back(bad[Next(5)]);
                    } else {
                        const int item = 1 + Next(5), c = 1 + Next(50);
                        save.push_back(std::to_string(item) + " " + std::to_string(c));
                        if (i < ref.n) {
                            loaded.id[i] = item;
                            loaded.count[i] = c;
                        }
                    }
                }
                const bool wantThrow = corruptAt >= 0 && corruptAt < lines && corruptAt < ref.n;
                bool threw = false;
                try {
                    inv.Load(save);
                } catch (const std::exception&) {
                    threw = true;
                }
                if (threw != wantThrow) ok = Fail("round %d step %d: Load의 예외 여부가 기준과 다름 (기대 %d)", round, step, wantThrow ? 1 : 0);
                if (!wantThrow) ref = loaded;
            }
            for (int i = 0; i < ref.n && ok; ++i) {
                const ItemStack s = inv.Slot(i);
                if (s.itemId != ref.id[i] || s.count != ref.count[i])
                    ok = Fail("round %d step %d: 슬롯 %d가 기준(id %d)과 다름", round, step, i, ref.id[i]);
            }
        }
    }
    return Verdict(ok, judge_heap::g_live - live0, judge_heap::g_mismatch - mismatch0, "무작위 Add/Craft/Load 2400회와 가방 40개 파괴");
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    AddStacksThenFillsEmpty, CraftSuccess,          CraftNotEnough,       CraftNoFreeSlotNoLeak,
    LoadValidLines,          LoadCorruptLineNoLeak, DeleteFormMatchesNew, RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i] : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 2;  // a correct case finishes in milliseconds

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): std::terminate 호출 또는 힙 손상 감지";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (해제한 메모리 사용 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Every case runs in its own child process, so a crash costs only that case.
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);
}

