problems.solutionCode:
#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <type_traits>
#include <utility>

// Per-frame scratch memory for temporary allocations (culling lists, sort keys,
// formatted UI strings). Blocks are bump-allocated from one buffer and all released
// at once by Reset() at the end of the frame. The arena does not own the buffer and
// never allocates from the heap.
class FrameArena {
public:
    FrameArena(void* buffer, std::size_t capacity) noexcept
        : base_(static_cast<unsigned char*>(buffer)), capacity_(capacity) {}

    FrameArena(const FrameArena&) = delete;
    FrameArena& operator=(const FrameArena&) = delete;

    // Returns `size` bytes aligned to `alignment`, starting at the lowest suitably
    // aligned address at or after the current top. Returns nullptr and changes
    // nothing if size is 0, alignment is not a power of two, or the block does not
    // fit in the rest of the buffer.
    void* Allocate(std::size_t size, std::size_t alignment = alignof(std::max_align_t)) noexcept {
        // std::align has undefined behaviour for an alignment that is not a power of
        // two, so that is rejected first. (a & (a - 1)) clears the lowest set bit.
        if (size == 0 || alignment == 0 || (alignment & (alignment - 1)) != 0) return nullptr;
        void* p = base_ + top_;              // align the ADDRESS, not the offset
        std::size_t space = capacity_ - top_;
        // On success p moves to the first aligned address and space shrinks by the
        // padding; if padding + size does not fit, nothing changes. The check is
        // written without "top + padding + size", so a huge size cannot wrap around.
        if (std::align(alignment, size, p, space) == nullptr) return nullptr;
        top_ = capacity_ - space + size;    // new top = old top + padding + size
        return p;
    }

    // Allocate(sizeof(T), alignof(T)) and construct a T there from args. Returns
    // nullptr (constructing nothing) when it does not fit. Reset and Rewind never run
    // destructors, so T must be trivially destructible.
    template <typename T, typename... Args>
    T* Create(Args&&... args) {
        static_assert(std::is_trivially_destructible<T>::value,
                      "FrameArena never runs destructors: T must be trivially destructible");
        void* p = Allocate(sizeof(T), alignof(T));
        if (p == nullptr) return nullptr;
        return ::new (p) T(std::forward<Args>(args)...);
    }

    // The current top as a byte offset from the start of the buffer (always the same
    // value as Used()), to be passed to Rewind later.
    std::size_t Mark() const noexcept { return top_; }

    // Releases every block allocated after `mark` was taken. `mark` must come from
    // Mark() after the last Reset and must not be above the current top.
    void Rewind(std::size_t mark) noexcept {
        if (mark <= top_) top_ = mark;  // a mark above the top is a caller bug: ignored
    }

    // Releases every block. O(1): nothing is destroyed, the top just moves back.
    void Reset() noexcept { top_ = 0; }

    // Bytes from the start of the buffer to the top, padding included.
    std::size_t Used() const noexcept { return top_; }

    std::size_t Capacity() const noexcept { return capacity_; }

private:
    unsigned char* base_;
    std::size_t capacity_;
    std::size_t top_ = 0;  // offset of the first free byte
};

