// Counting heap: "the arena never touches the heap" is measured, not assumed.
namespace judge_heap {
long g_allocs = 0;
}
void* operator new(std::size_t n) {
    ++judge_heap::g_allocs;
    void* p = std::malloc(n ? n : 1);
    if (p == nullptr) throw std::bad_alloc();
    return p;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept { std::free(p); }
void operator delete[](void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }
void operator delete[](void* p, std::size_t) noexcept { std::free(p); }

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "aligned-at-every-base-offset",
    "contiguous-blocks-and-used",
    "full-returns-null-unchanged",
    "huge-size-and-bad-alignment",
    "reset-reuses-memory-no-heap",
    "mark-and-rewind",
    "create-constructs-in-arena",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료\n" : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }
std::string UNum(unsigned long long v) { return std::to_string(v); }

// One 64-byte-aligned backing store. Arenas are placed at chosen offsets inside it,
// so the base address of an arena is misaligned on purpose in many cases.
alignas(64) unsigned char g_store[8192];

// Reference model: computes the expected address of every block from integers only.
struct Model {
    std::uintptr_t base;
    std::size_t cap;
    std::size_t top;
    std::uintptr_t Alloc(std::size_t size, std::size_t align) {
        if (size == 0 || align == 0 || (align & (align - 1)) != 0) return 0;
        const std::uintptr_t cur = base + top;
        const std::uintptr_t aligned = (cur + (align - 1)) & ~static_cast<std::uintptr_t>(align - 1);
        const std::size_t pad = static_cast<std::size_t>(aligned - cur);
        if (pad > cap - top || size > cap - top - pad) return 0;
        top += pad + size;
        return aligned;
    }
};

std::string Where(const Model& m, std::uintptr_t a) {
    if (a == 0) return "nullptr";
    if (a < m.base || a > m.base + m.cap) return "버퍼 밖 주소";
    return "오프셋 " + UNum(a - m.base);
}

// Allocates through the learner's arena and the model; any difference is a failure.
std::string Step(FrameArena& arena, Model& m, std::size_t size, std::size_t align, const std::string& who) {
    const std::uintptr_t want = m.Alloc(size, align);
    const std::uintptr_t got = reinterpret_cast<std::uintptr_t>(arena.Allocate(size, align));
    const std::string call = who + "Allocate(" + UNum(size) + ", " + UNum(align) + ")";
    if (got != want) {
        std::string d = call + " 기대 " + Where(m, want) + ", 결과 " + Where(m, got);
        if (got != 0 && align != 0 && got % align != 0) d += " (주소가 " + UNum(align) + "의 배수가 아님)";
        return d;
    }
    if (arena.Used() != m.top) return call + " 뒤 Used 기대 " + UNum(m.top) + ", 결과 " + UNum(arena.Used());
    return "";
}

std::string AlignedAtEveryBaseOffset() {
    const std::size_t sizes[] = {3, 8, 1, 24, 5, 64, 2, 40};
    const std::size_t aligns[] = {1, 8, 2, 16, 4, 64, 32, 16};
    for (std::size_t offset = 0; offset < 64; ++offset) {
        unsigned char* base = g_store + offset;
        FrameArena arena(base, 1024);
        Model m{reinterpret_cast<std::uintptr_t>(base), 1024, 0};
        for (int i = 0; i < 8; ++i) {
            std::string d = Step(arena, m, sizes[i], aligns[i], "버퍼 시작이 64바이트 경계 + " + UNum(offset) + "일 때 ");
            if (!d.empty()) return d;
        }
    }
    return "";
}

std::string ContiguousBlocksAndUsed() {
    FrameArena arena(g_store + 5, 100);
    Model m{reinterpret_cast<std::uintptr_t>(g_store + 5), 100, 0};
    if (arena.Used() != 0 || arena.Capacity() != 100) return "새 아레나의 Used 기대 0, Capacity 기대 100";
    for (int i = 0; i < 10; ++i) {
        std::string d = Step(arena, m, 7, 1, "정렬 1, 크기 7 블록 " + Num(i + 1) + "번째: ");
        if (!d.empty()) return d;
    }
    // The default alignment is alignof(std::max_align_t).
    const std::uintptr_t want = m.Alloc(8, alignof(std::max_align_t));
    const std::uintptr_t got = reinterpret_cast<std::uintptr_t>(arena.Allocate(8));
    if (got != want) return "Allocate(8)(기본 정렬 alignof(std::max_align_t) = " + UNum(alignof(std::max_align_t)) + ") 기대 " + Where(m, want) + ", 결과 " + Where(m, got);
    if (arena.Used() != m.top) return "Allocate(8) 뒤 Used 기대 " + UNum(m.top) + ", 결과 " + UNum(arena.Used());
    return "";
}

std::string FullReturnsNullUnchanged() {
    FrameArena arena(g_store + 3, 64);
    Model m{reinterpret_cast<std::uintptr_t>(g_store + 3), 64, 0};
    std::string d = Step(arena, m, 50, 1, "");
    if (d.empty()) d = Step(arena, m, 20, 1, "남은 14바이트에 ");
    if (d.empty()) d = Step(arena, m, 14, 16, "패딩 때문에 들어가지 않는 ");
    if (d.empty()) d = Step(arena, m, 14, 1, "남은 14바이트를 정확히 채우는 ");
    if (d.empty()) d = Step(arena, m, 1, 1, "가득 찬 아레나에 ");
    if (!d.empty()) return d;
    if (arena.Used() != arena.Capacity()) return "가득 찬 아레나의 Used가 Capacity와 다름";
    FrameArena empty(nullptr, 0);
    if (empty.Allocate(1, 1) != nullptr || empty.Used() != 0) return "용량 0인 아레나(버퍼 nullptr)의 Allocate(1, 1)이 nullptr이 아니거나 Used가 0이 아님";
    return "";
}

std::string HugeSizeAndBadAlignment() {
    FrameArena arena(g_store + 1, 256);
    Model m{reinterpret_cast<std::uintptr_t>(g_store + 1), 256, 0};
    std::string d = Step(arena, m, 10, 1, "");
    const std::size_t big = static_cast<std::size_t>(-1);
    // top + padding + size wraps around to a small number for these sizes.
    if (d.empty()) d = Step(arena, m, big, 1, "SIZE_MAX 크기: ");
    if (d.empty()) d = Step(arena, m, big - 10, 16, "SIZE_MAX - 10 크기(덧셈이 넘치면 작은 수가 됨): ");
    if (d.empty()) d = Step(arena, m, big - 300, 4, "SIZE_MAX - 300 크기: ");
    if (d.empty()) d = Step(arena, m, 257, 1, "용량보다 큰 크기: ");
    if (d.empty()) d = Step(arena, m, 0, 8, "크기 0: ");
    const std::size_t badAligns[] = {0, 3, 6, 24, 48, 100};
    for (std::size_t a : badAligns) {
        if (d.empty()) d = Step(arena, m, 8, a, "2의 거듭제곱이 아닌 정렬: ");
    }
    if (d.empty()) d = Step(arena, m, 8, static_cast<std::size_t>(1) << 40, "만족할 수 없는 큰 정렬 2^40: ");
    if (d.empty()) d = Step(arena, m, 8, 8, "실패 뒤 정상 요청: ");
    return d;
}

std::string ResetReusesMemoryNoHeap() {
    const long allocs0 = judge_heap::g_allocs;
    FrameArena arena(g_store + 9, 2000);
    std::uintptr_t first[6];
    const std::size_t sizes[] = {100, 3, 48, 17, 256, 9};
    const std::size_t aligns[] = {16, 1, 64, 4, 32, 8};
    for (int i = 0; i < 6; ++i) {
        first[i] = reinterpret_cast<std::uintptr_t>(arena.Allocate(sizes[i], aligns[i]));
        if (first[i] == 0) return "빈 아레나(용량 2000)에서 " + Num(i + 1) + "번째 작은 Allocate가 nullptr을 반환함";
    }
    const std::size_t used = arena.Used();
    arena.Reset();
    if (arena.Used() != 0) return "Reset 뒤 Used 기대 0, 결과 " + UNum(arena.Used());
    for (int i = 0; i < 6; ++i) {
        const std::uintptr_t again = reinterpret_cast<std::uintptr_t>(arena.Allocate(sizes[i], aligns[i]));
        if (again == 0 || again != first[i]) return "Reset 뒤 같은 순서의 " + Num(i + 1) + "번째 Allocate가 처음과 다른 주소를 반환함 (메모리를 처음부터 다시 쓰지 않음)";
    }
    if (arena.Used() != used) return "Reset 뒤 같은 할당을 반복했는데 Used가 처음과 다름";
    // 3000 frames of temporary allocations.
    unsigned seed = 7u;
    for (int frame = 0; frame < 3000; ++frame) {
        arena.Reset();
        for (int k = 0; k < 12; ++k) {
            seed = seed * 1664525u + 1013904223u;
            void* p = arena.Allocate(1 + (seed >> 16) % 150, static_cast<std::size_t>(1) << ((seed >> 8) % 7));
            if (p == nullptr && k < 8) return "frame " + Num(frame) + ": Reset 직후의 작은 할당이 실패함";
            if (arena.Used() > arena.Capacity()) return "Used가 Capacity를 넘음";
        }
    }
    const long allocs = judge_heap::g_allocs - allocs0;
    if (allocs != 0) return "아레나 생성과 3000프레임 동안 힙 할당 " + Num(allocs) + "회 (기대 0회)";
    return "";
}

std::string MarkAndRewind() {
    FrameArena arena(g_store + 2, 512);
    Model m{reinterpret_cast<std::uintptr_t>(g_store + 2), 512, 0};
    std::string d = Step(arena, m, 24, 8, "");
    if (!d.empty()) return d;
    const std::size_t mark = arena.Mark();
    if (mark != m.top) return "Mark 기대 " + UNum(m.top) + ", 결과 " + UNum(mark);
    const Model atMark = m;
    d = Step(arena, m, 100, 16, "Mark 뒤 임시 ");
    if (d.empty()) d = Step(arena, m, 7, 1, "Mark 뒤 임시 ");
    if (!d.empty()) return d;
    arena.Rewind(mark);
    m = atMark;
    if (arena.Used() != mark) return "Rewind(mark) 뒤 Used 기대 " + UNum(mark) + ", 결과 " + UNum(arena.Used());
    d = Step(arena, m, 100, 16, "Rewind 뒤 같은 요청: ");
    if (!d.empty()) return d;
    // Nested scopes: inner first, then outer.
    const std::size_t outer = arena.Mark();
    const Model atOuter = m;
    d = Step(arena, m, 33, 4, "바깥 범위 ");
    const std::size_t inner = arena.Mark();
    const Model atInner = m;
    if (d.empty()) d = Step(arena, m, 64, 64, "안쪽 범위 ");
    if (!d.empty()) return d;
    arena.Rewind(inner);
    m = atInner;
    if (arena.Used() != inner) return "안쪽 Rewind 뒤 Used 기대 " + UNum(inner) + ", 결과 " + UNum(arena.Used());
    d = Step(arena, m, 5, 1, "안쪽 Rewind 뒤 ");
    if (!d.empty()) return d;
    arena.Rewind(outer);
    m = atOuter;
    if (arena.Used() != outer) return "바깥 Rewind 뒤 Used 기대 " + UNum(outer) + ", 결과 " + UNum(arena.Used());
    arena.Rewind(arena.Mark());
    if (arena.Used() != outer) return "Rewind(Mark())가 Used를 바꿈";
    return Step(arena, m, 400, 32, "바깥 Rewind 뒤 큰 요청: ");
}

long g_particleCtors = 0;
struct Particle {
    float x, y, vx, vy;
    int life;
    Particle(float px, float py, int l) : x(px), y(py), vx(0.5f), vy(-1.0f), life(l) { ++g_particleCtors; }
};
long g_transformCtors = 0;
struct alignas(32) Transform {
    float m[8];
    explicit Transform(float s) {
        for (int i = 0; i < 8; ++i) m[i] = s * static_cast<float>(i);
        ++g_transformCtors;
    }
};

std::string CreateConstructsInArena() {
    FrameArena arena(g_store + 7, 80);
    Model m{reinterpret_cast<std::uintptr_t>(g_store + 7), 80, 0};
    g_particleCtors = 0;
    g_transformCtors = 0;
    Particle* a = arena.Create<Particle>(1.5f, 2.5f, 30);
    std::uintptr_t want = m.Alloc(sizeof(Particle), alignof(Particle));
    if (reinterpret_cast<std::uintptr_t>(a) != want) return "Create<Particle> 기대 " + Where(m, want) + ", 결과 " + Where(m, reinterpret_cast<std::uintptr_t>(a));
    if (g_particleCtors != 1) return "Create<Particle>가 생성자를 " + Num(g_particleCtors) + "회 호출함 (기대 1회)";
    if (a->x != 1.5f || a->y != 2.5f || a->life != 30 || a->vx != 0.5f) return "Create<Particle>로 만든 객체의 값이 인자와 다름 (생성자에 인자를 전달하지 않음)";
    Transform* t = arena.Create<Transform>(2.0f);
    if (g_transformCtors != 1) return "Create<Transform>가 생성자를 " + Num(g_transformCtors) + "회 호출함 (기대 1회)";
    want = m.Alloc(sizeof(Transform), alignof(Transform));
    if (reinterpret_cast<std::uintptr_t>(t) != want) return "Create<Transform>(alignas(32)) 기대 " + Where(m, want) + ", 결과 " + Where(m, reinterpret_cast<std::uintptr_t>(t));
    for (int i = 0; i < 8; ++i) {
        if (t->m[i] != 2.0f * static_cast<float>(i)) return "Create<Transform>로 만든 객체의 값이 다름";
    }
    if (a->life != 30 || a->x != 1.5f) return "두 번째 Create 뒤 첫 객체의 값이 깨짐 (블록이 겹침)";
    // The 80-byte arena has no room left for a third 32-byte Transform.
    const std::size_t before = arena.Used();
    Transform* none = arena.Create<Transform>(1.0f);
    want = m.Alloc(sizeof(Transform), alignof(Transform));
    if (reinterpret_cast<std::uintptr_t>(none) != want) return "공간이 부족한 Create<Transform> 기대 " + Where(m, want) + ", 결과 " + Where(m, reinterpret_cast<std::uintptr_t>(none));
    if (arena.Used() != before) return "실패한 Create가 Used를 바꿈";
    if (g_transformCtors != 1) return "공간이 없어 실패한 Create<Transform>가 생성자를 호출함";
    Particle* b = arena.Create<Particle>(0.0f, 0.0f, 1);
    want = m.Alloc(sizeof(Particle), alignof(Particle));
    if (reinterpret_cast<std::uintptr_t>(b) != want) return "남은 공간의 Create<Particle> 기대 " + Where(m, want) + ", 결과 " + Where(m, reinterpret_cast<std::uintptr_t>(b));
    if (b == nullptr && g_particleCtors != 1) return "공간이 없어 실패한 Create가 생성자를 호출함";
    return "";
}

unsigned g_seed = 20261122u;
std::size_t Next(std::size_t mod) {
    g_seed = g_seed * 1664525u + 1013904223u;
    return static_cast<std::size_t>(g_seed >> 8) % mod;
}

std::string RandomVsReference() {
    const std::size_t aligns[] = {0, 1, 2, 3, 4, 8, 16, 24, 32, 64, 128, 256};
    for (int round = 0; round < 200; ++round) {
        const std::size_t offset = Next(64);
        const std::size_t cap = Next(3) == 0 ? Next(64) : Next(4000);
        FrameArena arena(g_store + offset, cap);
        Model m{reinterpret_cast<std::uintptr_t>(g_store + offset), cap, 0};
        std::size_t marks[64];
        Model models[64];
        int depth = 0;
        for (int step = 0; step < 80; ++step) {
            const std::size_t op = Next(20);
            const std::string who = "round " + Num(round) + " step " + Num(step) + " (오프셋 " + UNum(offset) + ", 용량 " + UNum(cap) + "): ";
            if (op < 13) {
                const std::size_t size = Next(5) == 0 ? Next(8) : Next(400);
                std::string d = Step(arena, m, size, aligns[Next(12)], who);
                if (!d.empty()) return d;
            } else if (op < 16) {
                if (depth < 64) {
                    marks[depth] = arena.Mark();
                    models[depth] = m;
                    if (marks[depth] != m.top) return who + "Mark 기대 " + UNum(m.top) + ", 결과 " + UNum(marks[depth]);
                    ++depth;
                }
            } else if (op < 19) {
                if (depth > 0) {
                    const int to = static_cast<int>(Next(static_cast<std::size_t>(depth)));
                    arena.Rewind(marks[to]);
                    m = models[to];
                    depth = to;
                    if (arena.Used() != m.top) return who + "Rewind 뒤 Used 기대 " + UNum(m.top) + ", 결과 " + UNum(arena.Used());
                }
            } else {
                arena.Reset();
                m.top = 0;
                depth = 0;
                if (arena.Used() != 0) return who + "Reset 뒤 Used가 0이 아님";
            }
        }
    }
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    AlignedAtEveryBaseOffset, ContiguousBlocksAndUsed, FullReturnsNullUnchanged, HugeSizeAndBadAlignment,
    ResetReusesMemoryNoHeap,  MarkAndRewind,           CreateConstructsInArena,  RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i] : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 2;  // a correct case finishes in milliseconds

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT)";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (버퍼 밖 주소를 반환했을 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Every case runs in its own child process, so a crash costs only that case.
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);
}

