#include <cstddef>
#include <cstdio>
#include <functional>
#include <memory>
#include <type_traits>
#include <utility>
#include <vector>

struct Enemy {
    float x, y;
    int hp;
};

struct World {
    std::vector<Enemy> enemies;

    // Non-template core: the spatial query is compiled once. It only writes the
    // indices of the enemies in range into a caller-provided buffer.
    std::size_t QueryRadius(float cx, float cy, float r, std::vector<std::size_t>& out) const {
        out.clear();
        for (std::size_t i = 0; i < enemies.size(); ++i) {
            const float dx = enemies[i].x - cx, dy = enemies[i].y - cy;
            if (dx * dx + dy * dy <= r * r) out.push_back(i);
        }
        return out.size();
    }
};

// (1) Hot path: a thin template over the core. Each lambda type instantiates only
// this small loop, and the call f(e) can be inlined because F is known here.
template <typename F>
void ForEachEnemyInRadius(World& w, float cx, float cy, float r, std::vector<std::size_t>& scratch, F&& f) {
    w.QueryRadius(cx, cy, r, scratch);
    for (std::size_t i : scratch) f(w.enemies[i]);
}

// (2) Non-owning callable reference (what std::function_ref standardises in C++26):
// a pointer to the callable plus a function pointer that knows its type. Valid only
// while the referenced callable is alive; never store it.
template <typename Sig>
class FunctionRef;
template <typename R, typename... Args>
class FunctionRef<R(Args...)> {
public:
    template <typename F, typename = std::enable_if_t<!std::is_same<std::decay_t<F>, FunctionRef>::value>>
    FunctionRef(F& f) noexcept  // lvalues only: binding a temporary would dangle at once
        : object_(static_cast<void*>(std::addressof(f))),
          call_([](void* o, Args... a) -> R { return (*static_cast<F*>(o))(std::forward<Args>(a)...); }) {}
    R operator()(Args... a) const { return call_(object_, std::forward<Args>(a)...); }

private:
    void* object_;
    R (*call_)(void*, Args...);
};

// (3) Stored callbacks: owned, type-erased, may be empty.
class Timers {
public:
    void After(float seconds, std::function<void()> fn) { pending_.push_back({seconds, std::move(fn)}); }
    void Tick(float dt) {
        for (Entry& e : pending_) {
            e.left -= dt;
            if (e.left <= 0.0f && e.fn) {
                std::function<void()> fn = std::move(e.fn);
                e.fn = nullptr;
                fn();
            }
        }
    }

private:
    struct Entry {
        float left;
        std::function<void()> fn;
    };
    std::vector<Entry> pending_;
};

// (4) Plugin boundary: a callback made only of C types (function pointer + user
// data), the shape a module boundary exported with extern "C" can carry.
typedef void (*EnemyCallback)(void* user, Enemy* e);
void ForEachEnemyC(World& w, EnemyCallback cb, void* user) {
    for (Enemy& e : w.enemies) cb(user, &e);
}

int main() {
    World w;
    for (int i = 0; i < 6; ++i) w.enemies.push_back(Enemy{static_cast<float>(i), 0.0f, 100});
    std::vector<std::size_t> scratch;

    ForEachEnemyInRadius(w, 0.0f, 0.0f, 2.5f, scratch, [](Enemy& e) { e.hp -= 30; });  // enemies 0..2

    int hits = 0;
    auto countHit = [&hits](Enemy& e) { hits += e.hp < 100 ? 1 : 0; };
    FunctionRef<void(Enemy&)> ref(countHit);
    for (Enemy& e : w.enemies) ref(e);

    Timers timers;
    timers.After(0.5f, [&w] { w.enemies[5].hp = 0; });
    timers.Tick(0.25f);
    timers.Tick(0.25f);

    ForEachEnemyC(w, [](void* user, Enemy* e) { *static_cast<int*>(user) += e->hp; }, &hits);

    std::function<void()> empty;
    bool threw = false;
    try {
        empty();
    } catch (const std::bad_function_call&) {
        threw = true;
    }
    std::printf("hp0 %d, hp5 %d, hits+hp sum %d, empty call threw %d\n", w.enemies[0].hp, w.enemies[5].hp, hits, threw ? 1 : 0);
    std::printf("sizeof: std::function<void()> %zu, FunctionRef %zu\n", sizeof(std::function<void()>), sizeof(FunctionRef<void(Enemy&)>));
    return 0;
}

