#include <cstddef>
#include <functional>
#include <map>
#include <string>
#include <string_view>

struct ConfigEntry {
    std::string_view key;
    std::string_view value;
};

namespace {

// Narrows the view; never copies characters.
std::string_view Trim(std::string_view s) {
    const std::size_t first = s.find_first_not_of(" \t");
    if (first == std::string_view::npos) return s.substr(s.size());  // empty, still inside s
    const std::size_t last = s.find_last_not_of(" \t");
    return s.substr(first, last - first + 1);
}

}  // namespace

// Reads the next entry of a settings line such as
//   "fov = 90; vsync=on ; # comment"
// and removes everything up to and including that entry (and its ';') from the
// front of `rest`.
//  - entries are separated by ';'
//  - from the first '#' to the end of the line is a comment
//  - key = text before the first '=', value = text after it; spaces and tabs
//    around both are trimmed
//  - blank segments, segments without '=' and segments with an empty key are skipped
// Returns false when no entry is left; `rest` is then empty.
// The views point into the caller's buffer.
bool NextConfigEntry(std::string_view& rest, ConfigEntry& entry) {
    while (!rest.empty()) {
        const std::size_t end = rest.find_first_of(";#");
        const std::string_view segment = rest.substr(0, end);  // npos: the whole rest
        if (end == std::string_view::npos || rest[end] == '#') {
            rest.remove_prefix(rest.size());  // a comment ends the line
        } else {
            rest.remove_prefix(end + 1);  // drop the segment and its ';'
        }
        const std::size_t eq = segment.find('=');
        if (eq == std::string_view::npos) continue;
        const std::string_view key = Trim(segment.substr(0, eq));
        if (key.empty()) continue;
        entry.key = key;
        entry.value = Trim(segment.substr(eq + 1));
        return true;
    }
    return false;
}

// Game settings that must outlive the line they were parsed from.
class Settings {
public:
    // Parses `line` and stores every entry; a later entry for the same key wins.
    // The caller may overwrite or destroy `line` right after this returns, so the
    // characters are copied here, exactly once per stored key and value.
    void Apply(std::string_view line) {
        ConfigEntry e;
        while (NextConfigEntry(line, e)) {
            const auto it = values_.find(e.key);  // no temporary std::string (std::less<>)
            if (it == values_.end()) {
                values_.emplace(std::string(e.key), std::string(e.value));
            } else {
                it->second.assign(e.value.data(), e.value.size());
            }
        }
    }

    // Value for `key`, or an empty view if the key is unknown.
    // The returned view stays valid until the next call to Apply.
    std::string_view Get(std::string_view key) const {
        const auto it = values_.find(key);
        if (it == values_.end()) return {};
        return it->second;  // views the string owned by the map
    }

    // Number of distinct keys stored.
    std::size_t Size() const { return values_.size(); }

private:
    // std::less<> is transparent: find() accepts a std::string_view directly.
    std::map<std::string, std::string, std::less<>> values_;
};

