#include <cerrno>
#include <csignal>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <map>
#include <new>
#include <string>
#include <string_view>
#include <vector>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

// Tracking, quarantining heap. Every block is registered with its address and size,
// and released memory is filled with 0xDD and never handed back to malloc. So a view
// that points into a released block can be recognised from its address alone (it is
// not inside any live block) and the judge never has to read it; and no new
// allocation can ever reuse that address.
namespace judge_heap {
const int kMaxBlocks = 60000;
const std::size_t kHeader = 16;
struct Block {
    std::uintptr_t begin;
    std::size_t size;
    bool live;
};
Block g_blocks[kMaxBlocks];
int g_count = 0;
long g_allocs = 0;
bool g_overflow = false;
void* Allocate(std::size_t n) {
    unsigned char* raw = static_cast<unsigned char*>(std::malloc(n + kHeader));
    if (raw == nullptr) throw std::bad_alloc();
    ++g_allocs;
    int index = -1;
    if (g_count < kMaxBlocks) {
        index = g_count++;
        g_blocks[index] = Block{reinterpret_cast<std::uintptr_t>(raw + kHeader), n, true};
    } else {
        g_overflow = true;
    }
    std::memcpy(raw, &index, sizeof(index));
    return raw + kHeader;
}
void Release(void* p) noexcept {
    if (p == nullptr) return;
    int index = -1;
    std::memcpy(&index, static_cast<unsigned char*>(p) - kHeader, sizeof(index));
    if (index >= 0 && index < g_count) {
        g_blocks[index].live = false;
        std::memset(p, 0xDD, g_blocks[index].size);
    }
}
// True if [p, p + n) lies inside one block that is still allocated.
bool InLiveBlock(const void* p, std::size_t n) {
    const std::uintptr_t a = reinterpret_cast<std::uintptr_t>(p);
    for (int i = 0; i < g_count; ++i) {
        const Block& b = g_blocks[i];
        if (b.live && a >= b.begin && a + n <= b.begin + b.size) return true;
    }
    return false;
}
}  // namespace judge_heap
void* operator new(std::size_t n) { return judge_heap::Allocate(n); }
void* operator new[](std::size_t n) { return judge_heap::Allocate(n); }
void operator delete(void* p) noexcept { judge_heap::Release(p); }
void operator delete[](void* p) noexcept { judge_heap::Release(p); }
void operator delete(void* p, std::size_t) noexcept { judge_heap::Release(p); }
void operator delete[](void* p, std::size_t) noexcept { judge_heap::Release(p); }

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "two-entries-in-order",
    "trims-spaces-and-tabs",
    "skips-blank-and-malformed",
    "comment-ends-the-line",
    "views-into-input-no-allocation",
    "settings-own-their-values",
    "get-does-not-allocate",
    "random-vs-reference",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

// Only used when the judge cannot run a case in its own process (see main).
void OnCrash(int) {
    for (int i = g_current; i < kCaseCount; ++i) {
        Emit("[FAIL] ");
        Emit(kCases[i]);
        Emit(i == g_current ? " :: 실행 중 비정상 종료\n" : " :: 앞선 케이스에서 프로그램이 중단됨\n");
    }
    _exit(0);
}

std::string Num(long long v) { return std::to_string(v); }
std::string Quote(std::string_view s) { return "\"" + std::string(s) + "\""; }

bool Inside(std::string_view part, const char* begin, std::size_t size) {
    const std::uintptr_t a = reinterpret_cast<std::uintptr_t>(part.data());
    const std::uintptr_t lo = reinterpret_cast<std::uintptr_t>(begin);
    return a >= lo && a + part.size() <= lo + size;
}

typedef std::vector<std::pair<std::string, std::string> > Pairs;

// Reference tokenizer: copies characters one by one, never uses string_view.
Pairs Reference(const std::string& line) {
    Pairs out;
    std::string text = line.substr(0, line.find('#'));
    std::size_t start = 0;
    while (start <= text.size()) {
        std::size_t end = text.find(';', start);
        if (end == std::string::npos) end = text.size();
        const std::string seg = text.substr(start, end - start);
        start = end + 1;
        const std::size_t eq = seg.find('=');
        if (eq == std::string::npos) continue;
        auto trim = [](const std::string& s) {
            std::size_t b = 0, e = s.size();
            while (b < e && (s[b] == ' ' || s[b] == '\t')) ++b;
            while (e > b && (s[e - 1] == ' ' || s[e - 1] == '\t')) --e;
            return s.substr(b, e - b);
        };
        const std::string key = trim(seg.substr(0, eq));
        if (key.empty()) continue;
        out.push_back(std::make_pair(key, trim(seg.substr(eq + 1))));
    }
    return out;
}

// Runs the learner's tokenizer over `line`. Every returned view is checked to lie
// inside `line` before a single character of it is read. `left` receives the length
// of `rest` after the final call (which must be 0).
std::string Tokenize(const std::string& line, Pairs& got, std::size_t& left) {
    got.clear();
    std::string_view rest(line);
    const char* const end = line.data() + line.size();
    ConfigEntry e;
    int guard = 0;
    while (NextConfigEntry(rest, e)) {
        if (++guard > static_cast<int>(line.size()) + 2) return "항목이 끝나지 않음 (rest가 줄어들지 않는 무한 반복)";
        if (!e.key.empty() && !Inside(e.key, line.data(), line.size()))
            return "key view가 입력 줄 버퍼 밖을 가리킴 (임시 문자열이나 복사본을 가리키는 view)";
        if (!e.value.empty() && !Inside(e.value, line.data(), line.size()))
            return "value view가 입력 줄 버퍼 밖을 가리킴 (임시 문자열이나 복사본을 가리키는 view)";
        if (!rest.empty() && (!Inside(rest, line.data(), line.size()) || rest.data() + rest.size() != end))
            return "NextConfigEntry 뒤의 rest가 입력 줄의 뒷부분(접미사)이 아님";
        got.push_back(std::make_pair(std::string(e.key), std::string(e.value)));
    }
    left = rest.size();
    return "";
}

std::string Describe(const Pairs& p) {
    std::string s = "[";
    for (std::size_t i = 0; i < p.size(); ++i) s += (i ? ", " : "") + Quote(p[i].first) + "=" + Quote(p[i].second);
    return s + "]";
}

std::string CheckLine(const std::string& line) {
    Pairs got;
    std::size_t left = 0;
    std::string d = Tokenize(line, got, left);
    if (!d.empty()) return "입력 " + Quote(line) + ": " + d;
    const Pairs want = Reference(line);
    if (got != want) return "입력 " + Quote(line) + ": 기대 " + Describe(want) + ", 결과 " + Describe(got);
    if (left != 0) return "입력 " + Quote(line) + ": false를 반환했는데 rest가 비어 있지 않음 (남은 길이 " + Num((long long)left) + ")";
    return "";
}

std::string CheckLines(const std::vector<std::string>& lines) {
    for (const std::string& line : lines) {
        std::string d = CheckLine(line);
        if (!d.empty()) return d;
    }
    return "";
}

std::string TwoEntries() { return CheckLines({"fov=90;vsync=on", "", "difficulty=hard"}); }

std::string TrimsSpacesAndTabs() {
    return CheckLines({"  resolution = 1920x1080 ;\t quality\t=\thigh  ;", "\tfov =  90\t", "name = Sir Robin of Camelot ;"});
}

std::string SkipsBlankAndMalformed() {
    return CheckLines({";; ;  \t ;", "=5; justtext ; name= ; a==b; key = value with spaces ", " = 7 ;  ; x=1"});
}

std::string CommentEndsTheLine() {
    return CheckLines({"fov=90 # default 75; vsync=off", "# only a comment", "a=1;b=2#;c=3", "theme=dark#", "#=1;b=2"});
}

std::string ViewsIntoInputNoAllocation() {
    std::string line;
    for (int i = 0; i < 40; ++i) {
        line += "  texture_streaming_budget_slot_" + Num(i) + " = value_long_enough_to_need_the_heap_" + Num(i * 7) + " ;";
    }
    line += " # trailing comment with a = sign; and a ; separator";
    std::string_view rest(line);
    ConfigEntry e;
    int count = 0;
    const long allocs0 = judge_heap::g_allocs;
    std::string bad;
    while (NextConfigEntry(rest, e)) {
        if (++count > 41) {
            bad = "항목이 끝나지 않음";
            break;
        }
        if (!Inside(e.key, line.data(), line.size()) || !Inside(e.value, line.data(), line.size())) {
            bad = "key 또는 value view가 입력 줄 버퍼 밖을 가리킴";
            break;
        }
    }
    const long allocs = judge_heap::g_allocs - allocs0;
    if (!bad.empty()) return bad;
    if (allocs != 0) return "항목 40개를 읽는 동안 힙 할당 " + Num(allocs) + "회 (기대 0회: 토큰을 std::string으로 복사하지 말 것)";
    if (count != 40) return "항목 수 기대 40, 결과 " + Num(count);
    return CheckLine(line);
}

// A non-empty view returned by Get may only point into memory that is still alive:
// a live heap block or the Settings object itself. Checked before any character is read.
bool Alive(const Settings& s, std::string_view v) {
    if (v.empty()) return true;
    return Inside(v, reinterpret_cast<const char*>(&s), sizeof(Settings)) || judge_heap::InLiveBlock(v.data(), v.size());
}

std::string CheckGet(const Settings& s, const std::string& key, const std::string& want, const std::string& who,
                     const char* oldBegin = nullptr, std::size_t oldSize = 0) {
    const std::string_view got = s.Get(key);
    if (want.empty()) {
        if (!got.empty()) return who + ": Get(" + Quote(key) + ") 기대 빈 view, 결과 길이 " + Num((long long)got.size());
        return "";
    }
    if (got.empty())
        return who + ": Get(" + Quote(key) + ") 기대 " + Quote(want) +
               ", 결과 빈 view (키나 값을 줄 버퍼를 가리키는 view로 저장했다면, 그 버퍼가 사라진 뒤에는 찾을 수 없음)";
    if (oldBegin != nullptr && Inside(got, oldBegin, oldSize))
        return who + ": Get(" + Quote(key) + ")이 Apply에 넘긴 줄 버퍼를 가리킴 (그 버퍼는 이미 해제됨: 값은 Settings가 복사해 소유해야 함)";
    if (!Alive(s, got))
        return who + ": Get(" + Quote(key) + ")이 Settings가 소유하지 않은 메모리를 가리키는 view를 반환함 (해제된 블록이나 사라진 임시 std::string 등)";
    if (got != want) return who + ": Get(" + Quote(key) + ") 기대 " + Quote(want) + ", 결과 " + Quote(got);
    return "";
}

std::string SettingsOwnTheirValues() {
    Settings s;
    const char* oldBegin = nullptr;
    std::size_t oldSize = 0;
    {
        // A line buffer that the loader reuses for the next line and then destroys.
        std::string line = "texture_streaming_budget_mb = 2048 ; shadow_quality_preset=ultra_high_detail; fov=90";
        s.Apply(line);
        oldBegin = line.data();
        oldSize = line.size();
        for (char& c : line) c = 'X';
    }
    std::string d = CheckGet(s, "texture_streaming_budget_mb", "2048", "줄 버퍼를 덮어쓰고 해제한 뒤", oldBegin, oldSize);
    if (d.empty()) d = CheckGet(s, "shadow_quality_preset", "ultra_high_detail", "줄 버퍼를 덮어쓰고 해제한 뒤", oldBegin, oldSize);
    if (d.empty()) d = CheckGet(s, "fov", "90", "줄 버퍼를 덮어쓰고 해제한 뒤", oldBegin, oldSize);
    if (!d.empty()) return d;
    if (s.Size() != 3) return "서로 다른 키 3개를 넣은 뒤 Size 기대 3, 결과 " + Num((long long)s.Size());
    s.Apply(std::string("fov = 100 ; fov=110 ; language = ko_KR_with_a_long_locale_suffix"));  // temporary line
    d = CheckGet(s, "fov", "110", "같은 키를 다시 넣은 뒤");
    if (d.empty()) d = CheckGet(s, "language", "ko_KR_with_a_long_locale_suffix", "임시 문자열로 Apply한 뒤");
    if (d.empty()) d = CheckGet(s, "shadow_quality_preset", "ultra_high_detail", "다른 줄을 Apply한 뒤");
    if (d.empty()) d = CheckGet(s, "unknown_key", "", "없는 키");
    if (!d.empty()) return d;
    if (s.Size() != 4) return "키 4개(fov 중복)를 넣은 뒤 Size 기대 4, 결과 " + Num((long long)s.Size());
    return "";
}

std::string GetDoesNotAllocate() {
    Settings s;
    s.Apply("streaming_pool_size_for_open_world_megabytes = 1536; ui_scale = 1.25 ;");
    static const char keyText[] = "streaming_pool_size_for_open_world_megabytes";
    const std::string_view key(keyText, sizeof(keyText) - 1);
    const long allocs0 = judge_heap::g_allocs;
    const std::string_view a = s.Get(key);
    const std::string_view b = s.Get(std::string_view("ui_scale"));
    const std::string_view c = s.Get(std::string_view("not_a_key_but_long_enough_to_need_the_heap"));
    const long allocs = judge_heap::g_allocs - allocs0;
    if (allocs != 0) return "Get 3회에 힙 할당 " + Num(allocs) + "회 (기대 0회: 조회하려고 키를 std::string으로 만들지 말 것)";
    if (!Alive(s, a) || !Alive(s, b)) return "Get이 Settings가 소유하지 않은 메모리(해제된 블록, 사라진 임시 객체, Apply에 넘긴 문자열)를 가리키는 view를 반환함";
    if (a != "1536") return "Get(긴 키) 기대 \"1536\", 결과 " + Quote(a);
    if (b != "1.25") return "Get(\"ui_scale\") 기대 \"1.25\", 결과 " + Quote(b);
    if (!c.empty()) return "없는 키의 Get이 빈 view가 아님";
    return "";
}

unsigned g_seed = 20261122u;
int Next(unsigned mod) {
    g_seed = g_seed * 1664525u + 1013904223u;
    return static_cast<int>((g_seed >> 16) % mod);
}

std::string Pad() {
    static const char* const pads[] = {"", " ", "  ", "\t", " \t "};
    return pads[Next(5)];
}

std::string RandomLine() {
    static const char* const keys[] = {"fov", "vsync", "texture_streaming_budget_mb", "shadow_quality_preset", "ui_scale",
                                       "master_volume", "x", "resolution"};
    static const char* const values[] = {"90", "on", "2048", "ultra_high_detail_mode_enabled", "1.25", "0", "", "1920x1080",
                                         "a=b", "two words"};
    std::string line;
    const int parts = Next(7);
    for (int i = 0; i < parts; ++i) {
        const int kind = Next(10);
        if (kind < 7) {
            line += Pad() + keys[Next(8)] + Pad() + "=" + Pad() + values[Next(10)] + Pad();
        } else if (kind == 7) {
            line += Pad() + "justtext" + Pad();
        } else if (kind == 8) {
            line += Pad() + "=" + values[Next(10)];
        } else {
            line += Pad();
        }
        if (i + 1 < parts || Next(2) == 0) line += ";";
    }
    if (Next(4) == 0) line += Pad() + "# note: fov=1; vsync=off";
    return line;
}

std::string RandomVsReference() {
    Settings s;
    std::map<std::string, std::string> model;
    for (int round = 0; round < 300; ++round) {
        const std::string line = RandomLine();
        std::string d = CheckLine(line);
        if (!d.empty()) return "round " + Num(round) + ": " + d;
        {
            std::string copy = line;
            s.Apply(copy);
            for (char& c : copy) c = '?';
        }
        for (const auto& kv : Reference(line)) model[kv.first] = kv.second;
        if (s.Size() != model.size())
            return "round " + Num(round) + ": Size 기대 " + Num((long long)model.size()) + ", 결과 " + Num((long long)s.Size());
        for (const auto& kv : model) {
            d = CheckGet(s, kv.first, kv.second, "round " + Num(round));
            if (!d.empty()) return d;
        }
        d = CheckGet(s, "missing_key", "", "round " + Num(round));
        if (!d.empty()) return d;
    }
    if (judge_heap::g_overflow) return "(채점기 내부) 힙 추적 한도 초과";
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    TwoEntries, TrimsSpacesAndTabs, SkipsBlankAndMalformed, CommentEndsTheLine, ViewsIntoInputNoAllocation,
    SettingsOwnTheirValues, GetDoesNotAllocate, RandomVsReference,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i] : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const int kVerdictWritten = 77;   // exit status of a case process that wrote its verdict line
const unsigned kCaseSeconds = 2;  // a correct case finishes in milliseconds

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): std::terminate 호출 등";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음 (rest를 줄이지 않는 무한 루프 가능성)";
        if (sig == SIGSEGV || sig == SIGBUS) return "유효하지 않은 메모리 접근으로 비정상 종료 (범위 밖 인덱스나 댕글링 view 가능성)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Every case runs in its own child process, so a crash or an endless loop costs
    // only that case.
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            const int signals[] = {SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT};
            for (int s : signals) std::signal(s, OnCrash);
            RunCase(i);
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);
}

