#include <condition_variable>
#include <cstddef>
#include <deque>
#include <mutex>
#include <thread>
#include <utility>
#include <vector>

struct Chunk {
    int id = 0;
    std::vector<int> tiles;  // filled by the loader
};

// The "disk". Read is slow and is only ever called on the loader thread.
class IChunkSource {
public:
    virtual ~IChunkSource() = default;
    virtual std::vector<int> Read(int chunkId) = 0;
};

// Streams world chunks on one background loader thread. Request, CollectReady and
// LoadedCount are called by the main thread every frame and must never wait for a
// Read to finish. Destroying the streamer waits for an in-flight Read to finish and
// drops the requests that have not started.
class ChunkStreamer {
public:
    explicit ChunkStreamer(IChunkSource& source) : source_(source), loader_([this] { LoaderLoop(); }) {}

    ~ChunkStreamer() {
        stop_ = true;
        loader_.join();
    }

    ChunkStreamer(const ChunkStreamer&) = delete;
    ChunkStreamer& operator=(const ChunkStreamer&) = delete;

    // Queues a chunk for loading.
    void Request(int chunkId) {
        std::lock_guard<std::mutex> lock(mutex_);
        requests_.push_back(chunkId);
        wake_.notify_one();
    }

    // Hands over every chunk whose tiles are completely loaded, in completion order.
    std::vector<Chunk> CollectReady() {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<Chunk> out;
        out.swap(ready_);
        return out;
    }

    // Number of chunks completely loaded so far (drives the loading bar).
    int LoadedCount() const { return loaded_; }

private:
    void LoaderLoop() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!stop_) {
            if (requests_.empty()) {
                wake_.wait(lock);
                continue;
            }
            const int id = requests_.front();
            requests_.pop_front();
            ready_.push_back(Chunk{id, {}});
            const std::size_t slot = ready_.size() - 1;
            lock.unlock();  // never block the main thread during a disk read
            std::vector<int> tiles = source_.Read(id);
            ready_[slot].tiles = std::move(tiles);
            lock.lock();
            ++loaded_;
        }
    }

    IChunkSource& source_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::deque<int> requests_;
    std::vector<Chunk> ready_;
    bool stop_ = false;
    int loaded_ = 0;
    std::thread loader_;  // declared last: starts only after every other member exists
};

problems.solutionCode:
#include <atomic>
#include <condition_variable>
#include <cstddef>
#include <deque>
#include <mutex>
#include <thread>
#include <utility>
#include <vector>

struct Chunk {
    int id = 0;
    std::vector<int> tiles;  // filled by the loader
};

// The "disk". Read is slow and is only ever called on the loader thread.
class IChunkSource {
public:
    virtual ~IChunkSource() = default;
    virtual std::vector<int> Read(int chunkId) = 0;
};

// Streams world chunks on one background loader thread. Request, CollectReady and
// LoadedCount are called by the main thread every frame and must never wait for a
// Read to finish. Destroying the streamer waits for an in-flight Read to finish and
// drops the requests that have not started.
//
// Shared state and who protects it:
//   requests_, ready_, stop_  -> mutex_ (read and written only while it is held)
//   loaded_                   -> std::atomic (read by the main thread without the lock)
//   the chunk being loaded    -> owned by the loader thread alone until it is published
class ChunkStreamer {
public:
    explicit ChunkStreamer(IChunkSource& source) : source_(source), loader_([this] { LoaderLoop(); }) {}

    ~ChunkStreamer() {
        {
            // stop_ is part of the wait predicate: change it under the mutex, even
            // though the write itself is tiny, so the loader cannot miss it between
            // checking the predicate and going to sleep.
            std::lock_guard<std::mutex> lock(mutex_);
            stop_ = true;
        }
        wake_.notify_all();
        loader_.join();  // waits for an in-flight Read; queued requests are dropped
    }

    ChunkStreamer(const ChunkStreamer&) = delete;
    ChunkStreamer& operator=(const ChunkStreamer&) = delete;

    // Queues a chunk for loading.
    void Request(int chunkId) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            requests_.push_back(chunkId);
        }
        wake_.notify_one();
    }

    // Hands over every chunk whose tiles are completely loaded, in completion order.
    std::vector<Chunk> CollectReady() {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<Chunk> out;
        out.swap(ready_);
        return out;
    }

    // Number of chunks completely loaded so far (drives the loading bar).
    int LoadedCount() const { return loaded_.load(); }

private:
    void LoaderLoop() {
        std::unique_lock<std::mutex> lock(mutex_);
        for (;;) {
            wake_.wait(lock, [this] { return stop_ || !requests_.empty(); });
            if (stop_) return;
            const int id = requests_.front();
            requests_.pop_front();
            lock.unlock();  // never block the main thread during a disk read
            // The chunk is a local object: no other thread can see it yet.
            Chunk chunk{id, source_.Read(id)};
            lock.lock();
            ready_.push_back(std::move(chunk));  // publish only complete chunks
            loaded_.fetch_add(1);
        }
    }

    IChunkSource& source_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::deque<int> requests_;
    std::vector<Chunk> ready_;
    bool stop_ = false;
    std::atomic<int> loaded_{0};
    std::thread loader_;  // declared last: starts only after every other member exists
};

tests.template:
#include <atomic>
#include <cerrno>
#include <chrono>
#include <condition_variable>
#include <csignal>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <memory>
#include <mutex>
#include <string>
#include <thread>
#include <vector>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#define main __user_main
{{USER_CODE}}
#undef main

namespace judge {

const char* const kCases[] = {
    "loads-requested-chunks",
    "no-partial-chunk-during-read",
    "main-thread-not-blocked-by-read",
    "request-wakes-idle-loader",
    "stress-every-chunk-once-in-order",
    "destroy-idle-streamer-promptly",
    "destroy-waits-for-read-drops-queue",
};
const int kCaseCount = sizeof(kCases) / sizeof(kCases[0]);
volatile std::sig_atomic_t g_current = 0;
const int kVerdictWritten = 77;  // exit status of a case process that wrote its verdict line

void Emit(const char* s) {
    ssize_t ignored = write(1, s, std::strlen(s));
    (void)ignored;
}

std::string Num(long long v) { return std::to_string(v); }

// Writes the verdict and ends the case process at once. Threads that are still
// parked or stuck are never resumed, so the code under test does not run any
// further after a failure has been seen.
[[noreturn]] void FailNow(const std::string& why) {
    const std::string line = std::string("[FAIL] ") + kCases[g_current] + " :: " + why + "\n";
    Emit(line.c_str());
    _exit(kVerdictWritten);
}

std::vector<int> TilesFor(int id) {
    std::vector<int> t(static_cast<std::size_t>(8 + id % 5));
    for (std::size_t i = 0; i < t.size(); ++i) t[i] = id * 1000 + static_cast<int>(i);
    return t;
}

// The test disk. Read can be parked on a chosen chunk id until the test releases
// it, which opens a window of known length in the middle of a load. The hand-off
// uses a mutex and a condition variable, so every observation the test makes
// while the loader is parked is ordered after what the loader did before Read.
class GateSource : public IChunkSource {
public:
    std::vector<int> Read(int chunkId) override {
        std::unique_lock<std::mutex> lock(m_);
        reads_.push_back(chunkId);
        if (chunkId == parkId_) {
            parked_ = true;
            cv_.notify_all();
            cv_.wait(lock, [this] { return released_; });
        }
        const bool slow = slowEvery_ > 0 && static_cast<int>(reads_.size()) % slowEvery_ == 0;
        lock.unlock();
        if (slow) std::this_thread::sleep_for(std::chrono::microseconds(300));
        return TilesFor(chunkId);
    }
    void ParkOn(int id) {
        std::lock_guard<std::mutex> lock(m_);
        parkId_ = id;
    }
    void SlowEvery(int n) {
        std::lock_guard<std::mutex> lock(m_);
        slowEvery_ = n;
    }
    bool WaitParked(int ms) {
        std::unique_lock<std::mutex> lock(m_);
        return cv_.wait_for(lock, std::chrono::milliseconds(ms), [this] { return parked_; });
    }
    void Release() {
        std::lock_guard<std::mutex> lock(m_);
        released_ = true;
        cv_.notify_all();
    }
    std::vector<int> Reads() {
        std::lock_guard<std::mutex> lock(m_);
        return reads_;
    }

private:
    std::mutex m_;
    std::condition_variable cv_;
    std::vector<int> reads_;
    int parkId_ = -1;
    int slowEvery_ = 0;
    bool parked_ = false;
    bool released_ = false;
};

// Runs fn on a helper thread and reports whether it returned within ms. On timeout
// the helper is left behind; the caller fails the case right away.
template <typename F>
bool FinishesWithin(int ms, F fn) {
    std::shared_ptr<std::atomic<bool> > done = std::make_shared<std::atomic<bool> >(false);
    std::thread helper([done, fn]() mutable {
        fn();
        done->store(true);
    });
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(ms);
    while (!done->load()) {
        if (std::chrono::steady_clock::now() > deadline) {
            helper.detach();
            return false;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    helper.join();
    return true;
}

void Settle() { std::this_thread::sleep_for(std::chrono::milliseconds(150)); }

void CheckChunk(const Chunk& c, int wantId, const std::string& who) {
    if (c.id != wantId) FailNow(who + "청크 id 기대 " + Num(wantId) + ", 결과 " + Num(c.id) + " (완료 순서가 요청 순서와 다름)");
    if (c.tiles != TilesFor(c.id))
        FailNow(who + "청크 " + Num(c.id) + "의 타일 수 " + Num((long long)c.tiles.size()) + " (기대 " + Num((long long)TilesFor(c.id).size()) +
                "): 타일을 다 읽기 전에 넘어온 청크");
}

// Collects until `count` chunks arrived or ms passed; checks ids and tiles on the way.
void CollectInOrder(ChunkStreamer& s, const std::vector<int>& ids, int ms, const std::string& who) {
    std::size_t got = 0;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(ms);
    while (got < ids.size()) {
        std::vector<Chunk> batch;
        if (!FinishesWithin(1500, [&] { batch = s.CollectReady(); })) FailNow(who + "CollectReady가 1.5초 안에 반환되지 않음");
        for (const Chunk& c : batch) {
            if (got >= ids.size()) FailNow(who + "요청하지 않은 청크 " + Num(c.id) + "이(가) 넘어옴 (같은 청크가 두 번 넘어왔을 가능성)");
            CheckChunk(c, ids[got], who);
            ++got;
        }
        if (got < ids.size() && std::chrono::steady_clock::now() > deadline)
            FailNow(who + Num(ms) + "ms 안에 청크 " + Num((long long)ids.size()) + "개 중 " + Num((long long)got) + "개만 도착함");
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
}

void DestroyWithin(ChunkStreamer* s, int ms, const std::string& who) {
    if (!FinishesWithin(ms, [s] { delete s; }))
        FailNow(who + "소멸자가 " + Num(ms) + "ms 안에 끝나지 않음: 일감을 기다리며 잠든 로더 스레드가 깨어나지 못함 (로더가 끝나지 않아 join이 멈춤)");
}

std::string LoadsRequestedChunks() {
    GateSource disk;
    ChunkStreamer* s = new ChunkStreamer(disk);
    const std::vector<int> ids = {11, 12, 13, 14, 15};
    for (int id : ids) s->Request(id);
    CollectInOrder(*s, ids, 2000, "청크 5개 요청: ");
    if (s->LoadedCount() != 5) FailNow("5개가 모두 도착한 뒤 LoadedCount 기대 5, 결과 " + Num(s->LoadedCount()));
    DestroyWithin(s, 1500, "모두 받은 뒤: ");
    return "";
}

std::string NoPartialChunkDuringRead() {
    GateSource disk;
    disk.ParkOn(7);
    ChunkStreamer* s = new ChunkStreamer(disk);
    s->Request(7);
    if (!disk.WaitParked(2000)) FailNow("Request(7) 뒤 2초 안에 Read(7)이 호출되지 않음");
    // The loader is now inside Read(7) and stays there until Release().
    std::vector<Chunk> early;
    int countDuringRead = -1;
    if (!FinishesWithin(1500, [&] {
            early = s->CollectReady();
            countDuringRead = s->LoadedCount();
        }))
        FailNow("Read(7)이 진행되는 동안 CollectReady/LoadedCount가 1.5초 안에 반환되지 않음 (Read 동안 락을 쥐고 있음)");
    for (const Chunk& c : early) {
        FailNow("Read(7)이 끝나기 전에 CollectReady가 청크 " + Num(c.id) + "을(를) 타일 " + Num((long long)c.tiles.size()) +
                "개인 채로 넘겨줌 (다 읽기 전에 공개됨)");
    }
    if (countDuringRead != 0) FailNow("Read(7)이 끝나기 전에 LoadedCount가 " + Num(countDuringRead) + " (기대 0)");
    disk.Release();
    CollectInOrder(*s, {7}, 2000, "Read(7)이 끝난 뒤: ");
    if (s->LoadedCount() != 1) FailNow("청크 7을 받은 뒤 LoadedCount 기대 1, 결과 " + Num(s->LoadedCount()));
    DestroyWithin(s, 1500, "청크 7을 받은 뒤: ");
    return "";
}

std::string MainThreadNotBlockedByRead() {
    GateSource disk;
    disk.ParkOn(3);
    ChunkStreamer* s = new ChunkStreamer(disk);
    s->Request(3);
    if (!disk.WaitParked(2000)) FailNow("Request(3) 뒤 2초 안에 Read(3)이 호출되지 않음");
    if (!FinishesWithin(1500, [&] {
            s->Request(4);
            (void)s->LoadedCount();
            (void)s->CollectReady();
        }))
        FailNow("Read(3)이 진행되는 동안 Request/LoadedCount/CollectReady가 1.5초 안에 반환되지 않음 (디스크 읽기 동안 락을 쥐고 있어 메인 스레드가 멈춤)");
    disk.Release();
    CollectInOrder(*s, {3, 4}, 2000, "Read(3)이 끝난 뒤: ");
    DestroyWithin(s, 1500, "두 청크를 받은 뒤: ");
    return "";
}

std::string RequestWakesIdleLoader() {
    GateSource disk;
    ChunkStreamer* s = new ChunkStreamer(disk);
    Settle();  // the loader is now waiting for work
    s->Request(21);
    CollectInOrder(*s, {21}, 2000, "한가한 로더에 Request(21): ");
    Settle();
    s->Request(22);
    s->Request(23);
    CollectInOrder(*s, {22, 23}, 2000, "다시 한가해진 로더에 Request 2개: ");
    DestroyWithin(s, 1500, "모두 받은 뒤: ");
    return "";
}

std::string StressEveryChunkOnceInOrder() {
    GateSource disk;
    disk.SlowEvery(9);
    ChunkStreamer* s = new ChunkStreamer(disk);
    std::vector<int> ids;
    std::size_t got = 0;
    int lastCount = 0;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(4000);
    for (int frame = 0; got < 400; ++frame) {
        if (frame < 100) {
            for (int k = 0; k < 4; ++k) {
                ids.push_back(1000 + frame * 4 + k);
                s->Request(ids.back());
            }
        }
        const std::vector<Chunk> batch = s->CollectReady();
        for (const Chunk& c : batch) {
            if (got >= ids.size()) FailNow("요청하지 않은 청크 " + Num(c.id) + "이(가) 넘어옴 (같은 청크가 두 번 넘어왔을 가능성)");
            CheckChunk(c, ids[got], "frame " + Num(frame) + ": ");
            ++got;
        }
        const int count = s->LoadedCount();
        if (count < lastCount) FailNow("frame " + Num(frame) + ": LoadedCount가 " + Num(lastCount) + "에서 " + Num(count) + "(으)로 줄어듦");
        lastCount = count;
        if (std::chrono::steady_clock::now() > deadline) FailNow("4초 안에 청크 400개 중 " + Num((long long)got) + "개만 도착함");
        std::this_thread::sleep_for(std::chrono::microseconds(100));
    }
    if (s->LoadedCount() != 400) FailNow("400개가 모두 도착한 뒤 LoadedCount 기대 400, 결과 " + Num(s->LoadedCount()));
    DestroyWithin(s, 1500, "400개를 받은 뒤: ");
    return "";
}

std::string DestroyIdleStreamerPromptly() {
    {
        GateSource disk;
        ChunkStreamer* s = new ChunkStreamer(disk);
        Settle();  // the loader is now waiting for work
        DestroyWithin(s, 1500, "요청 없이 기다리던 스트리머: ");
    }
    GateSource disk;
    ChunkStreamer* s = new ChunkStreamer(disk);
    s->Request(5);
    CollectInOrder(*s, {5}, 2000, "청크 1개 요청: ");
    Settle();
    DestroyWithin(s, 1500, "청크 1개를 받고 기다리던 스트리머: ");
    return "";
}

std::string DestroyWaitsForReadDropsQueue() {
    GateSource disk;
    disk.ParkOn(1);
    ChunkStreamer* s = new ChunkStreamer(disk);
    s->Request(1);
    s->Request(2);
    s->Request(3);
    if (!disk.WaitParked(2000)) FailNow("Request(1) 뒤 2초 안에 Read(1)이 호출되지 않음");
    std::shared_ptr<std::atomic<bool> > done = std::make_shared<std::atomic<bool> >(false);
    std::thread destroyer([s, done] {
        delete s;
        done->store(true);
    });
    std::this_thread::sleep_for(std::chrono::milliseconds(300));
    if (done->load()) {
        destroyer.detach();
        FailNow("Read(1)이 끝나기 전에 소멸자가 반환함 (로더 스레드를 기다리지 않으면 로더가 파괴된 멤버를 사용함)");
    }
    disk.Release();
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(1500);
    while (!done->load()) {
        if (std::chrono::steady_clock::now() > deadline) {
            destroyer.detach();
            FailNow("Read(1)이 끝난 뒤에도 소멸자가 1.5초 안에 끝나지 않음");
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    destroyer.join();
    const std::vector<int> reads = disk.Reads();
    if (reads.size() != 1 || reads[0] != 1)
        FailNow("소멸 중에 시작되지 않은 요청까지 읽음: Read 호출 " + Num((long long)reads.size()) + "회 (기대 1회, 청크 1만)");
    return "";
}

typedef std::string (*CaseFn)();
const CaseFn kFns[] = {
    LoadsRequestedChunks,        NoPartialChunkDuringRead,    MainThreadNotBlockedByRead,    RequestWakesIdleLoader,
    StressEveryChunkOnceInOrder, DestroyIdleStreamerPromptly, DestroyWaitsForReadDropsQueue,
};

// Runs one case and writes its verdict line.
void RunCase(int i) {
    std::string reason;
    try {
        reason = kFns[i]();
    } catch (const std::exception& e) {
        reason = std::string("예외가 밖으로 전파됨: ") + e.what();
    } catch (...) {
        reason = "알 수 없는 예외가 밖으로 전파됨";
    }
    std::string line = reason.empty() ? std::string("[PASS] ") + kCases[i] : std::string("[FAIL] ") + kCases[i] + " :: " + reason;
    line += "\n";
    Emit(line.c_str());
}

const unsigned kCaseSeconds = 7;  // a correct case finishes well under a second

// Why a case process ended without writing a verdict.
std::string DeathReason(int status) {
    if (WIFSIGNALED(status)) {
        const int sig = WTERMSIG(status);
        if (sig == SIGABRT) return "비정상 종료(SIGABRT): joinable한 std::thread의 파괴(std::terminate) 등";
        if (sig == SIGALRM) return Num(kCaseSeconds) + "초 안에 끝나지 않음";
        if (sig == SIGSEGV || sig == SIGBUS)
            return "유효하지 않은 메모리 접근으로 비정상 종료 (락 없이 공유 컨테이너를 고치거나, CollectReady가 비운 뒤의 인덱스로 쓴 경우 등)";
        return "신호 " + Num(sig) + "(으)로 비정상 종료";
    }
    if (WIFEXITED(status)) return "결과를 내기 전에 프로세스가 종료됨 (종료 코드 " + Num(WEXITSTATUS(status)) + ")";
    return "결과를 내기 전에 프로세스가 종료됨";
}

}  // namespace judge

int main() {
    using namespace judge;
    // Every case runs in its own child process: a crash, a hang or a thread left
    // behind costs only that case, and no thread outlives its case.
    for (int i = 0; i < kCaseCount; ++i) {
        g_current = i;
        const pid_t pid = fork();
        if (pid == 0) {
            alarm(kCaseSeconds);
            RunCase(i);
            _exit(kVerdictWritten);
        }
        if (pid < 0) {
            const std::string line = std::string("[FAIL] ") + kCases[i] + " :: 채점기가 케이스용 프로세스를 만들지 못함\n";
            Emit(line.c_str());
            continue;
        }
        int status = 0;
        pid_t waited;
        do {
            waited = waitpid(pid, &status, 0);
        } while (waited < 0 && errno == EINTR);
        if (waited == pid && WIFEXITED(status) && WEXITSTATUS(status) == kVerdictWritten) continue;
        const std::string line = std::string("[FAIL] ") + kCases[i] + " :: " + DeathReason(waited == pid ? status : 0) + "\n";
        Emit(line.c_str());
    }
    g_current = kCaseCount;
    _exit(0);
}
